window.AUDIO = {"built": "2026-10-18", "groups": [{"id": "talks", "title": "Talks"}, {"id": "T", "title": "Thesis"}, {"id": "M", "title": "Machine Learning and Perception"}, {"id": "A", "title": "AI for Simulation"}, {"id": "T-id", "title": "Tesis · Bahasa Indonesia"}, {"id": "M-id", "title": "ML&P · Bahasa Indonesia"}, {"id": "A-id", "title": "AI for Simulation · Bahasa Indonesia"}], "tracks": [{"id": "D", "group": "talks", "title": "Defense talk", "file": "tracks/D.mp3", "voice": "Andrew", "duration": 638.3, "sections": [{"title": "1 · Can a recorded flow carry a temperature that pushes back?", "paras": [[{"t0": 0.05, "t1": 1.25, "text": "Thank you for coming."}, {"t0": 1.25, "t1": 5.59, "text": "Imagine you could film how water moves through a tank, just once."}, {"t0": 5.59, "t1": 12.86, "text": "And then, every time you need an answer, you simply replay that film, instead of solving the physics again."}, {"t0": 12.86, "t1": 17.54, "text": "That is the idea behind recurrence CFD, and it is fast."}, {"t0": 17.54, "t1": 18.85, "text": "Really fast."}, {"t0": 18.85, "t1": 20.25, "text": "But there is a catch."}, {"t0": 20.25, "t1": 25.59, "text": "The method was built for things that just ride along with the flow, like a drop of dye."}, {"t0": 25.59, "t1": 27.28, "text": "Temperature is different."}, {"t0": 27.28, "t1": 28.91, "text": "Warm water rises."}, {"t0": 28.91, "t1": 33.26, "text": "So temperature pushes back on the very flow that carries it."}, {"t0": 33.26, "t1": 35.49, "text": "And that is my question today."}, {"t0": 35.49, "t1": 39.82, "text": "Can a recorded flow carry a temperature that pushes back?"}, {"t0": 39.82, "t1": 43.41, "text": "And if it cannot, where exactly does it break?"}]]}, {"title": "2 · A warm jet builds a front only five millimetres thick", "paras": [[{"t0": 44.74, "t1": 46.63, "text": "Let me show you the flow first."}, {"t0": 46.63, "t1": 48.27, "text": "This is my test case."}, {"t0": 48.27, "t1": 53.97, "text": "A small, closed tank, seventy-five millimetres wide, full of cold liquid."}, {"t0": 53.97, "t1": 59.02, "text": "At mid-height, a warm jet comes in, for 315 seconds."}, {"t0": 59.02, "t1": 60.57, "text": "Now watch what happens."}, {"t0": 60.57, "t1": 66.5, "text": "The warm water rises, spreads out under the lid, and slowly fills the tank from the top down."}, {"t0": 66.5, "t1": 70.82, "text": "Between the warm layer and the cold water below, a front forms."}, {"t0": 70.82, "t1": 72.49, "text": "And look how thin it is."}, {"t0": 72.49, "t1": 74.66, "text": "Only about five millimetres."}, {"t0": 74.66, "t1": 79.45, "text": "The flow is slow and smooth, with a Reynolds number of about one hundred."}, {"t0": 79.45, "t1": 83.56, "text": "So it is laminar, and I need no turbulence model."}, {"t0": 83.56, "t1": 90.4, "text": "And because the tank is closed, I can account for every joule that goes in and every joule that comes out."}, {"t0": 90.4, "t1": 94.3, "text": "One more detail, and please keep it in mind: the outlet."}, {"t0": 94.3, "t1": 96.04, "text": "It sits just below the front."}, {"t0": 96.04, "t1": 97.38, "text": "We will come back to it."}]]}, {"title": "3 · rCFD records the motion once and replays it about 260 times cheaper", "paras": [[{"t0": 98.71, "t1": 100.5, "text": "So how does the shortcut work?"}, {"t0": 100.5, "t1": 102.04, "text": "It has two steps."}, {"t0": 102.04, "t1": 105.19, "text": "First, we run the full simulation once."}, {"t0": 105.19, "t1": 111.68, "text": "And while it runs, we record, for every time step, where the fluid in each cell goes."}, {"t0": 111.68, "t1": 116.18, "text": "Think of a traffic camera that records the route of every car in a city."}, {"t0": 116.18, "t1": 117.91, "text": "Second, the replay."}, {"t0": 117.91, "t1": 122.28, "text": "It takes those stored routes and uses them to move the temperature."}, {"t0": 122.28, "t1": 127.86, "text": "It also mixes a little heat between neighbouring cells, and it keeps the total heat right."}, {"t0": 127.86, "t1": 131.33, "text": "But it never solves for velocity or pressure again."}, {"t0": 131.33, "t1": 133.18, "text": "That is why it is so cheap."}, {"t0": 133.18, "t1": 138.78, "text": "In my case, the full simulation needed 569 minutes of solver time."}, {"t0": 138.78, "t1": 141.26, "text": "One replay needs about two minutes."}, {"t0": 141.26, "t1": 144.58, "text": "That is roughly 260 times faster."}, {"t0": 144.58, "t1": 151.66, "text": "To be fair, the recording itself costs one full run, so the saving starts with the second replay."}, {"t0": 151.66, "t1": 153.61, "text": "Now, here is the problem."}, {"t0": 153.61, "t1": 155.38, "text": "Back to the traffic camera."}, {"t0": 155.38, "t1": 159.15, "text": "What if the parcels you move are so heavy that they change the traffic?"}, {"t0": 159.15, "t1": 160.43, "text": "That is temperature."}, {"t0": 160.43, "t1": 163.26, "text": "In the replay, the motion is fixed."}, {"t0": 163.26, "t1": 165.76, "text": "The temperature can no longer change it."}, {"t0": 165.76, "t1": 167.36, "text": "That feedback is cut."}]]}, {"title": "4 · One mixing knob cannot fix heat content and layer height at once", "paras": [[{"t0": 168.7, "t1": 171.37, "text": "The replay has one free setting."}, {"t0": 171.37, "t1": 177.63, "text": "After each move, it mixes a bit of heat across every face between two cells."}, {"t0": 177.63, "t1": 178.6, "text": "How much?"}, {"t0": 178.6, "t1": 181.67, "text": "That is a knob, and the user sets it by hand."}, {"t0": 181.67, "t1": 183.66, "text": "So my first question was simple."}, {"t0": 183.66, "t1": 185.04, "text": "What is the right setting?"}, {"t0": 185.04, "t1": 190.08, "text": "I tried seven values, from no extra mixing at all, up to strong mixing."}, {"t0": 190.08, "t1": 193.3, "text": "On the left, you see the mean temperature of the tank."}, {"t0": 193.3, "t1": 195.93, "text": "On the right, how high the heat sits."}, {"t0": 195.93, "t1": 197.35, "text": "And here is the trouble."}, {"t0": 197.35, "t1": 200.63, "text": "The heat content is best with no extra mixing."}, {"t0": 200.63, "t1": 203.83, "text": "The error is 1.07 kelvin."}, {"t0": 203.83, "t1": 208.54, "text": "But the height of the warm layer is best with a medium setting, around one half."}, {"t0": 208.54, "t1": 213.41, "text": "There, the error is only 0.068 millimetres."}, {"t0": 213.41, "t1": 215.73, "text": "So no single value gets both right."}, {"t0": 215.73, "t1": 217.2, "text": "And it gets worse."}, {"t0": 217.2, "t1": 222.14, "text": "The more you mix, the more heat the tank loses after the inflow stops."}, {"t0": 222.14, "t1": 227.68, "text": "With the strongest mixing, the tank ends 5.08 kelvin too cold."}, {"t0": 227.68, "t1": 230.5, "text": "So mixing does not just blur the picture."}, {"t0": 230.5, "t1": 232.94, "text": "It changes the energy in the tank."}, {"t0": 232.94, "t1": 234.95, "text": "The question is: why?"}]]}, {"title": "5 · The exchange smears the front, and the outlet below it drains the heat", "paras": [[{"t0": 236.28, "t1": 237.94, "text": "Here is the answer."}, {"t0": 237.94, "t1": 240.52, "text": "On the left, the reference simulation."}, {"t0": 240.52, "t1": 242.91, "text": "On the right, the standard replay."}, {"t0": 242.91, "t1": 246.21, "text": "Both use exactly the same recorded motion."}, {"t0": 246.21, "t1": 247.38, "text": "But look at the front."}, {"t0": 247.38, "t1": 253.21, "text": "In the reference, at 240 seconds, it is 4.5 millimetres thick."}, {"t0": 253.21, "t1": 256.19, "text": "In the replay, it is 19.3."}, {"t0": 256.19, "t1": 258.2, "text": "More than four times thicker."}, {"t0": 258.2, "t1": 259.55, "text": "So who is guilty?"}, {"t0": 259.55, "t1": 261.65, "text": "The recording, or the mixing?"}, {"t0": 261.65, "t1": 262.87, "text": "I tested that."}, {"t0": 262.87, "t1": 270.16, "text": "When I switch the mixing off and keep only the recorded maps, the front stays thin: 2.5 millimetres."}, {"t0": 270.16, "t1": 271.79, "text": "So the recording is fine."}, {"t0": 271.79, "t1": 274.54, "text": "It is the mixing step that smears the front."}, {"t0": 274.54, "t1": 277.85, "text": "Now, remember the outlet, just below the front."}, {"t0": 277.85, "t1": 280.57, "text": "A thick front reaches down to the outlet."}, {"t0": 280.57, "t1": 284.81, "text": "So warm water leaves the tank, and the heat leaves with it."}, {"t0": 284.81, "t1": 288.02, "text": "I checked this with the energy balance of the whole tank."}, {"t0": 288.02, "t1": 295.45, "text": "After the inflow, the smeared replay drains 4.6 kelvin of mean temperature through the outlet."}, {"t0": 295.45, "t1": 300.67, "text": "So a small numerical error at the front becomes a real error in the energy budget."}]]}, {"title": "6 · A bounded anti-diffusion rebuilds the front without new extremes", "paras": [[{"t0": 302.02, "t1": 304.49, "text": "So, can we undo the smearing?"}, {"t0": 304.49, "t1": 308.2, "text": "The obvious idea is to run diffusion backwards."}, {"t0": 308.2, "t1": 314.45, "text": "Diffusion makes things smooth, so negative diffusion should make them sharp again."}, {"t0": 314.45, "t1": 315.95, "text": "And it does, for a moment."}, {"t0": 315.95, "t1": 322.27, "text": "But it also makes every tiny wiggle grow, and the smallest wiggles grow the fastest."}, {"t0": 322.27, "t1": 323.65, "text": "You can see it on the left."}, {"t0": 323.65, "t1": 330.21, "text": "In this one-dimensional test, after just 21 steps, the field leaves the range of the data."}, {"t0": 330.21, "t1": 331.58, "text": "That is useless."}, {"t0": 331.58, "t1": 335.64, "text": "So I kept the useful part, and I stopped the dangerous part with a limit."}, {"t0": 335.64, "t1": 337.2, "text": "My rule is this."}, {"t0": 337.2, "t1": 343.45, "text": "Across each face, heat may move uphill, from the colder cell to the warmer one."}, {"t0": 343.45, "t1": 345.04, "text": "That sharpens the front."}, {"t0": 345.04, "t1": 350.04, "text": "But only so far that both cells stay inside the range of their neighbours."}, {"t0": 350.04, "t1": 354.81, "text": "No cell may get hotter than its hottest neighbour, or colder than its coldest one."}, {"t0": 354.81, "t1": 358.43, "text": "So no new hot spot and no new cold spot can appear."}, {"t0": 358.43, "t1": 365.93, "text": "And whatever heat leaves one cell enters the other, so energy is conserved, face by face."}, {"t0": 365.93, "t1": 371.9, "text": "This idea comes from flux-corrected transport, by Boris and Book, and by Zalesak."}, {"t0": 371.9, "t1": 373.36, "text": "One last detail."}, {"t0": 373.36, "t1": 380.61, "text": "The front is horizontal, so I let the correction act across the front, in the vertical direction, and not along it."}, {"t0": 380.61, "t1": 388.93, "text": "On the right, the limited version simply sharpens the front, from 8.8 cells to 0.9, and then it stops."}]]}, {"title": "7 · In the adiabatic tank the front returns to the width of the reference", "paras": [[{"t0": 390.29, "t1": 392.06, "text": "Does it work in the real tank?"}, {"t0": 392.06, "t1": 393.95, "text": "Here is the end of the run."}, {"t0": 393.95, "t1": 398.6, "text": "Without the correction, the front ends 15.7 millimetres wide."}, {"t0": 398.6, "t1": 405.64, "text": "With the correction, in its working range, it ends between 5.3 and 4.5 millimetres."}, {"t0": 405.64, "t1": 407.9, "text": "The reference has 5.0."}, {"t0": 407.9, "t1": 409.99, "text": "So the width is back."}, {"t0": 409.99, "t1": 411.66, "text": "You can see it in the pictures."}, {"t0": 411.66, "t1": 414.59, "text": "The row below shows the departure from the reference."}, {"t0": 414.59, "t1": 420.77, "text": "It shrinks as the strength grows, and it turns again when the correction gets too strong."}, {"t0": 420.77, "t1": 428.37, "text": "And the error of the mean temperature over the whole run drops from 1.46 kelvin to about 0.7."}, {"t0": 428.37, "t1": 430.41, "text": "I want to be honest about one point."}, {"t0": 430.41, "t1": 433.96, "text": "I chose the strength by comparing with this same reference."}, {"t0": 433.96, "t1": 436.14, "text": "So this shows what the correction can do."}, {"t0": 436.14, "t1": 440.53, "text": "Choosing the strength without a reference is still an open question."}]]}, {"title": "8 · Under a cooled lid the heat is right, but the layers separate too slowly", "paras": [[{"t0": 441.87, "t1": 444.45, "text": "So far, the lid was insulated."}, {"t0": 444.45, "t1": 447.48, "text": "Now I make it cold, and this changes the story."}, {"t0": 447.48, "t1": 450.75, "text": "Cold water sinks from the lid in plumes."}, {"t0": 450.75, "t1": 453.81, "text": "So now the temperature creates its own motion."}, {"t0": 453.81, "t1": 458.0, "text": "This is exactly the feedback that the replay cannot reproduce."}, {"t0": 458.0, "t1": 459.45, "text": "Let's see what happens."}, {"t0": 459.45, "t1": 463.34, "text": "Over the run, the tank cools by 9.62 kelvin."}, {"t0": 463.34, "t1": 468.33, "text": "The standard replay ends 0.66 kelvin too cold."}, {"t0": 468.33, "t1": 475.9, "text": "With the correction, it ends within 0.06 kelvin, again with a strength chosen against the reference."}, {"t0": 475.9, "t1": 478.16, "text": "So the heat content is right."}, {"t0": 478.16, "t1": 481.44, "text": "But look at the shaded band during the warm inflow."}, {"t0": 481.44, "t1": 485.66, "text": "While the tank fills, the layers separate too slowly."}, {"t0": 485.66, "t1": 490.14, "text": "I tried six different local corrections, and none of them moved this lag."}, {"t0": 490.14, "t1": 491.06, "text": "Why not?"}, {"t0": 491.06, "t1": 494.94, "text": "Because a local rule only moves heat between neighbours."}, {"t0": 494.94, "t1": 499.73, "text": "It can sharpen a front, but it cannot carry heat from one layer to another."}, {"t0": 499.73, "t1": 501.22, "text": "That needs transport."}, {"t0": 501.22, "t1": 507.25, "text": "So I read a vertical heat flux from the recording itself, and I added it to the replay."}, {"t0": 507.25, "t1": 513.5, "text": "It removes most of the lag, from 2.25 to 0.45 kelvin."}, {"t0": 513.5, "t1": 515.18, "text": "But it comes with a price."}, {"t0": 515.18, "t1": 518.98, "text": "The tank then ends 0.86 kelvin too cold."}]]}, {"title": "9 · A recording belongs to the flow regime it was made in", "paras": [[{"t0": 520.32, "t1": 523.33, "text": "Why can the recording not do this by itself?"}, {"t0": 523.33, "t1": 526.67, "text": "Because the cold lid makes a different kind of flow."}, {"t0": 526.67, "t1": 531.64, "text": "These maps compare every moment of a recording with every other moment."}, {"t0": 531.64, "t1": 539.06, "text": "After the inflow, the cooled flow keeps renewing itself, about ten times faster than the insulated one."}, {"t0": 539.06, "t1": 544.06, "text": "A recording made without the cold lid simply does not contain that motion."}, {"t0": 544.06, "t1": 545.98, "text": "Think of the traffic camera again."}, {"t0": 545.98, "t1": 551.4, "text": "A recording of a quiet Sunday will not tell you how the city moves in a snowstorm."}, {"t0": 551.4, "t1": 555.27, "text": "So a recording belongs to the flow regime it was made in."}]]}, {"title": "10 · What the evidence supports, and what it does not", "paras": [[{"t0": 556.59, "t1": 559.26, "text": "Let me be clear about what the evidence supports."}, {"t0": 559.26, "t1": 560.05, "text": "One."}, {"t0": 560.05, "t1": 565.61, "text": "There is no single best mixing setting, and the outlet below the front explains why."}, {"t0": 565.61, "t1": 566.33, "text": "Two."}, {"t0": 566.33, "t1": 572.49, "text": "A conservative, bounded correction rebuilds the front, without creating new extremes."}, {"t0": 572.49, "t1": 573.31, "text": "Three."}, {"t0": 573.31, "t1": 579.18, "text": "Under a cold lid, what remains is missing transport, not missing sharpness."}, {"t0": 579.18, "t1": 580.19, "text": "And four."}, {"t0": 580.19, "t1": 583.05, "text": "A recording belongs to its flow regime."}, {"t0": 583.05, "t1": 584.74, "text": "Now, what I have not shown."}, {"t0": 584.74, "t1": 588.22, "text": "I have not chosen the strength without the reference."}, {"t0": 588.22, "t1": 593.44, "text": "I have not tested other meshes, turbulent flows, or several phases."}, {"t0": 593.44, "t1": 598.59, "text": "The through-flow vessel study is still running, so I claim no result from it."}, {"t0": 598.59, "t1": 603.32, "text": "And I have not shown that a recorded flux transfers to other cases."}]]}, {"title": "11 · Contribution in three lines", "paras": [[{"t0": 604.66, "t1": 606.73, "text": "So, three things to take home."}, {"t0": 606.73, "t1": 607.55, "text": "One."}, {"t0": 607.55, "t1": 615.86, "text": "I measured the trade-off of the standard replay, and I found its cause: a smeared front that drains heat through the outlet."}, {"t0": 615.86, "t1": 616.57, "text": "Two."}, {"t0": 616.57, "t1": 623.57, "text": "I built a correction that sharpens the front within physical bounds, without creating new extremes."}, {"t0": 623.57, "t1": 624.4, "text": "Three."}, {"t0": 624.4, "t1": 626.6, "text": "I found where local fixes stop."}, {"t0": 626.6, "t1": 631.04, "text": "What remains is transport, and a recording belongs to its regime."}, {"t0": 631.04, "t1": 635.25, "text": "A fast simulation is only useful when we know its error."}, {"t0": 635.25, "t1": 637.3, "text": "That is what this thesis measures."}, {"t0": 637.3, "t1": 638.18, "text": "Thank you."}]]}]}, {"id": "I", "group": "talks", "title": "Industry talk", "file": "tracks/I.mp3", "voice": "Andrew", "duration": 402.9, "sections": [{"title": "1 · Thermal processes are fast in flow and slow in temperature", "paras": [[{"t0": 0.05, "t1": 1.35, "text": "Thank you for having me."}, {"t0": 1.35, "t1": 4.47, "text": "Many thermal processes share one feature."}, {"t0": 4.47, "t1": 6.73, "text": "There are two clocks running at the same time."}, {"t0": 6.73, "t1": 8.78, "text": "The flow is the fast clock."}, {"t0": 8.78, "t1": 11.07, "text": "It finds its pattern in seconds."}, {"t0": 11.07, "t1": 13.33, "text": "The temperature is the slow clock."}, {"t0": 13.33, "t1": 16.86, "text": "It keeps changing for minutes, sometimes for hours."}, {"t0": 16.86, "t1": 23.63, "text": "But a normal simulation has to follow the fast clock all the time, even when nothing new happens in the flow."}, {"t0": 23.63, "t1": 25.01, "text": "That is expensive."}, {"t0": 25.01, "t1": 27.67, "text": "And that is where my research starts."}]]}, {"title": "2 · Simulating hours of a process is the expensive part", "paras": [[{"t0": 28.99, "t1": 30.31, "text": "Let me put a number on it."}, {"t0": 30.31, "t1": 39.48, "text": "In my test case, about ten minutes of flow, in a tank of seventy-five millimetres, took 569 minutes of solver time."}, {"t0": 39.48, "t1": 41.27, "text": "That is more than nine hours."}, {"t0": 41.27, "t1": 42.58, "text": "Where does that time go?"}, {"t0": 42.58, "t1": 45.69, "text": "Mostly into velocity and pressure."}, {"t0": 45.69, "t1": 52.55, "text": "In every time step, the solver couples them again, even after the flow has settled into its pattern."}, {"t0": 52.55, "t1": 55.61, "text": "The temperature itself is cheap to carry."}, {"t0": 55.61, "t1": 58.16, "text": "So the engineering question is simple."}, {"t0": 58.16, "t1": 63.4, "text": "Can we keep the temperature physics, and stop paying for the flow every time?"}, {"t0": 63.4, "t1": 65.19, "text": "The answer depends on one thing."}, {"t0": 65.19, "t1": 67.6, "text": "Does the temperature change the flow?"}]]}, {"title": "3 · Record the flow once, replay it for the temperature", "paras": [[{"t0": 68.93, "t1": 71.77, "text": "There is a method that does exactly this."}, {"t0": 71.77, "t1": 76.16, "text": "It is called recurrence CFD, and it works in three steps."}, {"t0": 76.16, "t1": 78.7, "text": "Step one: simulate once."}, {"t0": 78.7, "t1": 83.36, "text": "One full simulation, with velocity, pressure and temperature."}, {"t0": 83.36, "t1": 85.73, "text": "Step two: record the motion."}, {"t0": 85.73, "t1": 90.29, "text": "For every second, we store where the fluid in each cell goes."}, {"t0": 90.29, "t1": 91.84, "text": "Six hundred frames."}, {"t0": 91.84, "t1": 96.5, "text": "Think of a traffic camera that records the route of every car in a city."}, {"t0": 96.5, "t1": 98.61, "text": "Step three: replay."}, {"t0": 98.61, "t1": 105.1, "text": "We use those stored routes to move the temperature, and we never solve for velocity or pressure again."}, {"t0": 105.1, "t1": 109.02, "text": "In my case, one replay takes about two minutes."}, {"t0": 109.02, "t1": 112.17, "text": "That is roughly 260 times cheaper."}, {"t0": 112.17, "t1": 118.54, "text": "To be fair, you need the full simulation first, so the saving starts with the second replay."}, {"t0": 118.54, "t1": 119.93, "text": "But there is a catch."}, {"t0": 119.93, "t1": 124.0, "text": "What if the parcels you move are so heavy that they change the traffic?"}, {"t0": 124.0, "t1": 125.22, "text": "That is temperature."}, {"t0": 125.22, "t1": 126.86, "text": "Warm water rises."}, {"t0": 126.86, "t1": 132.46, "text": "In the replay, the flow is fixed, so the temperature can no longer change it."}]]}, {"title": "4 · A small tank where the temperature pushes back", "paras": [[{"t0": 133.83, "t1": 137.66, "text": "So I built a case where the temperature does change the flow."}, {"t0": 137.66, "t1": 142.81, "text": "A warm jet enters a closed tank, for 315 seconds."}, {"t0": 142.81, "t1": 147.99, "text": "It builds a warm layer on top of cold water, with a thin front in between."}, {"t0": 147.99, "t1": 150.69, "text": "On the left, the full simulation."}, {"t0": 150.69, "t1": 153.96, "text": "On the right, the replay with its standard settings."}, {"t0": 153.96, "t1": 155.46, "text": "Same recorded flow."}, {"t0": 155.46, "t1": 156.71, "text": "Now look at the front."}, {"t0": 156.71, "t1": 160.96, "text": "In the full simulation, it is about five millimetres thick."}, {"t0": 160.96, "t1": 164.27, "text": "In the replay, it is about four times thicker."}, {"t0": 164.27, "t1": 170.22, "text": "The tank is laminar and closed, so every joule in and out can be accounted for."}, {"t0": 170.22, "t1": 173.57, "text": "That makes it a clean place to ask the real question."}, {"t0": 173.57, "t1": 175.14, "text": "Where does this error come from?"}]]}, {"title": "5 · The outlet below the front turns a smeared front into a heat leak", "paras": [[{"t0": 176.47, "t1": 179.52, "text": "I did not tune numbers until the picture looked right."}, {"t0": 179.52, "t1": 180.88, "text": "I followed the heat."}, {"t0": 180.88, "t1": 187.06, "text": "First, the whole tank: no setting of the mixing knob gets both the heat and the layer height right."}, {"t0": 187.06, "t1": 188.23, "text": "Then the outlet."}, {"t0": 188.23, "t1": 192.0, "text": "I recovered its temperature from the energy balance of the tank."}, {"t0": 192.0, "t1": 193.46, "text": "And here is the key."}, {"t0": 193.46, "t1": 196.11, "text": "The outlet sits just below the front."}, {"t0": 196.11, "t1": 204.29, "text": "So a thick front puts warm water at the outlet, and after the inflow, 4.6 kelvin of mean temperature drains away."}, {"t0": 204.29, "t1": 207.66, "text": "Finally, one face between two cells."}, {"t0": 207.66, "t1": 211.24, "text": "With the recorded motion alone, the front stays thin."}, {"t0": 211.24, "t1": 213.68, "text": "With the mixing step, it gets thick."}, {"t0": 213.68, "t1": 215.37, "text": "So the recording is fine."}, {"t0": 215.37, "t1": 217.56, "text": "The mixing step is the problem."}, {"t0": 217.56, "t1": 219.13, "text": "That is how I like to work."}, {"t0": 219.13, "t1": 222.86, "text": "Follow the energy, until the error has an address."}]]}, {"title": "6 · A correction that respects physics", "paras": [[{"t0": 224.19, "t1": 227.39, "text": "Once the cause is local, the fix can be local too."}, {"t0": 227.39, "t1": 230.0, "text": "So I built a correction that respects physics."}, {"t0": 230.0, "t1": 235.15, "text": "It moves heat back, from the colder cell to the warmer one, to sharpen the front."}, {"t0": 235.15, "t1": 242.01, "text": "But each face only moves as much as both cells can take, while they stay within the range of their neighbours."}, {"t0": 242.01, "t1": 248.02, "text": "So the total heat stays exactly the same, and no new hot spot or cold spot can appear."}, {"t0": 248.02, "t1": 251.26, "text": "For an industrial model, I think this matters."}, {"t0": 251.26, "t1": 256.36, "text": "A correction that you cannot trust to keep the energy is not a correction."}, {"t0": 256.36, "t1": 257.3, "text": "The result?"}, {"t0": 257.3, "t1": 261.14, "text": "The front goes back from almost sixteen millimetres to about five."}, {"t0": 261.14, "t1": 263.19, "text": "The full simulation has five."}, {"t0": 263.19, "t1": 264.32, "text": "One honest note."}, {"t0": 264.32, "t1": 268.04, "text": "I chose the strength by comparing with the full simulation."}, {"t0": 268.04, "t1": 271.56, "text": "Choosing it without one is the next research step."}]]}, {"title": "7 · Knowing the limit is part of the result", "paras": [[{"t0": 272.88, "t1": 274.59, "text": "Then I made the problem harder."}, {"t0": 274.59, "t1": 276.01, "text": "I made the lid cold."}, {"t0": 276.01, "t1": 277.34, "text": "Look at the plumes."}, {"t0": 277.34, "t1": 282.87, "text": "Cold water falls from the lid, so now the temperature creates its own motion."}, {"t0": 282.87, "t1": 285.59, "text": "The correction still gets the heat content right."}, {"t0": 285.59, "t1": 291.17, "text": "It ends within 0.06 kelvin, on almost ten kelvin of cooling."}, {"t0": 291.17, "t1": 297.7, "text": "But while the tank fills, the layers separate too slowly, and no local fix changes that."}, {"t0": 297.7, "t1": 299.93, "text": "The missing piece is transport."}, {"t0": 299.93, "t1": 301.65, "text": "And there is a bigger lesson."}, {"t0": 301.65, "t1": 306.0, "text": "These plumes are a motion that the insulated recording never saw."}, {"t0": 306.0, "t1": 309.68, "text": "A recording only covers the kind of flow it was made in."}, {"t0": 309.68, "t1": 311.63, "text": "Think of the traffic camera again."}, {"t0": 311.63, "t1": 317.08, "text": "A recording of a quiet Sunday will not tell you how the city moves in a snowstorm."}, {"t0": 317.08, "t1": 321.05, "text": "For me, knowing where a method stops is part of the result."}, {"t0": 321.05, "t1": 322.43, "text": "It is not a failure."}]]}, {"title": "8 · Where scientific machine learning could fit", "paras": [[{"t0": 323.76, "t1": 326.65, "text": "This is where I see room for machine learning."}, {"t0": 326.65, "t1": 331.04, "text": "Three directions, and each one comes from a weakness that I measured."}, {"t0": 331.04, "t1": 334.05, "text": "I want to be clear: none of them is tested yet."}, {"t0": 334.05, "t1": 335.81, "text": "First, learn the mixing."}, {"t0": 335.81, "t1": 338.74, "text": "Today, a person sets the knob by hand."}, {"t0": 338.74, "t1": 344.45, "text": "A model could learn it from recorded data, and we would check it against the full simulation."}, {"t0": 344.45, "t1": 346.69, "text": "Second, switch by regime."}, {"t0": 346.69, "t1": 353.96, "text": "One recording covers one kind of flow, so a replay could watch its own state and pick the right recording."}, {"t0": 353.96, "t1": 355.96, "text": "Third, physics as tests."}, {"t0": 355.96, "t1": 360.37, "text": "Any fast model, learned or not, should pass simple checks."}, {"t0": 360.37, "t1": 361.81, "text": "Does it keep the energy?"}, {"t0": 361.81, "t1": 364.3, "text": "Does it stay within physical limits?"}, {"t0": 364.3, "t1": 377.37, "text": "And before anyone uses this on a real process, three things must be shown: reference data for each operating state, recordings that cover what the process will see, and checks against real measurements."}]]}, {"title": "9 · How I work, and the next question", "paras": [[{"t0": 378.7, "t1": 380.48, "text": "Let me close with how I work."}, {"t0": 380.48, "t1": 381.3, "text": "One."}, {"t0": 381.3, "t1": 384.61, "text": "I follow the energy until the error has a location."}, {"t0": 384.61, "t1": 385.33, "text": "Two."}, {"t0": 385.33, "t1": 387.7, "text": "I fix it within physical bounds."}, {"t0": 387.7, "t1": 388.52, "text": "Three."}, {"t0": 388.52, "t1": 392.02, "text": "I state clearly where the method stops, with numbers."}, {"t0": 392.02, "t1": 393.79, "text": "And my next question is this."}, {"t0": 393.79, "t1": 400.13, "text": "Can the replay choose its own correction strength, without a full simulation to compare with?"}, {"t0": 400.13, "t1": 401.02, "text": "Thank you."}, {"t0": 401.02, "t1": 402.81, "text": "I look forward to your questions."}]]}]}, {"id": "A1", "group": "A", "title": "A1 · Recurrence CFD, as Professor Pirker teaches it", "file": "tracks/A1.mp3", "voice": "Ava", "duration": 401.3, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 3.48, "text": "Recurrence CFD, as Professor Pirker teaches it."}], [{"t0": 4.13, "t1": 10.2, "text": "Professor Pirker is your supervisor, and he taught Numerical Methods in Fluid Mechanics."}, {"t0": 10.2, "t1": 15.57, "text": "Expect him to stay close to recurrence CFD and to the figures of your thesis."}, {"t0": 15.57, "t1": 25.26, "text": "In this episode, we go through recurrence CFD the way his lecture tells it, so that your answers sound like his course, and then we link every idea to your own work."}]]}, {"title": "Why recurrence CFD at all?", "paras": [[{"t0": 26.57, "t1": 28.39, "text": "Start with the big picture."}, {"t0": 28.39, "t1": 33.75, "text": "Many industrial flows run for a long time, and they show recurring patterns."}, {"t0": 33.75, "t1": 39.12, "text": "Think of bubble columns, fluidized beds, or turbulent stirred vessels."}, {"t0": 39.12, "t1": 46.01, "text": "Solving momentum and pressure for all that time is wasteful, once the flow keeps repeating itself."}], [{"t0": 46.68, "t1": 52.01, "text": "So recurrence CFD makes a bold prediction: reuse the recorded flow."}, {"t0": 52.01, "t1": 58.76, "text": "And then it corrects that prediction with physics, wherever the reuse breaks something, for example the mass balance."}], [{"t0": 59.42, "t1": 62.8, "text": "Here is a lovely way to connect it to the lecture."}, {"t0": 62.8, "t1": 65.78, "text": "The SIMPLE algorithm does the same thing."}, {"t0": 65.78, "t1": 71.55, "text": "It guesses a pressure, solves the velocity, and then corrects the pressure from continuity."}, {"t0": 71.55, "t1": 76.32, "text": "Recurrence CFD guesses the flow from the recording, and then corrects it."}, {"t0": 76.32, "t1": 79.77, "text": "Bold prediction, then physics-based correction."}, {"t0": 79.77, "t1": 83.15, "text": "If you say that sentence, you are speaking his language."}]]}, {"title": "Flow-based versus transport-based", "paras": [[{"t0": 84.45, "t1": 86.4, "text": "There are two families."}, {"t0": 86.4, "t1": 99.68, "text": "Flow-based recurrence CFD, from Lichtenegger and Pirker in 2016, stitches recorded flow sequences into a long artificial flow, and it still solves a transport equation on top."}, {"t0": 99.68, "t1": 103.94, "text": "That is about 100 times faster than full CFD."}], [{"t0": 104.59, "t1": 111.4, "text": "Transport-based recurrence CFD, from Pirker and Lichtenegger in 2018, goes further."}, {"t0": 111.4, "t1": 114.39, "text": "It solves no transport equation at all."}, {"t0": 114.39, "t1": 117.73, "text": "It replaces it by cell shifts and face swaps."}, {"t0": 117.73, "t1": 127.63, "text": "The lecture example is a steel ladle: 26 hours of full CFD, against 1.6 seconds of transport-based recurrence CFD."}], [{"t0": 128.3, "t1": 134.74, "text": "Your thesis uses the transport-based form, plus a correction hook and the conservation constraint."}]]}, {"title": "The recurrence norm, matrix, plateau and prominence", "paras": [[{"t0": 136.05, "t1": 140.53, "text": "The recurrence norm measures how different two recorded states are."}, {"t0": 140.53, "t1": 145.76, "text": "Compute it for all pairs, normalise it, and you get the recurrence matrix."}], [{"t0": 146.41, "t1": 149.09, "text": "Now take one row of that matrix."}, {"t0": 149.09, "t1": 154.06, "text": "It starts at zero on the diagonal, because a state is identical to itself."}, {"t0": 154.06, "t1": 157.88, "text": "Then it rises, and oscillates around a plateau."}, {"t0": 157.88, "t1": 164.17, "text": "If the row dips deep below the plateau, the flow comes back to a state similar to an earlier one."}, {"t0": 164.17, "t1": 167.6, "text": "That is recurrence, and the replay can jump there."}, {"t0": 167.6, "t1": 172.18, "text": "The prominence measures how deep those dips are, relative to the plateau."}], [{"t0": 172.84, "t1": 178.48, "text": "The method asks for a prominence of about 0.05 to 0.1."}, {"t0": 178.48, "t1": 182.6, "text": "Your tank has a median of 0.028."}, {"t0": 182.6, "t1": 186.95, "text": "So the dips are shallow, and the replay plays the frames in order."}, {"t0": 186.95, "t1": 195.67, "text": "Say it plainly: my flow is not recurrent, and that is fine, because the saving comes from not solving velocity and pressure."}]]}, {"title": "The three bold failures", "paras": [[{"t0": 196.98, "t1": 202.67, "text": "The lecture names three bold failures of recurrence CFD, each with its correction."}, {"t0": 202.67, "t1": 205.48, "text": "Learn them as a list of three pairs."}], [{"t0": 206.15, "t1": 208.57, "text": "First, mass imbalance."}, {"t0": 208.57, "t1": 211.85, "text": "Cell shifts do not conserve mass locally."}, {"t0": 211.85, "t1": 216.88, "text": "So a global monitor corrects the total, with mass-acting face swaps."}], [{"t0": 217.54, "t1": 220.14, "text": "Second, unphysical diffusion."}, {"t0": 220.14, "t1": 223.9, "text": "A fixed number of swaps gives the same mixing everywhere."}, {"t0": 223.9, "t1": 226.79, "text": "So the swaps should follow the local mixing."}], [{"t0": 227.45, "t1": 229.69, "text": "Third, too little recurrence."}, {"t0": 229.69, "t1": 234.82, "text": "In large domains, frames that match globally do not match locally."}, {"t0": 234.82, "t1": 240.22, "text": "So the domain is split into recurrence islands, each with its own matrix."}], [{"t0": 240.89, "t1": 243.47, "text": "And your thesis touches all three."}, {"t0": 243.47, "t1": 246.4, "text": "The conservation constraint is the first."}, {"t0": 246.4, "t1": 249.15, "text": "The recorded diffusivity is the second."}, {"t0": 249.15, "t1": 252.42, "text": "And your flow, with too little prominence, is the third."}]]}, {"title": "When does it work, and when does it fail?", "paras": [[{"t0": 253.73, "t1": 258.27, "text": "It works when the motion repeats, and when the scalar does not change the flow."}, {"t0": 258.27, "t1": 263.72, "text": "It fails when the scalar drives the flow, or when the operating state changes."}, {"t0": 263.72, "t1": 269.67, "text": "In a new state, the recording simply does not contain the motion that this state would produce."}], [{"t0": 270.34, "t1": 271.84, "text": "That is your result."}, {"t0": 271.84, "t1": 280.27, "text": "Under the cooled lid, the flow keeps renewing itself with cold plumes, a motion that the insulated recording never saw."}, {"t0": 280.27, "t1": 286.68, "text": "And the lecture's answer is multi-state recurrence CFD: one database per process state."}]]}, {"title": "Digital twins", "paras": [[{"t0": 288.0, "t1": 291.25, "text": "Professor Pirker likes the digital-twin story."}, {"t0": 291.25, "t1": 296.89, "text": "A tank model with one mean value is instant, but it ignores the inside of the plant."}, {"t0": 296.89, "t1": 300.81, "text": "Full CFD shows the inside, but takes days."}, {"t0": 300.81, "t1": 311.61, "text": "The lecture example: the tank model under one second, the experiment 750 seconds, CFD two days, and recurrence CFD 30 seconds."}, {"t0": 311.61, "t1": 314.71, "text": "So recurrence CFD sits in between."}], [{"t0": 315.36, "t1": 318.57, "text": "But run blindly forward, it collects error."}, {"t0": 318.57, "t1": 321.44, "text": "So live data should keep aligning it."}, {"t0": 321.44, "t1": 330.54, "text": "And your thesis shows what such a twin must watch: a boundary condition can move the process into a regime that the database does not cover."}]]}, {"title": "Is recurrence CFD machine learning?", "paras": [[{"t0": 331.85, "t1": 333.7, "text": "Here is a careful answer."}, {"t0": 333.7, "t1": 335.93, "text": "It is data-based simulation."}, {"t0": 335.93, "t1": 344.06, "text": "An expensive ground truth makes the data, a cheap model reuses it, and the real question is how far it generalizes."}, {"t0": 344.06, "t1": 346.07, "text": "There is no gradient training."}, {"t0": 346.07, "t1": 349.38, "text": "Choosing the next frame is a nearest-neighbour search."}, {"t0": 349.38, "t1": 355.39, "text": "And the replay is a sequence of sparse linear operators, close to a learned propagator."}], [{"t0": 356.06, "t1": 366.45, "text": "Possible AI steps: learn the map for unseen states, learn the missing flux as a function of the state, or train a neural operator on the database."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 367.75, "t1": 368.62, "text": "One."}, {"t0": 368.62, "t1": 374.87, "text": "Bold prediction plus physics-based correction, just like SIMPLE guesses a pressure and corrects it."}], [{"t0": 375.52, "t1": 376.3, "text": "Two."}, {"t0": 376.3, "t1": 388.09, "text": "Three bold failures: mass imbalance, fixed by a global balance; unphysical diffusion, fixed by local swaps; too little recurrence, fixed by islands."}, {"t0": 388.09, "t1": 390.62, "text": "Your thesis touches all three."}], [{"t0": 391.29, "t1": 392.2, "text": "Three."}, {"t0": 392.2, "t1": 395.08, "text": "A database belongs to a flow regime."}, {"t0": 395.08, "t1": 401.2, "text": "The lecture's answer is multi-state recurrence CFD, and your cooled lid is the example."}]]}]}, {"id": "A2", "group": "A", "title": "A2 · Reading the figures of my thesis", "file": "tracks/A2.mp3", "voice": "Ava", "duration": 439.4, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 2.56, "text": "Reading the figures of my thesis."}], [{"t0": 3.19, "t1": 8.81, "text": "Professor Pirker often points at a figure and asks: what does it show, and why?"}, {"t0": 8.81, "t1": 13.25, "text": "So for every important figure, you need three sentences ready."}, {"t0": 13.25, "t1": 14.47, "text": "What is plotted."}, {"t0": 14.47, "t1": 15.76, "text": "What we see."}, {"t0": 15.76, "t1": 17.61, "text": "And why it matters."}, {"t0": 17.61, "t1": 20.95, "text": "In this episode, we practise exactly that."}, {"t0": 20.95, "t1": 27.73, "text": "I will describe each figure by its content, not by its number, because the numbering may still change."}]]}, {"title": "The passive and the non-passive scalar", "paras": [[{"t0": 29.04, "t1": 31.81, "text": "The opening figure has three panels."}, {"t0": 31.81, "t1": 38.72, "text": "First, a dye in the stored velocity of the insulated tank: it is only stretched by the flow."}, {"t0": 38.72, "t1": 44.14, "text": "Second, the cooled tank, where cold plumes from the lid create the motion."}, {"t0": 44.14, "t1": 50.41, "text": "Third, the replay, which moves temperature with recorded maps and never solves the velocity."}], [{"t0": 51.07, "t1": 55.91, "text": "Why it matters: it is the whole thesis question in one figure."}, {"t0": 55.91, "t1": 62.46, "text": "A dye only rides the flow, but temperature makes the flow, and the replay cuts that feedback."}]]}, {"title": "The recurrence of the database", "paras": [[{"t0": 63.77, "t1": 66.83, "text": "This figure shows the distance matrix of the recording."}, {"t0": 66.83, "t1": 72.11, "text": "It has two blocks, split at the end of the inflow: filling, and settling."}, {"t0": 72.11, "t1": 76.84, "text": "The rows rise to a plateau, and none of them returns towards zero."}], [{"t0": 77.49, "t1": 84.58, "text": "Why it matters: the prominence, a median of 0.028, stays below what the method needs."}, {"t0": 84.58, "t1": 88.9, "text": "So no state comes back, and the replay plays the frames in order."}]]}, {"title": "Vertical heat transport under the cooled lid", "paras": [[{"t0": 90.21, "t1": 98.53, "text": "This figure splits the plane-mean vertical heat flux into two parts: the part carried by the flow, and the part carried by conduction."}, {"t0": 98.53, "t1": 106.77, "text": "Under the cooled lid, the flow carries far more heat than conduction, and the temperature departures have the size of whole plumes."}], [{"t0": 107.44, "t1": 111.42, "text": "Why it matters: cooling is a transport process."}, {"t0": 111.42, "t1": 113.96, "text": "A diffusive step cannot copy it."}]]}, {"title": "The two regimes", "paras": [[{"t0": 115.27, "t1": 119.48, "text": "Same geometry, same inflow, two different flows."}, {"t0": 119.48, "t1": 126.33, "text": "With the insulated lid, the jet rises, spreads under the lid, and the warm layer then rests."}, {"t0": 126.33, "t1": 133.57, "text": "With the cooled lid, the layer above the front overturns in a row of cells, driven by cold plumes."}], [{"t0": 134.22, "t1": 140.14, "text": "Why it matters: one boundary condition switches the flow from one regime to another."}]]}, {"title": "The standard replay over the mixing sweep", "paras": [[{"t0": 141.45, "t1": 147.16, "text": "Two panels: the mean temperature, and the height of the heat, for seven mixing strengths."}, {"t0": 147.16, "t1": 152.83, "text": "More mixing heats the tank faster during the inflow, and drains it faster afterwards."}, {"t0": 152.83, "t1": 158.09, "text": "The height is best at a medium strength, the heat content with little mixing."}], [{"t0": 158.75, "t1": 162.46, "text": "Why it matters: there is no single best setting."}]]}, {"title": "The insulated tank through the run", "paras": [[{"t0": 163.77, "t1": 169.13, "text": "The mid-plane temperature at four times, with the front width written in each panel."}, {"t0": 169.13, "t1": 174.61, "text": "The replay with the recorded maps alone keeps the front as thin as the reference."}, {"t0": 174.61, "t1": 176.84, "text": "The standard replay smears it."}, {"t0": 176.84, "t1": 179.73, "text": "The corrected replay makes it thin again."}], [{"t0": 180.4, "t1": 186.02, "text": "Why it matters: the smearing comes from the face exchange, not from the maps."}]]}, {"title": "The space–time diagram", "paras": [[{"t0": 187.33, "t1": 191.83, "text": "The horizontal mean temperature, plotted against height and time."}, {"t0": 191.83, "t1": 194.6, "text": "You see the warm layer growing downwards."}, {"t0": 194.6, "t1": 202.92, "text": "The difference panel shows where the standard replay is too warm or too cold, and the thickness panel shows its front stays too thick."}, {"t0": 202.92, "t1": 205.59, "text": "The corrected replay follows the reference."}]]}, {"title": "Every correction run in one map", "paras": [[{"t0": 206.92, "t1": 214.31, "text": "Each marker is one replay: the trace error and the end-profile error, plotted against the front width."}, {"t0": 214.31, "t1": 222.25, "text": "Only the vertically weighted form brings both errors down while the front reaches the reference width of 5.0 millimetres."}, {"t0": 222.25, "t1": 227.58, "text": "Its working range is s from 0.40 to 0.50."}], [{"t0": 228.25, "t1": 232.52, "text": "Why it matters: direction matters more than strength."}]]}, {"title": "The buoyancy frequency across the front", "paras": [[{"t0": 233.84, "t1": 239.35, "text": "The buoyancy frequency says how strongly the layering resists vertical motion."}, {"t0": 239.35, "t1": 244.55, "text": "N squared equals g times beta times the vertical temperature gradient."}, {"t0": 244.55, "t1": 249.68, "text": "The standard replay holds a barrier only about half as strong as the reference."}, {"t0": 249.68, "t1": 253.86, "text": "The corrected replay reaches the reference value after the inflow."}], [{"t0": 254.53, "t1": 262.8, "text": "Why it matters: a sharper front is a stronger barrier, so the correction restores the stability of the front, not only its width."}]]}, {"title": "End profiles through the front", "paras": [[{"t0": 264.1, "t1": 268.2, "text": "Without correction, the front is wide and too high."}, {"t0": 268.2, "t1": 272.62, "text": "The unweighted correction makes it thin, but puts it in the wrong place."}, {"t0": 272.62, "t1": 275.12, "text": "The vertical weight follows the reference."}], [{"t0": 275.79, "t1": 280.97, "text": "Why it matters: a saw-toothed front can have the right width and the wrong shape."}, {"t0": 280.97, "t1": 283.8, "text": "Always read the width together with the profile."}]]}, {"title": "The outlet temperature from the energy balance", "paras": [[{"t0": 285.1, "t1": 296.91, "text": "The outlet temperature is recovered from the energy balance of the whole tank: the mass times the rate of change of the mean temperature equals the mass flow times inlet minus outlet temperature."}, {"t0": 296.91, "t1": 303.46, "text": "While the inflow is warm, the standard replay keeps about 2.7 kelvin too much heat."}, {"t0": 303.46, "t1": 307.07, "text": "Afterwards, it drains 4.6 kelvin."}], [{"t0": 307.73, "t1": 316.05, "text": "Why it matters: the outlet sits just below the front, so a numerical error at the front becomes an error in the energy budget."}]]}, {"title": "The state space", "paras": [[{"t0": 317.36, "t1": 324.87, "text": "The two leading POD modes of the reference field, and the distance of each run from the space of the first ten modes."}, {"t0": 324.87, "t1": 328.73, "text": "The standard replay leaves this space and does not return."}, {"t0": 328.73, "t1": 331.88, "text": "The corrected replay comes back after the inflow."}], [{"t0": 332.55, "t1": 338.69, "text": "Why it matters: the correction keeps the replay close to the states that the recording spans."}]]}, {"title": "The cooled lid: profiles, traces, and plumes", "paras": [[{"t0": 340.01, "t1": 349.93, "text": "The end profiles: the standard replay holds nearly the right heat, but in the wrong place, with a profile error of 2.79 kelvin."}, {"t0": 349.93, "t1": 353.31, "text": "The bulk is too warm, the top layer too cold."}, {"t0": 353.31, "t1": 355.6, "text": "The correction moves the heat back."}], [{"t0": 356.26, "t1": 363.87, "text": "The traces: a shaded band shows how far the local correction lags in heterogeneity during the warm inflow."}, {"t0": 363.87, "t1": 367.96, "text": "Only the recorded flux also follows the heterogeneity."}, {"t0": 367.96, "t1": 372.54, "text": "A lag in layering is missing transport, not missing sharpness."}], [{"t0": 373.2, "t1": 378.49, "text": "And in 3D: the plumes of the standard replay end halfway down."}, {"t0": 378.49, "t1": 381.71, "text": "With the correction, they reach the front again."}, {"t0": 381.71, "t1": 384.24, "text": "The replay invents no motion."}, {"t0": 384.24, "t1": 387.38, "text": "The plumes were in the recorded maps all along."}]]}, {"title": "The recurrence of the two recordings", "paras": [[{"t0": 388.7, "t1": 398.78, "text": "After the inflow, the cooled flow keeps renewing itself, about ten times faster at short lags, while the insulated flow hardly changes."}], [{"t0": 399.45, "t1": 407.65, "text": "Why it matters: the cooled case is a different regime, so a database recorded without cooling cannot contain its motion."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 408.96, "t1": 409.8, "text": "One."}, {"t0": 409.8, "t1": 415.38, "text": "For every figure: what is plotted, what we see, why it matters."}], [{"t0": 416.03, "t1": 416.81, "text": "Two."}, {"t0": 416.81, "t1": 427.53, "text": "The key chain of figures: no single mixing setting, the maps keep the front thin, the outlet drains heat, the vertical correction restores width and stability."}], [{"t0": 428.18, "t1": 429.13, "text": "Three."}, {"t0": 429.13, "t1": 439.38, "text": "Under the cooled lid: right heat, wrong place without correction; the lag is missing transport; and a different regime needs a different database."}]]}]}, {"id": "A3", "group": "A", "title": "A3 · The CFD basics behind recurrence CFD", "file": "tracks/A3.mp3", "voice": "Ava", "duration": 464.3, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 3.46, "text": "The CFD basics behind recurrence CFD."}], [{"t0": 4.13, "t1": 9.2, "text": "This last episode covers the CFD basics from Professor Pirker's lecture."}, {"t0": 9.2, "t1": 15.01, "text": "These are the questions that test whether you really understand the ground that recurrence CFD stands on."}, {"t0": 15.01, "t1": 21.67, "text": "The trick for each one is the same: say the idea, give one formula, and connect it to your thesis."}, {"t0": 21.67, "t1": 25.85, "text": "That connection is what turns a textbook answer into your answer."}]]}, {"title": "Dimensionless numbers", "paras": [[{"t0": 27.17, "t1": 33.26, "text": "The Reynolds number compares inertia with viscous forces: U times L over nu."}, {"t0": 33.26, "t1": 40.2, "text": "Pipe flow is laminar below about 2300, and turbulent above about 4000."}], [{"t0": 40.87, "t1": 42.26, "text": "A few others."}, {"t0": 42.26, "t1": 45.79, "text": "The Péclet number compares convection with diffusion."}, {"t0": 45.79, "t1": 50.34, "text": "The Prandtl number compares momentum diffusion with heat diffusion."}, {"t0": 50.34, "t1": 53.52, "text": "The Froude number compares inertia with gravity."}, {"t0": 53.52, "t1": 57.43, "text": "And the Richardson number compares buoyancy with inertia."}], [{"t0": 58.1, "t1": 67.54, "text": "Your case: a Reynolds number of about 99, so laminar, and a Richardson number of 1.84, so buoyancy is a little stronger than inertia."}]]}, {"title": "Governing equations and the material derivative", "paras": [[{"t0": 68.85, "t1": 72.62, "text": "Mass, momentum and energy are conserved."}, {"t0": 72.62, "t1": 74.85, "text": "There are two ways to look at a flow."}, {"t0": 74.85, "t1": 78.03, "text": "The Lagrangian view follows a fluid parcel."}, {"t0": 78.03, "t1": 80.85, "text": "The Eulerian view watches a fixed point."}], [{"t0": 81.52, "t1": 83.65, "text": "The material derivative links them."}, {"t0": 83.65, "t1": 91.14, "text": "It is the rate of change seen by the moving parcel: the local change in time, plus the velocity dotted with the gradient."}, {"t0": 91.14, "t1": 96.03, "text": "You get it from the chain rule along the path, because the parcel moves with the velocity."}], [{"t0": 96.69, "t1": 106.38, "text": "Momentum, in words: the change in time plus the convection equals the pressure force, plus the viscous force, plus the body force."}]]}, {"title": "The finite-volume method", "paras": [[{"t0": 107.68, "t1": 110.48, "text": "Integrate the equation over each cell."}, {"t0": 110.48, "t1": 115.81, "text": "The divergence theorem turns every divergence into fluxes through the faces."}, {"t0": 115.81, "t1": 120.45, "text": "And what leaves one cell enters its neighbour, so the method is conservative."}], [{"t0": 121.12, "t1": 132.2, "text": "Each cell value is then linked to its neighbours by one linear equation: a P times c P equals the sum of the neighbour coefficients times the neighbour values, plus a source."}, {"t0": 132.2, "t1": 134.72, "text": "That is the computational molecule."}], [{"t0": 135.37, "t1": 137.81, "text": "Here is the connection to your thesis."}, {"t0": 137.81, "t1": 145.36, "text": "If all coefficients are positive, the new value is a weighted mean of its neighbours, so no new extremum can appear."}, {"t0": 145.36, "t1": 152.57, "text": "That is exactly the rule that protects the face exchange in recurrence CFD, and the same idea behind your limiter."}]]}, {"title": "Discretization schemes and numerical diffusion", "paras": [[{"t0": 153.88, "t1": 157.46, "text": "First-order upwind takes the value from upstream."}, {"t0": 157.46, "t1": 160.3, "text": "It is stable, but it adds false diffusion."}, {"t0": 160.3, "t1": 166.57, "text": "Central differencing is more accurate, but it can oscillate when the cell Péclet number is above two."}], [{"t0": 167.22, "t1": 169.4, "text": "Why does upwind diffuse?"}, {"t0": 169.4, "t1": 173.03, "text": "Expand the upstream value in a Taylor series."}, {"t0": 173.03, "t1": 180.05, "text": "The upwind difference equals the true derivative minus one half delta x times the second derivative."}, {"t0": 180.05, "t1": 189.44, "text": "So the equation that upwind really solves has an extra diffusion term, with a numerical diffusivity of one half times u times delta x."}], [{"t0": 190.11, "t1": 195.3, "text": "And this is your thesis in one sentence: it is a numerical-diffusion story."}, {"t0": 195.3, "t1": 200.01, "text": "The face exchange smears the front, and the correction undoes it."}]]}, {"title": "Explicit versus implicit time stepping", "paras": [[{"t0": 201.32, "t1": 205.13, "text": "Explicit steps are cheap, but limited by stability."}, {"t0": 205.13, "t1": 210.7, "text": "Implicit steps solve a system of equations, but are unconditionally stable."}], [{"t0": 211.37, "t1": 219.7, "text": "For explicit convection, the Courant number must be below one: information must not travel more than one cell per step."}, {"t0": 219.7, "t1": 228.11, "text": "For explicit diffusion, the diffusion number, Gamma delta t over delta x squared, must be below one half."}], [{"t0": 228.77, "t1": 231.49, "text": "You can show the diffusion limit on the board."}, {"t0": 231.49, "t1": 235.64, "text": "Insert one Fourier mode into the explicit diffusion step."}, {"t0": 235.64, "t1": 241.73, "text": "The growth factor is one minus four d times sine squared of k delta x over two."}, {"t0": 241.73, "t1": 250.03, "text": "It stays between minus one and one for every mode only if four d is at most two, so d at most one half."}], [{"t0": 250.68, "t1": 259.01, "text": "And again, the link: this explicit diffusion limit is exactly the cap that stopped the recorded diffusivity in your replay."}]]}, {"title": "The SIMPLE algorithm", "paras": [[{"t0": 260.33, "t1": 265.63, "text": "SIMPLE means Semi-Implicit Method for Pressure-Linked Equations, from Patankar."}, {"t0": 265.63, "t1": 266.85, "text": "Four steps."}, {"t0": 266.85, "t1": 272.05, "text": "One: guess the pressure, and solve the momentum equation for a velocity."}, {"t0": 272.05, "t1": 277.17, "text": "Two: write the velocity correction as a function of the pressure correction."}, {"t0": 277.17, "t1": 282.78, "text": "Three: put that into continuity, which gives an equation for the pressure correction."}, {"t0": 282.78, "t1": 289.99, "text": "Four: correct both fields, with under-relaxation, and repeat until the residuals are small."}], [{"t0": 290.66, "t1": 293.75, "text": "Guess, solve, correct, repeat."}, {"t0": 293.75, "t1": 299.22, "text": "And remember from the first episode: recurrence CFD follows the same spirit."}]]}, {"title": "Turbulence", "paras": [[{"t0": 300.53, "t1": 304.32, "text": "Turbulence is chaotic, and it mixes strongly."}, {"t0": 304.32, "t1": 311.81, "text": "Energy enters at the large eddies and cascades down to the Kolmogorov scale, where viscosity dissipates it."}], [{"t0": 312.48, "t1": 315.94, "text": "You can derive the Kolmogorov length from dimensions."}, {"t0": 315.94, "t1": 321.18, "text": "It may depend only on the viscosity nu and the dissipation rate epsilon."}, {"t0": 321.18, "t1": 328.8, "text": "Match metres and seconds, and you get eta equals nu cubed over epsilon, to the power one quarter."}], [{"t0": 329.47, "t1": 342.12, "text": "RANS splits the velocity into a mean and a fluctuation, and models all eddies, usually with an eddy viscosity, like C mu times k squared over epsilon in the k-epsilon model."}, {"t0": 342.12, "t1": 344.99, "text": "LES models only the small eddies."}, {"t0": 344.99, "t1": 346.82, "text": "DNS models none."}, {"t0": 346.82, "t1": 350.87, "text": "And your case needs none of this, because it is laminar."}]]}, {"title": "Wall boundary layers", "paras": [[{"t0": 352.17, "t1": 355.22, "text": "Near a wall, the velocity drops to zero."}, {"t0": 355.22, "t1": 364.24, "text": "y plus says how far the first cell sits from the wall, in viscous units: the friction velocity times the wall distance, over nu."}, {"t0": 364.24, "t1": 370.55, "text": "The viscous sublayer lies below a y plus of about five, the log layer above about thirty."}, {"t0": 370.55, "t1": 375.98, "text": "Wall functions put the first cell in the log layer and model the rest, which is cheap."}, {"t0": 375.98, "t1": 380.58, "text": "A wall-resolved simulation needs a y plus of about one."}]]}, {"title": "Heat transport and Boussinesq", "paras": [[{"t0": 381.88, "t1": 390.58, "text": "Temperature and species follow the same transport equation: change in time plus convection equals diffusion plus a source."}, {"t0": 390.58, "t1": 396.2, "text": "If the density depends on temperature, the flow and the temperature are coupled."}], [{"t0": 396.86, "t1": 405.04, "text": "For small density changes, the Boussinesq approximation keeps the density constant everywhere, except in the gravity term."}, {"t0": 405.04, "t1": 409.37, "text": "And that buoyancy term is the exact link that the replay cuts."}]]}, {"title": "Multiphase flows", "paras": [[{"t0": 410.68, "t1": 415.75, "text": "Euler–Euler treats each phase as a continuum, with volume fractions."}, {"t0": 415.75, "t1": 418.58, "text": "It suits dense systems at lower cost."}, {"t0": 418.58, "t1": 427.93, "text": "Euler–Lagrange tracks every particle, and with particle contacts it becomes CFD–DEM: accurate, but expensive."}, {"t0": 427.93, "t1": 433.37, "text": "And recurrence CFD was first used for bubble columns and fluidized beds."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 434.68, "t1": 435.47, "text": "One."}, {"t0": 435.47, "t1": 442.97, "text": "Finite volumes are conservative, and positive coefficients mean no new extremes: the same rule protects your limiter."}], [{"t0": 443.63, "t1": 444.42, "text": "Two."}, {"t0": 444.42, "t1": 449.27, "text": "Upwind adds a numerical diffusivity of one half u delta x."}, {"t0": 449.27, "t1": 452.56, "text": "Your thesis is a numerical-diffusion story."}], [{"t0": 453.23, "t1": 454.19, "text": "Three."}, {"t0": 454.19, "t1": 459.87, "text": "Explicit limits: Courant below one, diffusion number below one half."}, {"t0": 459.87, "t1": 464.22, "text": "That diffusion limit is the cap that stopped the recorded diffusivity."}]]}]}, {"id": "M1", "group": "M", "title": "M1 · Learning from data: risk, loss, and the bias–variance story", "file": "tracks/M1.mp3", "voice": "Ava", "duration": 343.3, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 4.96, "text": "Learning from data: risk, loss, and the bias–variance story."}], [{"t0": 5.62, "t1": 10.45, "text": "Almost every Machine Learning and Perception exam starts in the same place."}, {"t0": 10.45, "t1": 16.02, "text": "The examiner says: write down a supervised data set and the training framework."}, {"t0": 16.02, "t1": 20.37, "text": "If you can tell this story calmly, the rest of the exam gets easier."}, {"t0": 20.37, "t1": 23.27, "text": "So let's build it, piece by piece."}]]}, {"title": "Data, model, loss, average, minimise", "paras": [[{"t0": 24.58, "t1": 26.55, "text": "We have N pairs."}, {"t0": 26.55, "t1": 30.87, "text": "Each pair is an input x n and a label y n."}, {"t0": 30.87, "t1": 37.74, "text": "We assume the pairs are drawn independently from one unknown distribution, p of x and y."}], [{"t0": 38.4, "t1": 43.36, "text": "A model g maps an input to a prediction, and it has weights w."}, {"t0": 43.36, "t1": 46.79, "text": "A loss L says how wrong one prediction is."}, {"t0": 46.79, "t1": 51.78, "text": "If we average the loss over all training pairs, we get the empirical risk."}, {"t0": 51.78, "t1": 57.04, "text": "And learning simply means: find the weights that minimise the empirical risk."}], [{"t0": 57.72, "t1": 63.75, "text": "Remember it as five words: data, model, loss, average, minimise."}]]}, {"title": "Why not minimise the real error?", "paras": [[{"t0": 65.04, "t1": 71.16, "text": "The examiner will push: what is the generalization error, and why can't we minimise it directly?"}], [{"t0": 71.83, "t1": 78.04, "text": "The generalization error is the expected loss on new data, drawn from the true distribution."}, {"t0": 78.04, "t1": 82.76, "text": "To compute it, you would need to integrate the loss against p of x and y."}, {"t0": 82.76, "t1": 84.5, "text": "But p is unknown."}, {"t0": 84.5, "t1": 86.64, "text": "That is the whole problem of learning."}], [{"t0": 87.3, "t1": 97.71, "text": "So we minimise the empirical risk instead, and we estimate the generalization error on data we did not train on: a test set, or cross-validation."}, {"t0": 97.71, "t1": 104.28, "text": "By the law of large numbers, the average loss on a large test set approaches the expected loss."}], [{"t0": 104.94, "t1": 109.96, "text": "And one trap to avoid: the training loss is not a fair estimate."}, {"t0": 109.96, "t1": 113.56, "text": "The weights were chosen on that data, so it looks too good."}]]}, {"title": "What is a loss function?", "paras": [[{"t0": 114.88, "t1": 117.63, "text": "A loss compares a label with a prediction."}, {"t0": 117.63, "t1": 122.12, "text": "It is never negative, and it is zero when the prediction is right."}, {"t0": 122.12, "t1": 123.67, "text": "You pick it for the task."}], [{"t0": 124.33, "t1": 131.06, "text": "For regression, the squared loss: one half times the label minus the prediction, squared."}, {"t0": 131.06, "t1": 134.44, "text": "For two classes, binary cross-entropy."}, {"t0": 134.44, "t1": 143.54, "text": "For many classes, categorical cross-entropy: minus the sum over classes of the label times the log of the predicted probability."}, {"t0": 143.54, "t1": 146.85, "text": "And for the support vector machine, the hinge loss."}], [{"t0": 147.51, "t1": 152.82, "text": "Professor Klambauer has asked a nice follow-up: are all losses differentiable?"}, {"t0": 152.82, "t1": 153.79, "text": "No."}, {"t0": 153.79, "t1": 159.26, "text": "The zero-one loss, which just counts mistakes, has no useful gradient."}, {"t0": 159.26, "t1": 161.56, "text": "It is flat almost everywhere."}, {"t0": 161.56, "t1": 164.66, "text": "So for training we use cross-entropy instead."}]]}, {"title": "Linear regression as the warm-up", "paras": [[{"t0": 165.97, "t1": 170.06, "text": "With a linear model and the squared loss, the risk is a bowl."}, {"t0": 170.06, "t1": 174.64, "text": "It is convex, so there is one minimum, and you can find it in closed form."}, {"t0": 174.64, "t1": 180.2, "text": "Take the gradient of one half times the squared norm of y minus X w."}, {"t0": 180.2, "t1": 183.47, "text": "It is minus X transposed times the error."}, {"t0": 183.47, "t1": 186.85, "text": "Set it to zero, and you get the normal equations."}, {"t0": 186.85, "t1": 192.52, "text": "The solution is X transposed X, inverted, times X transposed y."}, {"t0": 192.52, "t1": 194.64, "text": "That is the pseudo-inverse."}], [{"t0": 195.32, "t1": 199.47, "text": "Notice one pattern here, because it comes back in backpropagation."}, {"t0": 199.47, "t1": 204.02, "text": "For one sample, the gradient is the error times the input."}]]}, {"title": "Overfitting, underfitting, bias and variance", "paras": [[{"t0": 205.33, "t1": 207.21, "text": "Here is a picture that helps."}, {"t0": 207.21, "t1": 213.04, "text": "Imagine shooting arrows at a target, many times, each time with a new training set."}, {"t0": 213.04, "t1": 216.99, "text": "Bias is how far the centre of your arrows is from the bullseye."}, {"t0": 216.99, "t1": 220.22, "text": "Variance is how widely your arrows scatter."}], [{"t0": 220.88, "t1": 223.94, "text": "A model that is too simple has high bias."}, {"t0": 223.94, "t1": 226.83, "text": "It cannot follow the data, so it underfits."}, {"t0": 226.83, "t1": 230.12, "text": "A model that is too complex has high variance."}, {"t0": 230.12, "t1": 236.56, "text": "It follows the noise in each training set, so the training error is low, but the test error is high."}, {"t0": 236.56, "t1": 238.18, "text": "That is overfitting."}], [{"t0": 238.85, "t1": 246.99, "text": "The formula behind the picture: the expected squared error equals noise, plus bias squared, plus variance."}, {"t0": 246.99, "t1": 251.16, "text": "You derive it by adding and subtracting the average model prediction."}, {"t0": 251.16, "t1": 254.69, "text": "The cross terms have zero mean, so they disappear."}], [{"t0": 255.36, "t1": 260.37, "text": "And the modern twist: very large networks show double descent."}, {"t0": 260.37, "t1": 265.55, "text": "After the point where they fit the training data exactly, the test error falls again."}, {"t0": 265.55, "t1": 267.64, "text": "Mention it in one sentence."}, {"t0": 267.64, "t1": 271.08, "text": "It shows you know the classic curve is not the whole story."}]]}, {"title": "Maximum likelihood", "paras": [[{"t0": 272.4, "t1": 276.13, "text": "Professor Widmer has asked this one several times."}, {"t0": 276.13, "t1": 281.5, "text": "Maximum likelihood chooses the parameters that make the observed data most probable."}, {"t0": 281.5, "t1": 286.35, "text": "We maximise the log-likelihood, because a sum is easier than a product."}], [{"t0": 287.02, "t1": 292.64, "text": "The neat connection: squared loss is maximum likelihood under Gaussian noise."}, {"t0": 292.64, "t1": 300.33, "text": "Write the likelihood of a Gaussian, take minus the log, and the only part that depends on the weights is the sum of squared errors."}], [{"t0": 300.98, "t1": 306.4, "text": "And the weakness: with little data, maximum likelihood overfits."}, {"t0": 306.4, "t1": 309.67, "text": "An event you have never seen gets probability zero."}, {"t0": 309.67, "t1": 315.56, "text": "A prior, which gives you MAP estimation, or regularization, fixes that."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 316.87, "t1": 317.74, "text": "One."}, {"t0": 317.74, "t1": 323.95, "text": "Data, model, loss, average, minimise: that is empirical risk minimization."}], [{"t0": 324.62, "t1": 325.39, "text": "Two."}, {"t0": 325.39, "t1": 334.94, "text": "The generalization error needs the unknown distribution, so we estimate it on a test set or by cross-validation, never on the training data."}], [{"t0": 335.61, "t1": 336.5, "text": "Three."}, {"t0": 336.5, "t1": 343.27, "text": "Simple models have bias, complex models have variance, and very large nets show double descent."}]]}]}, {"id": "M2", "group": "M", "title": "M2 · From one neuron to backpropagation", "file": "tracks/M2.mp3", "voice": "Ava", "duration": 380.6, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 2.63, "text": "From one neuron to backpropagation."}], [{"t0": 3.29, "t1": 6.3, "text": "This is the most asked topic in the whole exam."}, {"t0": 6.3, "t1": 15.96, "text": "Professor Hochreiter, Professor Klambauer and others have asked it again and again: explain backpropagation and define the delta error."}, {"t0": 15.96, "t1": 17.76, "text": "Your goal is simple."}, {"t0": 17.76, "t1": 23.37, "text": "You should be able to write it on the board in two minutes, and explain every line while you write."}, {"t0": 23.37, "t1": 24.62, "text": "Let's get there."}]]}, {"title": "One neuron", "paras": [[{"t0": 25.94, "t1": 33.14, "text": "A neuron takes a weighted sum of its inputs, adds a bias, and passes the result through a non-linear function."}, {"t0": 33.14, "t1": 36.64, "text": "The weighted sum is called the pre-activation, s."}, {"t0": 36.64, "t1": 40.75, "text": "The result, a equals f of s, is the activation."}, {"t0": 40.75, "t1": 51.64, "text": "A layer does this for many neurons at once, so in matrix form, the activation of layer l is f of W times the activation of the layer below, plus b."}, {"t0": 51.64, "t1": 55.97, "text": "The forward pass goes layer by layer, from the input to the output."}]]}, {"title": "Why do we need the non-linearity?", "paras": [[{"t0": 57.29, "t1": 62.33, "text": "Professor Schlüter has asked: what happens without activation functions?"}, {"t0": 62.33, "t1": 66.01, "text": "The whole network collapses into one linear model."}, {"t0": 66.01, "t1": 70.36, "text": "Multiply two linear maps, and you get another linear map."}, {"t0": 70.36, "t1": 75.47, "text": "So depth adds nothing, and the network cannot even solve XOR."}, {"t0": 75.47, "t1": 78.7, "text": "The non-linearity is what makes depth useful."}]]}, {"title": "The universal approximation theorem", "paras": [[{"t0": 80.02, "t1": 90.19, "text": "One hidden layer, with enough units and a non-polynomial activation such as a sigmoid, can approximate any continuous function on a compact set."}, {"t0": 90.19, "t1": 92.8, "text": "Now the important part, the limit."}, {"t0": 92.8, "t1": 96.3, "text": "The theorem says the network can represent the function."}, {"t0": 96.3, "t1": 99.54, "text": "It does not say how many units you need."}, {"t0": 99.54, "t1": 103.49, "text": "And it does not say that gradient descent will find the weights."}, {"t0": 103.49, "t1": 105.7, "text": "Existence, not learnability."}]]}, {"title": "Backpropagation: the idea", "paras": [[{"t0": 107.02, "t1": 108.44, "text": "Here is the problem."}, {"t0": 108.44, "t1": 114.73, "text": "A network may have millions of weights, and we need the gradient of the loss for every single one."}, {"t0": 114.73, "t1": 117.6, "text": "Doing that one by one would be hopeless."}], [{"t0": 118.27, "t1": 123.71, "text": "Backpropagation gets all of them with one forward pass and one backward pass."}, {"t0": 123.71, "t1": 126.44, "text": "Think of it like tracing blame in a team."}, {"t0": 126.44, "t1": 129.31, "text": "The output is wrong by some amount."}, {"t0": 129.31, "t1": 133.5, "text": "Each unit gets a share of the blame, depending on how much it contributed."}, {"t0": 133.5, "t1": 136.98, "text": "And that blame flows backwards, layer by layer."}, {"t0": 136.98, "t1": 139.44, "text": "That share of blame is the delta."}]]}, {"title": "The delta, defined", "paras": [[{"t0": 140.76, "t1": 148.29, "text": "Write this first: delta i is defined as the derivative of the loss with respect to the pre-activation s i."}], [{"t0": 148.94, "t1": 152.35, "text": "Now the gradient of a weight w i j."}, {"t0": 152.35, "t1": 155.76, "text": "The weight acts on the loss only through s i."}, {"t0": 155.76, "t1": 166.28, "text": "So by the chain rule, the derivative of the loss with respect to w i j equals delta i, times the derivative of s i with respect to w i j."}, {"t0": 166.28, "t1": 171.38, "text": "And because s i is the weighted sum, that derivative is just a j."}], [{"t0": 172.05, "t1": 175.76, "text": "So the gradient is delta i times a j."}, {"t0": 175.76, "t1": 181.61, "text": "In words: the delta of the unit above, times the activation of the unit below."}, {"t0": 181.61, "t1": 184.3, "text": "That is the line examiners want to hear."}], [{"t0": 184.96, "t1": 193.13, "text": "And the update: w i j becomes w i j minus eta, times delta i, times a j."}]]}, {"title": "The recursion", "paras": [[{"t0": 194.44, "t1": 198.62, "text": "Next question: how do we get the deltas of hidden units?"}, {"t0": 198.62, "t1": 203.69, "text": "A hidden unit j affects the loss only through the units i in the next layer."}, {"t0": 203.69, "t1": 205.68, "text": "So we sum over those paths."}], [{"t0": 206.34, "t1": 213.92, "text": "Delta j equals the sum over i of delta i, times w i j, times f prime of s j."}], [{"t0": 214.6, "t1": 225.92, "text": "In matrix form: take the deltas of the layer above, multiply by the weight matrix transposed, then multiply element by element by the slopes of the activations."}, {"t0": 225.92, "t1": 231.99, "text": "Deltas flow down: multiply by W transposed, then by f prime."}], [{"t0": 232.64, "t1": 242.9, "text": "And the gradient for a whole weight matrix is the outer product: the delta vector of layer l times the activation vector of the layer below, transposed."}, {"t0": 242.9, "t1": 245.86, "text": "The cost is linear in the number of weights."}, {"t0": 245.86, "t1": 248.23, "text": "That is why backprop is efficient."}]]}, {"title": "The delta at the output", "paras": [[{"t0": 249.54, "t1": 256.5, "text": "Professor Hochreiter likes this one: what is the delta at the output with softmax and cross-entropy?"}, {"t0": 256.5, "t1": 259.21, "text": "The answer is beautifully simple."}, {"t0": 259.21, "t1": 261.1, "text": "Prediction minus label."}], [{"t0": 261.75, "t1": 263.14, "text": "You can derive it."}, {"t0": 263.14, "t1": 280.65, "text": "The derivative of the softmax output a k with respect to s i is a k times, one if k equals i minus a i. Put that into the derivative of the cross-entropy, use the fact that a one-hot label sums to one, and everything collapses to a i minus y i."}], [{"t0": 281.31, "t1": 288.37, "text": "The same clean result holds for a linear output with squared loss, and for a sigmoid with binary cross-entropy."}, {"t0": 288.37, "t1": 290.98, "text": "That is why these pairs are used together."}]]}, {"title": "Vanishing and exploding gradients", "paras": [[{"t0": 292.3, "t1": 294.43, "text": "Now look at the recursion again."}, {"t0": 294.43, "t1": 299.83, "text": "To get the delta of the first layer, you multiply by one Jacobian per layer."}, {"t0": 299.83, "t1": 304.96, "text": "So over many layers, the delta shrinks or grows exponentially."}, {"t0": 304.96, "t1": 308.73, "text": "With the sigmoid, the slope is at most one quarter."}, {"t0": 308.73, "t1": 314.92, "text": "If one quarter times the weight norm is below one, the delta vanishes as the network gets deeper."}], [{"t0": 315.58, "t1": 324.04, "text": "And here is the Linz connection: Sepp Hochreiter analysed this problem in his diploma thesis in 1991, here in Linz."}, {"t0": 324.04, "t1": 329.83, "text": "If the examiner asks who found it, that is your answer, and it is a good moment to smile."}], [{"t0": 330.48, "t1": 340.84, "text": "The fixes: ReLU or SELU activations, good initialization, normalization, residual connections, and for sequences, the LSTM."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 342.15, "t1": 342.99, "text": "One."}, {"t0": 342.99, "t1": 347.59, "text": "Delta is the derivative of the loss with respect to the pre-activation."}, {"t0": 347.59, "t1": 351.82, "text": "The gradient is the delta above times the activation below."}], [{"t0": 352.49, "t1": 353.28, "text": "Two."}, {"t0": 353.28, "t1": 359.26, "text": "Deltas flow down: multiply by W transposed, then by f prime."}, {"t0": 359.26, "t1": 364.96, "text": "At the output, softmax with cross-entropy gives prediction minus label."}], [{"t0": 365.64, "t1": 366.6, "text": "Three."}, {"t0": 366.6, "t1": 370.3, "text": "A product of Jacobians vanishes or explodes."}, {"t0": 370.3, "t1": 374.32, "text": "Hochreiter, 1991, Linz."}, {"t0": 374.32, "t1": 380.49, "text": "Fixes: ReLU or SELU, initialization, ResNet, LSTM."}]]}]}, {"id": "M3", "group": "M", "title": "M3 · Training well: optimizers, activations, regularization", "file": "tracks/M3.mp3", "voice": "Ava", "duration": 349.5, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 5.13, "text": "Training well: optimizers, activations, regularization."}], [{"t0": 5.78, "t1": 9.07, "text": "Once you have gradients, you have to use them well."}, {"t0": 9.07, "t1": 20.59, "text": "This episode covers the short questions that come after backpropagation: gradient descent, optimizers, activation functions, regularization and initialization."}, {"t0": 20.59, "t1": 23.9, "text": "They are quick questions, so your answers should be quick too."}, {"t0": 23.9, "t1": 26.82, "text": "One clear sentence, then one detail."}]]}, {"title": "Gradient descent and mini-batches", "paras": [[{"t0": 28.13, "t1": 33.98, "text": "Gradient descent moves the weights a small step against the gradient of the empirical risk."}, {"t0": 33.98, "t1": 38.37, "text": "The weights become the weights minus eta, times the gradient."}, {"t0": 38.37, "t1": 40.27, "text": "Eta is the learning rate."}], [{"t0": 40.94, "t1": 42.58, "text": "Why mini-batches?"}, {"t0": 42.58, "t1": 45.97, "text": "Think of a hiker in fog, trying to walk downhill."}, {"t0": 45.97, "t1": 52.08, "text": "The full batch is like surveying the whole mountain before every step: exact, but slow."}, {"t0": 52.08, "t1": 57.67, "text": "One sample is like guessing from one stone under your foot: cheap, but noisy."}, {"t0": 57.67, "t1": 60.03, "text": "A mini-batch is the compromise."}, {"t0": 60.03, "t1": 70.36, "text": "It gives an unbiased estimate of the gradient, it runs fast and in parallel on a GPU, and its small noise even helps the weights escape sharp minima."}]]}, {"title": "Which optimizers do you know?", "paras": [[{"t0": 71.69, "t1": 79.31, "text": "Gradient descent, stochastic gradient descent, momentum, AdaGrad, RMSprop and Adam."}], [{"t0": 79.96, "t1": 87.08, "text": "Momentum keeps a running sum of past gradients, like a ball rolling downhill that keeps its speed through small bumps."}, {"t0": 87.08, "t1": 93.68, "text": "AdaGrad and RMSprop give each weight its own step size, based on its past squared gradients."}, {"t0": 93.68, "t1": 100.74, "text": "Adam combines both ideas, momentum and RMSprop, with a bias correction for the first steps."}, {"t0": 100.74, "t1": 102.44, "text": "It is the usual default."}]]}, {"title": "Other training methods", "paras": [[{"t0": 103.75, "t1": 108.98, "text": "Professor Klambauer has asked: are there methods other than gradient descent?"}, {"t0": 108.98, "t1": 109.97, "text": "Yes."}, {"t0": 109.97, "t1": 112.35, "text": "Linear models have a closed form."}, {"t0": 112.35, "t1": 116.69, "text": "Logistic regression can use iteratively reweighted least squares."}, {"t0": 116.69, "t1": 121.65, "text": "RProp and Quickprop use only the sign or the curvature of the gradient."}, {"t0": 121.65, "t1": 129.26, "text": "Newton, Gauss–Newton, Levenberg–Marquardt and conjugate gradients use second-order information."}, {"t0": 129.26, "t1": 134.43, "text": "And evolutionary algorithms or random search need no gradient at all."}]]}, {"title": "Activation functions, and the one from Linz", "paras": [[{"t0": 135.74, "t1": 143.11, "text": "This is a favourite question of Professor Hochreiter: which activation functions do you know, and which one is from Linz?"}], [{"t0": 143.78, "t1": 149.83, "text": "Sigmoid and tanh are smooth, but they saturate, so their gradients become tiny."}, {"t0": 149.83, "t1": 159.45, "text": "ReLU is cheap and does not saturate for positive inputs, but units can die: if a unit's input stays negative, it never learns again."}], [{"t0": 160.12, "t1": 165.0, "text": "And from Linz: ELU and SELU, developed at JKU."}, {"t0": 165.0, "t1": 172.16, "text": "SELU, from Klambauer and colleagues in 2017, makes a network self-normalizing."}, {"t0": 172.16, "t1": 181.2, "text": "The mean and the variance of the activations are pulled towards zero and one, layer after layer, without any extra normalization layer."}, {"t0": 181.2, "t1": 190.19, "text": "The constants: lambda is about 1.0507, and alpha is about 1.6733."}, {"t0": 190.19, "t1": 193.71, "text": "The fixed point is zero mean and unit variance."}], [{"t0": 194.39, "t1": 201.77, "text": "For the output layer: linear for regression, sigmoid for two classes, softmax for many classes."}]]}, {"title": "Regularization", "paras": [[{"t0": 203.08, "t1": 209.07, "text": "Weight decay, dropout, early stopping, data augmentation and noise."}], [{"t0": 209.72, "t1": 215.8, "text": "Weight decay adds a penalty, lambda over two times the squared norm of the weights."}, {"t0": 215.8, "t1": 225.13, "text": "Its gradient adds lambda times w, so in every step the weights shrink by a factor of one minus eta lambda before the normal update."}, {"t0": 225.13, "t1": 227.17, "text": "That is where the name comes from."}], [{"t0": 227.84, "t1": 234.73, "text": "Dropout switches units off at random during training, so the network cannot rely on any single unit."}, {"t0": 234.73, "t1": 240.78, "text": "Think of a team where any member may be absent on a given day: everyone has to learn the job."}, {"t0": 240.78, "t1": 245.35, "text": "Early stopping ends training when the validation error starts to rise."}]]}, {"title": "Initialization and batch normalization", "paras": [[{"t0": 246.66, "t1": 249.05, "text": "Why does initialization matter?"}, {"t0": 249.05, "t1": 250.5, "text": "Two reasons."}, {"t0": 250.5, "t1": 253.9, "text": "First, random weights break the symmetry."}, {"t0": 253.9, "t1": 258.56, "text": "If all weights start equal, all units learn the same thing."}, {"t0": 258.56, "t1": 260.42, "text": "Second, the scale."}, {"t0": 260.42, "t1": 265.86, "text": "If it is wrong, the signal and the deltas vanish or explode through the layers."}], [{"t0": 266.53, "t1": 269.02, "text": "Here is the short derivation."}, {"t0": 269.02, "t1": 274.56, "text": "A pre-activation is a sum over n in inputs of weight times activation."}, {"t0": 274.56, "t1": 283.87, "text": "With independent, zero-mean weights, its variance is n in, times the variance of the weights, times the mean square of the activations."}, {"t0": 283.87, "t1": 289.27, "text": "To keep the variance constant, choose the weight variance as one over n in."}, {"t0": 289.27, "t1": 294.38, "text": "For ReLU, which halves the mean square, choose two over n in."}, {"t0": 294.38, "t1": 296.32, "text": "That is He initialization."}], [{"t0": 296.98, "t1": 305.59, "text": "Batch normalization standardizes each pre-activation over the mini-batch, and then rescales and shifts it with learned parameters."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 306.89, "t1": 307.69, "text": "One."}, {"t0": 307.69, "t1": 314.45, "text": "Mini-batches: a cheap, unbiased, parallel gradient estimate, with useful noise."}, {"t0": 314.45, "t1": 318.59, "text": "Adam is momentum plus RMSprop with bias correction."}], [{"t0": 319.25, "t1": 320.03, "text": "Two."}, {"t0": 320.03, "t1": 323.58, "text": "The Linz activations are ELU and SELU."}, {"t0": 323.58, "t1": 333.28, "text": "SELU is self-normalizing, with lambda about 1.0507 and alpha about 1.6733."}], [{"t0": 333.94, "t1": 334.86, "text": "Three."}, {"t0": 334.86, "t1": 342.4, "text": "Initialization keeps the variance constant: one over n in, or two over n in for ReLU."}, {"t0": 342.4, "t1": 349.45, "text": "Regularization: weight decay, dropout, early stopping, augmentation, noise."}]]}]}, {"id": "M4", "group": "M", "title": "M4 · Architectures: CNN, ResNet, RNN, LSTM and the Transformer", "file": "tracks/M4.mp3", "voice": "Ava", "duration": 407.5, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 6.62, "text": "Architectures: CNN, ResNet, RNN, LSTM and the Transformer."}], [{"t0": 7.27, "t1": 13.57, "text": "In most exams, after the core, the examiner picks one architecture and asks you to explain it."}, {"t0": 13.57, "t1": 22.28, "text": "So for each architecture, have three things ready: the idea in one sentence, why it works, and the one formula that shows it."}]]}, {"title": "Convolutional networks", "paras": [[{"t0": 23.59, "t1": 31.17, "text": "The idea: small filters with shared weights slide over the image, so a pattern is found wherever it appears."}], [{"t0": 31.85, "t1": 33.9, "text": "Why does this work for images?"}, {"t0": 33.9, "t1": 38.5, "text": "Images have local structure: neighbouring pixels belong together."}, {"t0": 38.5, "t1": 43.67, "text": "And the same pattern, an edge or an eye, can appear anywhere."}, {"t0": 43.67, "t1": 51.86, "text": "Shared weights give you very few parameters and translation equivariance: shift the image, and the feature map shifts with it."}, {"t0": 51.86, "t1": 55.81, "text": "Pooling makes the map smaller and adds a little invariance."}, {"t0": 55.81, "t1": 59.22, "text": "And deeper layers see larger parts of the image."}], [{"t0": 59.88, "t1": 67.86, "text": "The number to know: the output size is the floor of n plus two p minus k, divided by s, plus one."}, {"t0": 67.86, "t1": 72.98, "text": "Here n is the input size, k the kernel, p the padding, and s the stride."}]]}, {"title": "ResNet and U-Net", "paras": [[{"t0": 74.3, "t1": 77.59, "text": "ResNet adds the input of a block to its output."}, {"t0": 77.59, "t1": 83.2, "text": "The next activation equals the current activation plus F of the current activation."}, {"t0": 83.2, "t1": 84.49, "text": "Why does that help?"}, {"t0": 84.49, "t1": 89.01, "text": "The Jacobian of a residual block is the identity plus a small part."}, {"t0": 89.01, "t1": 91.94, "text": "So it does not shrink the delta."}, {"t0": 91.94, "t1": 95.25, "text": "Gradients can travel through very deep networks."}, {"t0": 95.25, "t1": 98.43, "text": "It is like an express lift next to the stairs."}], [{"t0": 99.09, "t1": 101.27, "text": "U-Net is for segmentation."}, {"t0": 101.27, "t1": 105.73, "text": "It is an encoder and a decoder with skip connections between them."}, {"t0": 105.73, "t1": 112.02, "text": "It predicts one class per pixel, and the skips copy fine detail from the encoder to the decoder."}, {"t0": 112.02, "t1": 115.24, "text": "Professor Klambauer has asked about U-Net before."}]]}, {"title": "Recurrent networks", "paras": [[{"t0": 116.54, "t1": 123.6, "text": "The idea: an RNN reads a sequence step by step and keeps a hidden state that carries the past."}], [{"t0": 124.26, "t1": 132.79, "text": "The forward pass: s of t equals W times x of t, plus R times a of t minus one."}, {"t0": 132.79, "t1": 136.13, "text": "Then a of t is f of s of t."}, {"t0": 136.13, "t1": 143.07, "text": "The same weights are used at every step, so the number of parameters does not grow with the length of the sequence."}], [{"t0": 143.73, "t1": 145.21, "text": "How is it trained?"}, {"t0": 145.21, "t1": 147.59, "text": "With backpropagation through time."}, {"t0": 147.59, "t1": 153.88, "text": "Unfold the network over the sequence, and backpropagate as in a deep network with shared weights."}, {"t0": 153.88, "t1": 160.94, "text": "The delta at each step gets two contributions: one from the output at that step, and one from the next step."}, {"t0": 160.94, "t1": 165.35, "text": "And because the weights are shared, their gradient is a sum over time."}]]}, {"title": "Why plain RNNs fail, and how LSTM fixes it", "paras": [[{"t0": 166.67, "t1": 172.43, "text": "At every step back in time, the delta is multiplied by the recurrent Jacobian."}, {"t0": 172.43, "t1": 175.64, "text": "Over a long sequence, that product vanishes."}, {"t0": 175.64, "t1": 179.52, "text": "So a plain RNN forgets long-range dependencies."}, {"t0": 179.52, "t1": 183.59, "text": "This is the same vanishing gradient problem, now in time."}], [{"t0": 184.26, "t1": 192.79, "text": "The LSTM, from Hochreiter and Schmidhuber in 1997, fixes it with a memory cell that is updated by addition."}, {"t0": 192.79, "t1": 199.85, "text": "The cell c of t equals the forget gate times the old cell, plus the input gate times the new input."}, {"t0": 199.85, "t1": 203.27, "text": "The output gate decides what to read from the cell."}], [{"t0": 203.94, "t1": 211.99, "text": "The key line: the derivative of c of t with respect to c of t minus one is just the forget gate."}, {"t0": 211.99, "t1": 216.75, "text": "When the forget gate is near one, that derivative is near the identity."}, {"t0": 216.75, "t1": 220.24, "text": "So the error flows back through time without shrinking."}, {"t0": 220.24, "t1": 223.08, "text": "This is the constant error carousel."}, {"t0": 223.08, "t1": 232.01, "text": "Picture a conveyor belt that carries the memory forward, and the gates are workers who decide what goes on the belt, what stays, and what is taken off."}]]}, {"title": "Bidirectional RNNs and sequence labels", "paras": [[{"t0": 233.34, "t1": 237.65, "text": "Professor Schlüter once asked about an \"RNN from the future\"."}, {"t0": 237.65, "t1": 243.83, "text": "A bidirectional RNN runs one RNN forward and one backward, and joins their states."}, {"t0": 243.83, "t1": 247.73, "text": "So every step sees both the past and the future."}, {"t0": 247.73, "t1": 252.8, "text": "The limit: it needs the whole sequence, so it is not for real-time use."}], [{"t0": 253.45, "t1": 261.46, "text": "For one label per sequence, use the last hidden state, or pool all hidden states, and put a classifier on top."}]]}, {"title": "Attention and the Transformer", "paras": [[{"t0": 262.76, "t1": 269.85, "text": "The idea: every token takes a weighted mean of all tokens, and the weights come from query times key."}], [{"t0": 270.51, "t1": 276.95, "text": "Each token makes three vectors by linear maps: a query, a key and a value."}, {"t0": 276.95, "t1": 283.4, "text": "The attention weights are the softmax of query times key, divided by the square root of d k."}, {"t0": 283.4, "t1": 286.42, "text": "The output mixes the values with those weights."}], [{"t0": 287.07, "t1": 289.96, "text": "Why divide by the square root of d k?"}, {"t0": 289.96, "t1": 302.44, "text": "If the entries of query and key are independent with variance one, their dot product has variance d k. Dividing by its square root brings the variance back to one, so the softmax does not saturate."}], [{"t0": 303.1, "t1": 311.52, "text": "A Transformer block is multi-head self-attention plus an MLP, each with a residual connection and layer normalization."}]]}, {"title": "Two follow-up questions", "paras": [[{"t0": 312.82, "t1": 319.59, "text": "Professor Lehner has asked: Transformers are permutation-equivariant, why is that a problem?"}, {"t0": 319.59, "t1": 323.01, "text": "Because self-attention sees the tokens as a set."}, {"t0": 323.01, "t1": 327.0, "text": "Shuffle the tokens, and the outputs shuffle the same way."}, {"t0": 327.0, "t1": 329.08, "text": "The order of words is lost."}, {"t0": 329.08, "t1": 336.21, "text": "So we add position information: fixed sinusoids, learned vectors, or relative encodings such as RoPE."}], [{"t0": 336.86, "t1": 341.67, "text": "And: compare the cost of an RNN and a Transformer."}, {"t0": 341.67, "t1": 347.12, "text": "An RNN is linear in the sequence length, order N, but it is sequential."}, {"t0": 347.12, "t1": 359.13, "text": "A Transformer is quadratic, order N squared, because every token attends to every token, but all tokens are processed in parallel, and long-range paths are only one step long."}, {"t0": 359.13, "t1": 366.83, "text": "That is also why LSTM-style models like xLSTM are attractive again: their inference is linear in N."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 368.14, "t1": 368.99, "text": "One."}, {"t0": 368.99, "t1": 372.97, "text": "CNN: local filters, shared weights, pooling."}, {"t0": 372.97, "t1": 378.34, "text": "ResNet: identity plus residual, so the Jacobian stays near the identity."}], [{"t0": 378.98, "t1": 379.74, "text": "Two."}, {"t0": 379.74, "t1": 385.38, "text": "RNN: same weights every step, trained by backpropagation through time."}, {"t0": 385.38, "t1": 393.13, "text": "LSTM: additive cell update, so with the forget gate near one, the error is carried unchanged."}], [{"t0": 393.79, "t1": 394.68, "text": "Three."}, {"t0": 394.68, "t1": 401.6, "text": "Attention: softmax of query times key over the square root of d k, times the values."}, {"t0": 401.6, "t1": 407.41, "text": "Transformers need position information, and cost N squared but run in parallel."}]]}]}, {"id": "M5", "group": "M", "title": "M5 · Classical machine learning, REINFORCE, and evaluating a model", "file": "tracks/M5.mp3", "voice": "Ava", "duration": 357.5, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 4.61, "text": "Classical machine learning, REINFORCE, and evaluating a model."}], [{"t0": 5.28, "t1": 19.26, "text": "The last ML&P episode covers the questions that sit next to deep learning: the support vector machine, kernels, the VC dimension, the REINFORCE loss, and how to evaluate and stress-test a classifier."}, {"t0": 19.26, "t1": 25.02, "text": "Some of these were asked by Professor Kofler and Professor Hochreiter, so they are worth your time."}]]}, {"title": "The support vector machine", "paras": [[{"t0": 26.33, "t1": 33.07, "text": "The idea in one sentence: the SVM finds the separating hyperplane with the largest margin."}], [{"t0": 33.74, "t1": 36.75, "text": "Picture a road between two groups of houses."}, {"t0": 36.75, "t1": 43.81, "text": "The SVM builds the widest possible road, and the houses that touch the edge of the road are the support vectors."}, {"t0": 43.81, "t1": 46.23, "text": "Only they decide where the road goes."}], [{"t0": 46.89, "t1": 49.91, "text": "The margin is two over the norm of w."}, {"t0": 49.91, "t1": 54.89, "text": "So maximizing the margin means minimizing the norm of w, squared."}, {"t0": 54.89, "t1": 59.58, "text": "In the soft-margin version, some points may sit inside the margin."}, {"t0": 59.58, "t1": 64.3, "text": "We allow that with slack variables, and we pay for it with a penalty C."}, {"t0": 64.3, "t1": 74.58, "text": "So we minimise one half the squared norm of w, plus C times the sum of the slacks, subject to each point being on the right side, up to its slack."}], [{"t0": 75.23, "t1": 79.57, "text": "In the dual problem, only dot products between data points appear."}, {"t0": 79.57, "t1": 84.11, "text": "The points with alpha n greater than zero are the support vectors."}]]}, {"title": "Kernels and the kernel trick", "paras": [[{"t0": 85.41, "t1": 90.69, "text": "A kernel is a dot product in a feature space, computed without building the features."}], [{"t0": 91.36, "t1": 93.72, "text": "Here is the classic example."}, {"t0": 93.72, "t1": 99.4, "text": "Take the polynomial kernel in two dimensions: x transposed x prime, squared."}, {"t0": 99.4, "t1": 109.85, "text": "Multiply it out, and you get exactly the dot product of two feature vectors, with features x one squared, root two times x one x two, and x two squared."}, {"t0": 109.85, "t1": 116.27, "text": "So the kernel computed the dot product in that three-dimensional feature space, without ever constructing it."}], [{"t0": 116.94, "t1": 122.44, "text": "And since the SVM dual needs only dot products, we can replace them by a kernel."}, {"t0": 122.44, "t1": 126.48, "text": "That gives a non-linear classifier at the cost of a linear one."}, {"t0": 126.48, "t1": 130.7, "text": "Examples: the polynomial kernel and the Gaussian kernel."}]]}, {"title": "The VC dimension", "paras": [[{"t0": 132.01, "t1": 138.49, "text": "The VC dimension is the largest number of points that a model class can label in every possible way."}, {"t0": 138.49, "t1": 141.18, "text": "We say the class can shatter that set."}, {"t0": 141.18, "t1": 142.99, "text": "It measures capacity."}, {"t0": 142.99, "t1": 148.77, "text": "For linear classifiers in d dimensions, the VC dimension is d plus one."}, {"t0": 148.77, "t1": 157.89, "text": "In generalization bounds, the gap between training and test error grows with the VC dimension and shrinks with the number of samples."}]]}, {"title": "REINFORCE, asked by Professor Hochreiter", "paras": [[{"t0": 159.21, "t1": 162.68, "text": "We want the policy with the largest expected return."}, {"t0": 162.68, "t1": 170.23, "text": "The expected return J of theta is the integral over trajectories of the probability of a trajectory, times its return."}], [{"t0": 170.89, "t1": 177.44, "text": "The trick is the log-derivative trick: the gradient of p equals p times the gradient of log p."}, {"t0": 177.44, "t1": 183.36, "text": "That moves the gradient inside the expectation, so we can estimate it from sampled episodes."}], [{"t0": 184.02, "t1": 187.43, "text": "Now write the log-probability of a trajectory."}, {"t0": 187.43, "t1": 195.2, "text": "It is the log of the start state, plus the sum over time of the log-policy, plus the log of the environment dynamics."}, {"t0": 195.2, "t1": 198.54, "text": "The environment does not depend on the policy parameters."}, {"t0": 198.54, "t1": 203.02, "text": "So when we take the gradient, only the policy terms survive."}], [{"t0": 203.7, "t1": 214.34, "text": "The result: the gradient of J is the expected value of the sum over time of the gradient of log pi of a t given s t, times the return G t."}, {"t0": 214.34, "t1": 221.9, "text": "As a loss to minimise, we write minus the sum of log pi of the action, times the return minus a baseline."}, {"t0": 221.9, "t1": 227.22, "text": "The baseline does not change the expected gradient, but it reduces the variance."}]]}, {"title": "How do you evaluate a classifier?", "paras": [[{"t0": 228.54, "t1": 234.16, "text": "With the confusion matrix, precision, recall and the area under the ROC curve."}], [{"t0": 234.82, "t1": 239.52, "text": "Precision: of everything I called positive, how much is right?"}, {"t0": 239.52, "t1": 243.43, "text": "True positives over true positives plus false positives."}, {"t0": 243.43, "t1": 247.71, "text": "Recall: of all real positives, how many did I find?"}, {"t0": 247.71, "t1": 251.66, "text": "True positives over true positives plus false negatives."}, {"t0": 251.66, "t1": 257.38, "text": "A simple way to remember: precision is how clean, recall is how complete."}], [{"t0": 258.05, "t1": 264.66, "text": "The ROC curve plots the true-positive rate against the false-positive rate, over all thresholds."}, {"t0": 264.66, "t1": 270.81, "text": "The AUC is the probability that a random positive gets a higher score than a random negative."}, {"t0": 270.81, "t1": 274.05, "text": "An AUC of 0.5 is chance."}, {"t0": 274.05, "t1": 276.58, "text": "An AUC of one is perfect."}]]}, {"title": "How else can you measure robustness?", "paras": [[{"t0": 277.9, "t1": 284.53, "text": "Professor Klambauer has asked: besides adversarial attacks, how else can you measure robustness?"}, {"t0": 284.53, "t1": 290.82, "text": "Test under distribution shift: corrupted inputs, new domains, data from another time."}, {"t0": 290.82, "t1": 296.65, "text": "Check calibration and uncertainty, with ensembles or Monte Carlo dropout."}, {"t0": 296.65, "t1": 301.11, "text": "And check how sensitive the output is to small changes of the input."}], [{"t0": 301.78, "t1": 304.51, "text": "And here you can bring in your own thesis."}, {"t0": 304.51, "t1": 310.35, "text": "A recording made under one boundary condition fails under another, because the regime changed."}, {"t0": 310.35, "t1": 314.06, "text": "That is distribution shift, in a physics simulation."}, {"t0": 314.06, "t1": 316.6, "text": "It is a strong, personal answer."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 317.91, "t1": 318.76, "text": "One."}, {"t0": 318.76, "t1": 327.48, "text": "SVM: maximum margin; the dual has only dot products, so a kernel gives a non-linear classifier at linear cost."}, {"t0": 327.48, "t1": 332.34, "text": "Linear classifiers in d dimensions have VC dimension d plus one."}], [{"t0": 333.0, "t1": 333.79, "text": "Two."}, {"t0": 333.79, "t1": 342.75, "text": "REINFORCE: the log-derivative trick, the dynamics drop out, and the loss is minus log pi times the return minus a baseline."}], [{"t0": 343.41, "t1": 344.31, "text": "Three."}, {"t0": 344.31, "t1": 350.09, "text": "Precision is how clean, recall is how complete, AUC is ranking quality."}, {"t0": 350.09, "t1": 357.39, "text": "Robustness: distribution shift, calibration, sensitivity, and your own regime example."}]]}]}, {"id": "T1", "group": "T", "title": "T1 · My thesis in plain words", "file": "tracks/T1.mp3", "voice": "Ava", "duration": 307.0, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 2.46, "text": "My thesis in plain words."}], [{"t0": 3.12, "t1": 8.26, "text": "Here is a question you will almost certainly hear on the day: what problem did you solve?"}, {"t0": 8.26, "t1": 13.87, "text": "So let's practise the answer, slowly, until it feels like your own story."}], [{"t0": 14.52, "t1": 16.05, "text": "Start with the method."}, {"t0": 16.05, "t1": 19.61, "text": "Recurrence CFD is a way to make simulation cheap."}, {"t0": 19.61, "t1": 22.69, "text": "You run one normal, full simulation."}, {"t0": 22.69, "t1": 29.18, "text": "While it runs, you record, frame by frame, which share of each cell moves to which other cell."}, {"t0": 29.18, "t1": 33.2, "text": "After that, you never solve the velocity or the pressure again."}, {"t0": 33.2, "t1": 38.24, "text": "You simply replay the stored motion, and you use it to carry something through the tank."}, {"t0": 38.24, "t1": 40.55, "text": "That is why it is fast."}, {"t0": 40.55, "t1": 46.62, "text": "In my case, the full simulation took 569 minutes of solver time."}, {"t0": 46.62, "t1": 49.18, "text": "One replay took about two minutes."}, {"t0": 49.18, "t1": 52.37, "text": "That is roughly 260 times faster."}], [{"t0": 53.04, "t1": 54.86, "text": "Now, here is the catch."}, {"t0": 54.86, "t1": 57.93, "text": "The method was built for passive scalars."}, {"t0": 57.93, "t1": 63.65, "text": "A passive scalar is something that rides along with the flow but does not change it, like a dye."}, {"t0": 63.65, "t1": 65.78, "text": "Temperature is not like that."}, {"t0": 65.78, "t1": 68.88, "text": "Warm water is lighter, so it rises."}, {"t0": 68.88, "t1": 71.99, "text": "Temperature drives the flow by buoyancy."}, {"t0": 71.99, "t1": 76.92, "text": "So when the replay keeps the recorded motion fixed, it cuts that feedback."}], [{"t0": 77.59, "t1": 81.39, "text": "So the answer to \"what problem did you solve?\" is this."}, {"t0": 81.39, "t1": 87.18, "text": "I tested recurrence CFD on temperature, a scalar that drives its own flow."}, {"t0": 87.18, "t1": 93.11, "text": "I measured what the replay loses, and how much I can repair without solving the flow again."}]]}, {"title": "Why should anybody care?", "paras": [[{"t0": 94.41, "t1": 97.98, "text": "The second question is often: why should I care?"}, {"t0": 97.98, "t1": 100.45, "text": "Here is a short, honest answer."}, {"t0": 100.45, "t1": 107.03, "text": "Thermal processes run for hours, and full CFD of that time is too slow for daily use."}, {"t0": 107.03, "t1": 111.75, "text": "A replay that is 260 times faster sounds wonderful."}, {"t0": 111.75, "t1": 115.41, "text": "But a fast model is only useful if you know its error."}, {"t0": 115.41, "t1": 122.64, "text": "My thesis measures that error, for a case where temperature matters, and it shows which part of the error can be repaired."}], [{"t0": 123.3, "t1": 126.3, "text": "Fast is useful only with a known error."}, {"t0": 126.3, "t1": 128.52, "text": "Say that sentence slowly."}, {"t0": 128.52, "t1": 129.93, "text": "It is a good line."}]]}, {"title": "Recurrence CFD in simple words", "paras": [[{"t0": 131.25, "t1": 136.16, "text": "If they ask you to explain recurrence CFD simply, use the traffic camera."}, {"t0": 136.16, "t1": 140.36, "text": "Imagine a camera that records the route of every car in a city."}, {"t0": 140.36, "t1": 143.67, "text": "Next time, you do not simulate the drivers."}, {"t0": 143.67, "t1": 147.01, "text": "You reuse the recorded routes to move parcels around."}, {"t0": 147.01, "t1": 148.49, "text": "That is the replay."}], [{"t0": 149.15, "t1": 153.91, "text": "But every analogy has a limit, and examiners love the limit."}, {"t0": 153.91, "t1": 157.82, "text": "Here it is: the recording does not store pictures."}, {"t0": 157.82, "t1": 161.79, "text": "It stores maps of how much fluid goes from cell to cell."}, {"t0": 161.79, "t1": 166.92, "text": "And if the parcels are heavy enough to change the traffic, the old routes are wrong."}, {"t0": 166.92, "t1": 168.47, "text": "That is temperature."}], [{"t0": 169.14, "t1": 171.98, "text": "One replay step has four stages."}, {"t0": 171.98, "t1": 176.63, "text": "Remember them as map, swap, correct, balance."}, {"t0": 176.63, "t1": 180.11, "text": "Map: the recorded map moves the heat."}, {"t0": 180.11, "t1": 185.09, "text": "Swap: a face exchange adds a little mixing between neighbours."}, {"t0": 185.09, "t1": 189.74, "text": "Correct: this is my contribution, the correction stage."}, {"t0": 189.74, "t1": 194.49, "text": "Balance: a conservation constraint fixes the total heat."}, {"t0": 194.49, "t1": 199.1, "text": "In standard recurrence CFD, the correction stage does nothing."}, {"t0": 199.1, "t1": 202.15, "text": "In my thesis, it does the real work."}]]}, {"title": "Why is this AI, and not only CFD?", "paras": [[{"t0": 203.46, "t1": 206.84, "text": "This question came up in earlier defenses, so be ready."}, {"t0": 206.84, "t1": 210.1, "text": "Recurrence CFD is a data-based simulation."}, {"t0": 210.1, "t1": 214.83, "text": "An expensive solver produces data, and a cheap model reuses it."}, {"t0": 214.83, "t1": 218.93, "text": "The database of recorded states plays the role of training data."}, {"t0": 218.93, "t1": 225.23, "text": "Choosing the next frame is a nearest-neighbour search in that database, which is the old method of analogues."}], [{"t0": 225.9, "t1": 230.06, "text": "And my main finding is really a finding about generalization."}, {"t0": 230.06, "t1": 233.02, "text": "A database belongs to a flow regime."}, {"t0": 233.02, "t1": 238.43, "text": "If a boundary condition changes the regime, the database is out of distribution."}, {"t0": 238.43, "t1": 244.16, "text": "In machine learning words: the test data no longer looks like the training data."}, {"t0": 244.16, "t1": 248.28, "text": "That is exactly what happens when the lid of my tank gets cold."}]]}, {"title": "The test case", "paras": [[{"t0": 249.59, "t1": 252.51, "text": "You should be able to describe the tank without notes."}, {"t0": 252.51, "t1": 259.58, "text": "A closed tank, seventy-five by seventy-five by fifteen millimetres, with one-millimetre cells."}, {"t0": 259.58, "t1": 269.58, "text": "A warm jet enters at mid-height, at 333 kelvin and 0.02 metres per second, for 315 seconds."}, {"t0": 269.58, "t1": 274.47, "text": "The Reynolds number is about 99, so the flow is laminar."}, {"t0": 274.47, "t1": 279.36, "text": "And there are two versions of the lid: an insulated one, and a cooled one."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 280.67, "t1": 281.55, "text": "One."}, {"t0": 281.55, "t1": 288.66, "text": "The problem: recurrence CFD was built for a dye, and I tested it on temperature, which pushes back on the flow."}], [{"t0": 289.33, "t1": 290.08, "text": "Two."}, {"t0": 290.08, "t1": 297.68, "text": "The value: 260 times faster, but fast is useful only with a known error, and I measure that error."}], [{"t0": 298.35, "t1": 299.2, "text": "Three."}, {"t0": 299.2, "t1": 306.98, "text": "The AI view: the database is training data, and a new flow regime means the data is out of distribution."}]]}]}, {"id": "T2", "group": "T", "title": "T2 · Inside the replay: the knob, the drain, and the limiter", "file": "tracks/T2.mp3", "voice": "Ava", "duration": 428.9, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 4.52, "text": "Inside the replay: the knob, the drain, and the limiter."}], [{"t0": 5.18, "t1": 12.39, "text": "This episode is about the heart of the thesis: why the standard replay goes wrong, and how the correction fixes it."}, {"t0": 12.39, "t1": 18.6, "text": "If you can tell this story clearly, you can answer most questions about chapters four and five."}]]}, {"title": "Is the flow recurrent?", "paras": [[{"t0": 19.92, "t1": 25.44, "text": "Let's start with a question Professor Pirker may ask: is your flow actually recurrent?"}, {"t0": 25.44, "t1": 27.33, "text": "The honest answer is no."}], [{"t0": 27.98, "t1": 32.29, "text": "The recurrence matrix compares every pair of recorded states."}, {"t0": 32.29, "t1": 38.37, "text": "A small distance means two states look alike, so the replay could jump from one to the other."}, {"t0": 38.37, "t1": 43.61, "text": "In my tank, the matrix shows two blocks: filling and settling."}, {"t0": 43.61, "t1": 46.03, "text": "And no state ever comes back."}, {"t0": 46.03, "t1": 51.67, "text": "The method asks for a prominence of about 0.05 to 0.1."}, {"t0": 51.67, "t1": 56.08, "text": "My tank has a median of 0.028."}, {"t0": 56.08, "t1": 59.25, "text": "So the replay simply plays the frames in order."}], [{"t0": 59.92, "t1": 62.91, "text": "Is it still recurrence CFD, then?"}, {"t0": 62.91, "t1": 63.93, "text": "Yes."}, {"t0": 63.93, "t1": 67.36, "text": "The saving does not come from jumping between frames."}, {"t0": 67.36, "t1": 71.02, "text": "It comes from never solving velocity and pressure again."}]]}, {"title": "The face exchange, and the knob", "paras": [[{"t0": 72.33, "t1": 75.25, "text": "A pure displacement does not mix anything."}, {"t0": 75.25, "t1": 83.85, "text": "So after each move, the replay library swaps a share of heat across every face, from the warm cell to the cold one."}, {"t0": 83.85, "t1": 87.73, "text": "The strength of this swap per step is called f s d."}, {"t0": 87.73, "t1": 93.35, "text": "It has no unit, so it is not a diffusion coefficient, but you can translate it into one."}], [{"t0": 94.0, "t1": 96.23, "text": "Here is the key property."}, {"t0": 96.23, "t1": 98.89, "text": "The exchange can only reduce differences."}, {"t0": 98.89, "t1": 102.34, "text": "It can never rebuild a front that has already been smeared."}]]}, {"title": "No single best setting", "paras": [[{"t0": 103.65, "t1": 105.83, "text": "I ran seven strengths."}, {"t0": 105.83, "t1": 114.16, "text": "The heat content of the tank is best with no added mixing: the error of the mean temperature is 1.07 kelvin."}, {"t0": 114.16, "t1": 121.87, "text": "The height of the warm layer is best near one half: an error of only 0.068 millimetres."}, {"t0": 121.87, "t1": 125.01, "text": "So no single value is best for both."}, {"t0": 125.01, "t1": 131.05, "text": "And with the strongest mixing, the tank ends 5.08 kelvin too cold."}], [{"t0": 131.7, "t1": 133.98, "text": "Why does more mixing lose heat?"}, {"t0": 133.98, "t1": 138.7, "text": "Picture a bathtub with the drain placed just below the warm surface layer."}, {"t0": 138.7, "t1": 142.64, "text": "If the layer stays thin, the drain takes cold water."}, {"t0": 142.64, "t1": 147.86, "text": "If you smear the layer downwards, warm water reaches the drain and leaves."}, {"t0": 147.86, "t1": 151.47, "text": "In my tank, the outlet sits just below the front."}, {"t0": 151.47, "t1": 154.67, "text": "So a smeared front turns into a heat leak."}], [{"t0": 155.34, "t1": 158.83, "text": "I showed this with the energy balance of the whole tank."}, {"t0": 158.83, "t1": 163.04, "text": "Energy in minus energy out gives the outlet temperature."}, {"t0": 163.04, "t1": 169.19, "text": "During the warm inflow, the standard replay keeps about 2.7 kelvin too much."}, {"t0": 169.19, "t1": 173.86, "text": "After the inflow, it drains 4.6 kelvin through the outlet."}], [{"t0": 174.52, "t1": 176.81, "text": "And who smears the front?"}, {"t0": 176.81, "t1": 178.02, "text": "I checked."}, {"t0": 178.02, "t1": 184.88, "text": "With the recorded maps alone, the front at 240 seconds is 2.5 millimetres."}, {"t0": 184.88, "t1": 188.12, "text": "With the standard exchange, 19.3."}, {"t0": 188.12, "t1": 190.56, "text": "The reference has 4.5."}, {"t0": 190.56, "t1": 192.18, "text": "So the maps are fine."}, {"t0": 192.18, "t1": 193.89, "text": "The exchange is guilty."}]]}, {"title": "Why not just use negative diffusion?", "paras": [[{"t0": 195.2, "t1": 197.81, "text": "This is a classic examiner question."}, {"t0": 197.81, "t1": 199.24, "text": "Diffusion smooths."}, {"t0": 199.24, "t1": 202.76, "text": "So why not run it backwards to sharpen the front?"}], [{"t0": 203.43, "t1": 206.44, "text": "Because negative diffusion is ill-posed."}, {"t0": 206.44, "t1": 211.76, "text": "It amplifies every disturbance, and the shortest wiggles grow fastest."}, {"t0": 211.76, "t1": 214.3, "text": "You can show it with one Fourier mode."}, {"t0": 214.3, "t1": 222.55, "text": "For the explicit diffusion step, the growth factor is one minus four nu times sine squared of k delta x over two."}, {"t0": 222.55, "t1": 229.89, "text": "For a negative nu and the shortest mode, the factor is one plus four times the absolute value of nu."}, {"t0": 229.89, "t1": 234.21, "text": "That is larger than one, so the wiggle grows at every step."}, {"t0": 234.21, "t1": 239.82, "text": "In my one-dimensional test, after 21 steps, the field left the range of the data."}], [{"t0": 240.49, "t1": 245.92, "text": "So I keep the useful part, the steepening, and I stop the dangerous part with a limiter."}]]}, {"title": "The limiter", "paras": [[{"t0": 247.23, "t1": 253.75, "text": "For every cell, take the smallest and the largest value among the cell and its neighbours."}, {"t0": 253.75, "t1": 255.69, "text": "Those are its local bounds."}, {"t0": 255.69, "t1": 259.84, "text": "The headroom of the warm cell is how far it can still rise."}, {"t0": 259.84, "t1": 263.71, "text": "The headroom of the cold cell is how far it can still fall."}, {"t0": 263.71, "t1": 273.66, "text": "Across a face, heat moves uphill, from the colder cell to the warmer one, and the amount is the smaller of the two headrooms, times a strength s."}], [{"t0": 274.33, "t1": 277.0, "text": "So no cell can leave its bounds."}, {"t0": 277.0, "t1": 281.26, "text": "A maximum cannot grow, a minimum cannot sink."}, {"t0": 281.26, "t1": 287.48, "text": "And the heat that leaves one cell enters the other, so energy is conserved face by face."}, {"t0": 287.48, "t1": 294.16, "text": "This is the limiter idea of flux-corrected transport, from Boris and Book, and from Zalesak."}], [{"t0": 294.82, "t1": 296.72, "text": "There is also a neat bound."}, {"t0": 296.72, "t1": 299.68, "text": "A hexahedral cell has six faces."}, {"t0": 299.68, "t1": 306.57, "text": "If s is at most one sixth, no cell can leave its bounds even before any clamp acts."}, {"t0": 306.57, "t1": 315.94, "text": "My working range, 0.40 to 0.50, is above that, so it relies on the clamp and on the global conservation constraint."}, {"t0": 315.94, "t1": 318.41, "text": "Say that honestly if they ask."}]]}, {"title": "Why the vertical weight?", "paras": [[{"t0": 319.73, "t1": 321.85, "text": "The front is horizontal."}, {"t0": 321.85, "t1": 325.49, "text": "So the correction should act across it, not along it."}, {"t0": 325.49, "t1": 330.8, "text": "Each face gets the weight cosine squared of the angle between its link and the vertical."}, {"t0": 330.8, "t1": 335.2, "text": "Faces across the front get one, faces along it get zero."}, {"t0": 335.2, "t1": 339.07, "text": "Without the weight, the correction roughens the front sideways."}, {"t0": 339.07, "t1": 346.53, "text": "Mathematically, this weight is exactly the face coefficient of a diffusion that acts in one direction only."}]]}, {"title": "The recorded diffusivity did not help", "paras": [[{"t0": 347.86, "t1": 350.59, "text": "One more result you must be able to explain."}, {"t0": 350.59, "t1": 355.64, "text": "I also tried a recorded, local diffusivity instead of the constant knob."}, {"t0": 355.64, "t1": 359.43, "text": "It changed nothing, and the replays were bit-identical."}, {"t0": 359.43, "t1": 360.3, "text": "Why?"}, {"t0": 360.3, "t1": 364.94, "text": "The recorded values ask for more exchange than the explicit step can apply."}, {"t0": 364.94, "t1": 370.5, "text": "Every face hits the cap, so the field behaves exactly like the constant setting."}, {"t0": 370.5, "t1": 374.82, "text": "A shorter time step or an implicit exchange would let it act."}]]}, {"title": "The result", "paras": [[{"t0": 376.13, "t1": 383.81, "text": "With the correction, the end front goes from 15.7 millimetres to between 5.3 and 4.5."}, {"t0": 383.81, "t1": 386.39, "text": "The reference has 5.0."}, {"t0": 386.39, "t1": 393.04, "text": "The error of the mean temperature over the run drops from 1.46 to about 0.7 kelvin."}, {"t0": 393.04, "t1": 398.64, "text": "And remember the honest sentence: the strength was chosen against the same reference."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 399.94, "t1": 400.78, "text": "One."}, {"t0": 400.78, "t1": 407.1, "text": "No single knob setting works, because the outlet below the front drains the heat of a smeared front."}], [{"t0": 407.76, "t1": 408.52, "text": "Two."}, {"t0": 408.52, "t1": 411.25, "text": "Negative diffusion grows wiggles."}, {"t0": 411.25, "t1": 418.38, "text": "The limiter keeps the steepening and stays inside the neighbours' bounds, so no new extremes and no lost heat."}], [{"t0": 419.04, "t1": 419.99, "text": "Three."}, {"t0": 419.99, "t1": 428.88, "text": "15.7 millimetres becomes about 5, the reference is 5.0, and the strength was chosen with the reference."}]]}]}, {"id": "T3", "group": "T", "title": "T3 · The cold lid, the limits, and how I know I am right", "file": "tracks/T3.mp3", "voice": "Ava", "duration": 397.7, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 3.94, "text": "The cold lid, the limits, and how I know I am right."}], [{"t0": 4.61, "t1": 9.2, "text": "In this episode we go to the harder half of the thesis: the cooled lid."}, {"t0": 9.2, "t1": 12.96, "text": "Then we practise the questions every committee asks at the end."}, {"t0": 12.96, "t1": 15.08, "text": "How do you know your results are correct?"}, {"t0": 15.08, "t1": 16.67, "text": "What would you do differently?"}, {"t0": 16.67, "t1": 19.25, "text": "And which papers shaped your work?"}]]}, {"title": "When the lid gets cold", "paras": [[{"t0": 20.57, "t1": 23.31, "text": "Up to now, the lid was insulated."}, {"t0": 23.31, "t1": 27.19, "text": "Heat came in with the jet and left through the outlet, and that was it."}, {"t0": 27.19, "t1": 30.15, "text": "Now the lid loses heat to the outside."}, {"t0": 30.15, "t1": 32.45, "text": "And this changes the physics."}, {"t0": 32.45, "t1": 37.91, "text": "Cold water forms under the lid, it is heavier, so it sinks in plumes."}, {"t0": 37.91, "t1": 41.04, "text": "The layer above the front starts to overturn."}, {"t0": 41.04, "t1": 44.41, "text": "So now the temperature creates its own motion."}, {"t0": 44.41, "t1": 50.73, "text": "That is exactly the feedback that a replay cannot reproduce, because the motion is fixed in the recording."}], [{"t0": 51.41, "t1": 56.52, "text": "Every replay in this chapter uses the same fluid properties as the reference."}, {"t0": 56.52, "t1": 61.09, "text": "Keep that sentence ready, because it rules out a whole family of questions."}]]}, {"title": "What the replay gets right", "paras": [[{"t0": 62.4, "t1": 66.78, "text": "Over the run, the tank cools by 9.62 kelvin."}, {"t0": 66.78, "t1": 71.62, "text": "The standard replay ends 0.66 kelvin too cold."}, {"t0": 71.62, "t1": 75.01, "text": "That sounds small, and it is, for the heat content."}, {"t0": 75.01, "t1": 76.87, "text": "But look at where the heat is."}, {"t0": 76.87, "t1": 86.12, "text": "The end profile of the standard replay departs by 2.79 kelvin: the bulk is too warm, and the top layer is too cold."}, {"t0": 86.12, "t1": 88.43, "text": "Same heat, wrong place."}], [{"t0": 89.08, "t1": 108.74, "text": "With the correction, at strengths between 0.475 and 0.55, the end error of the heat content is between minus 0.04 and plus 0.06 kelvin, and the end profile improves to between 0.59 and 0.41 kelvin."}, {"t0": 108.74, "t1": 111.92, "text": "So the correction puts the heat back in the right layer."}, {"t0": 111.92, "t1": 116.95, "text": "And again, say it honestly: these strengths were chosen with the reference."}], [{"t0": 117.62, "t1": 120.96, "text": "This is why I always report two kinds of measure."}, {"t0": 120.96, "t1": 124.03, "text": "The mean temperature says how much heat there is."}, {"t0": 124.03, "t1": 127.58, "text": "The profile and the front width say where it is."}, {"t0": 127.58, "t1": 131.2, "text": "A replay can be right on one and wrong on the other."}]]}, {"title": "What cannot be repaired", "paras": [[{"t0": 132.52, "t1": 134.91, "text": "Now the defect that survives."}, {"t0": 134.91, "t1": 139.12, "text": "While the tank fills, the layers separate too slowly."}, {"t0": 139.12, "t1": 143.16, "text": "I tried six local variants, and none of them moved this lag."}, {"t0": 143.16, "t1": 144.0, "text": "Why?"}], [{"t0": 144.66, "t1": 146.97, "text": "Here is the cleanest way to say it."}, {"t0": 146.97, "t1": 150.43, "text": "A local correction only moves heat between neighbours."}, {"t0": 150.43, "t1": 156.94, "text": "It can change the shape of a front, but it cannot carry heat from one layer to another layer far away."}, {"t0": 156.94, "t1": 158.44, "text": "That is transport."}, {"t0": 158.44, "t1": 162.81, "text": "So the lag is missing transport, not missing sharpness."}], [{"t0": 163.48, "t1": 166.03, "text": "Then I tried to supply that transport."}, {"t0": 166.03, "t1": 175.78, "text": "During the recording, I stored a vertical heat flux: the part of the heat carried by the vertical velocity, relative to the mean of a horizontal band."}, {"t0": 175.78, "t1": 177.88, "text": "In the replay, I applied it."}, {"t0": 177.88, "t1": 184.36, "text": "And it works: the layering lag drops from 2.25 to 0.45 kelvin."}, {"t0": 184.36, "t1": 186.3, "text": "But it has a price."}, {"t0": 186.3, "t1": 190.21, "text": "The tank then ends 0.86 kelvin too cold."}]]}, {"title": "Why the recording cannot do it alone", "paras": [[{"t0": 191.53, "t1": 194.68, "text": "The final piece of the story is the flow regime."}, {"t0": 194.68, "t1": 199.3, "text": "Compare how fast each recording changes over short time lags."}, {"t0": 199.3, "t1": 206.46, "text": "After the inflow, the cooled flow keeps renewing itself, about ten times faster than the insulated one."}, {"t0": 206.46, "t1": 212.73, "text": "So a recording made without the cold lid simply does not contain the motion of the cooled case."}, {"t0": 212.73, "t1": 217.11, "text": "A database belongs to a flow regime, not to a case."}, {"t0": 217.11, "t1": 221.95, "text": "In machine learning language: a new regime is out of distribution."}]]}, {"title": "How do you know your results are correct?", "paras": [[{"t0": 223.26, "t1": 225.82, "text": "This came up in earlier defenses."}, {"t0": 225.82, "t1": 227.91, "text": "Give three short points."}], [{"t0": 228.56, "t1": 231.69, "text": "First, every replay is deterministic."}, {"t0": 231.69, "t1": 235.19, "text": "A rerun gives the same trace, bit for bit."}, {"t0": 235.19, "t1": 239.87, "text": "So any difference between two runs comes from the one setting I changed."}], [{"t0": 240.51, "t1": 251.69, "text": "Second, I compare replay and reference at the same instants, and over the same end window, from 580 to 599 seconds, on both sides."}], [{"t0": 252.34, "t1": 256.84, "text": "Third, I close the energy budget of each case, term by term."}, {"t0": 256.84, "t1": 260.78, "text": "If the heat does not add up, I know before I interpret anything."}]]}, {"title": "Why bias and RMSE?", "paras": [[{"t0": 262.09, "t1": 267.86, "text": "On a trace, the bias tells you the side of the error, too warm or too cold."}, {"t0": 267.86, "t1": 270.87, "text": "The root mean square error tells you the size."}, {"t0": 270.87, "t1": 274.44, "text": "And there is a neat identity you can derive on the board."}, {"t0": 274.44, "t1": 279.01, "text": "RMSE squared equals bias squared plus the variance of the error."}, {"t0": 279.01, "t1": 282.05, "text": "So it separates an offset from a wrong shape."}]]}, {"title": "Two physics checks", "paras": [[{"t0": 283.38, "t1": 285.32, "text": "Why is the flow laminar?"}, {"t0": 285.32, "t1": 294.91, "text": "The jet enters at 0.02 metres per second through five millimetres, so the Reynolds number is about 99, far below transition."}, {"t0": 294.91, "t1": 304.31, "text": "And the Richardson number is 1.84: buoyancy is slightly stronger than inertia, so the jet bends upwards within a few inlet widths."}], [{"t0": 304.97, "t1": 307.4, "text": "Why the Boussinesq approximation?"}, {"t0": 307.4, "t1": 311.43, "text": "The density changes only a little over this temperature range."}, {"t0": 311.43, "t1": 315.43, "text": "So we keep it constant everywhere, except in the gravity term."}, {"t0": 315.43, "t1": 322.14, "text": "And here is the nice link to the thesis: that buoyancy term is exactly the link the replay cuts."}]]}, {"title": "What would you do differently? Future work", "paras": [[{"t0": 323.45, "t1": 324.68, "text": "Three things."}, {"t0": 324.68, "t1": 330.58, "text": "Let the recorded diffusivity act, with an implicit exchange or a shorter time step."}, {"t0": 330.58, "t1": 336.33, "text": "Split the conservation constraint into compartments, so it does not push heat back to the front."}, {"t0": 336.33, "t1": 343.51, "text": "And use several recordings, chosen by the state of the replayed temperature, so that more than one regime is covered."}]]}, {"title": "Which papers influenced you most?", "paras": [[{"t0": 344.81, "t1": 352.06, "text": "Lichtenegger and Pirker, 2016, which introduced recurrence CFD and the recurrence matrix."}, {"t0": 352.06, "t1": 359.1, "text": "Pirker and colleagues, 2018, for the face exchange and the conservation constraint."}, {"t0": 359.1, "t1": 366.6, "text": "And Zalesak, 1979, for the local bounds of flux-corrected transport that my limiter uses."}]]}, {"title": "Three things to remember", "paras": [[{"t0": 367.9, "t1": 368.69, "text": "One."}, {"t0": 368.69, "t1": 375.99, "text": "Under the cold lid, the heat content is right, but the layers separate too slowly: that is missing transport."}], [{"t0": 376.66, "t1": 377.45, "text": "Two."}, {"t0": 377.45, "t1": 387.41, "text": "A recorded flux reduces the lag from 2.25 to 0.45 kelvin, but the tank then ends 0.86 kelvin too cold."}], [{"t0": 388.06, "t1": 388.93, "text": "Three."}, {"t0": 388.93, "t1": 397.62, "text": "I know I am right because replays are deterministic, one change per run, the same clock on both sides, and a closed energy budget."}]]}]}, {"id": "A1-id", "group": "A-id", "title": "A1 · Recurrence CFD, seperti diajarkan Profesor Pirker", "file": "tracks/A1-id.mp3", "voice": "Gadis", "duration": 543.5, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 5.74, "text": "Recurrence CFD, seperti diajarkan Profesor Pirker."}], [{"t0": 6.36, "t1": 14.17, "text": "Profesor Pirker adalah pembimbing Anda, dan beliau mengajar Numerical Methods in Fluid Mechanics."}, {"t0": 14.17, "t1": 21.79, "text": "Kemungkinan besar beliau akan bertanya seputar recurrence CFD dan gambar-gambar di tesis Anda."}, {"t0": 21.79, "t1": 36.57, "text": "Di episode ini kita telusuri recurrence CFD sesuai alur kuliah beliau, supaya jawaban Anda terdengar seperti bahasa kuliahnya, lalu setiap ide kita kaitkan dengan pekerjaan Anda sendiri."}]]}, {"title": "Kenapa recurrence CFD?", "paras": [[{"t0": 37.82, "t1": 40.7, "text": "Mulai dari gambaran besar."}, {"t0": 40.7, "t1": 46.24, "text": "Banyak aliran industri berjalan lama dan menunjukkan pola yang berulang."}, {"t0": 46.24, "t1": 52.73, "text": "Contohnya bubble column, fluidized bed, atau stirred vessel yang turbulen."}, {"t0": 52.73, "t1": 60.04, "text": "Menghitung momentum dan tekanan sepanjang waktu itu sia-sia ketika alirannya terus mengulang dirinya."}], [{"t0": 60.65, "t1": 68.28, "text": "Jadi recurrence CFD membuat sebuah prediksi berani: pakai ulang aliran yang sudah direkam."}, {"t0": 68.28, "t1": 77.95, "text": "Lalu prediksi itu dikoreksi dengan fisika, di mana pun pemakaian ulang tadi merusak sesuatu, misalnya neraca massa."}], [{"t0": 78.57, "t1": 83.09, "text": "Ada cara bagus untuk mengaitkannya dengan kuliah."}, {"t0": 83.09, "t1": 87.02, "text": "Algoritma SIMPLE melakukan hal yang serupa."}, {"t0": 87.02, "t1": 95.33, "text": "SIMPLE menebak tekanan, menghitung kecepatan, lalu mengoreksi tekanan dari persamaan kontinuitas."}, {"t0": 95.33, "t1": 101.44, "text": "Recurrence CFD menebak aliran dari rekaman, lalu mengoreksinya."}, {"t0": 101.44, "t1": 106.44, "text": "Prediksi berani, lalu koreksi berbasis fisika."}, {"t0": 106.44, "t1": 117.31, "text": "Kalau Anda mengucapkan kalimat itu dalam bahasa Inggris, bold prediction plus physics-based correction, Anda sedang berbicara dengan bahasa beliau."}]]}, {"title": "Flow-based dan transport-based", "paras": [[{"t0": 118.58, "t1": 121.17, "text": "Ada dua keluarga."}, {"t0": 121.17, "t1": 137.24, "text": "Flow-based recurrence CFD, dari Lichtenegger dan Pirker tahun 2016, menyambung potongan-potongan aliran terekam menjadi satu aliran buatan yang panjang, dan masih menyelesaikan persamaan transport di atasnya."}, {"t0": 137.24, "t1": 142.32, "text": "Kira-kira 100 kali lebih cepat daripada CFD penuh."}], [{"t0": 142.94, "t1": 152.23, "text": "Transport-based recurrence CFD, dari Pirker dan Lichtenegger tahun 2018, melangkah lebih jauh."}, {"t0": 152.23, "t1": 160.04, "text": "Persamaan transport tidak diselesaikan sama sekali, melainkan diganti dengan cell shift dan face swap."}, {"t0": 160.04, "t1": 171.66, "text": "Contoh di kuliah adalah ladle baja: 26 jam CFD penuh, dibandingkan 1,6 detik recurrence CFD berbasis transport."}], [{"t0": 172.26, "t1": 179.92, "text": "Tesis Anda memakai bentuk transport-based, ditambah correction hook dan conservation constraint."}]]}, {"title": "Recurrence norm, matrix, plateau, dan prominence", "paras": [[{"t0": 181.19, "t1": 186.75, "text": "Recurrence norm mengukur seberapa berbeda dua keadaan yang terekam."}, {"t0": 186.75, "t1": 193.8, "text": "Hitung untuk semua pasangan, normalkan, dan hasilnya recurrence matrix."}], [{"t0": 194.41, "t1": 198.33, "text": "Sekarang ambil satu baris matriks itu."}, {"t0": 198.33, "t1": 206.24, "text": "Baris itu dimulai dari nol di diagonal, karena sebuah keadaan identik dengan dirinya sendiri."}, {"t0": 206.24, "t1": 211.42, "text": "Lalu nilainya naik dan berosilasi di sekitar sebuah plateau."}, {"t0": 211.42, "t1": 219.9, "text": "Kalau barisnya turun jauh di bawah plateau, aliran kembali ke keadaan yang mirip dengan keadaan sebelumnya."}, {"t0": 219.9, "t1": 225.18, "text": "Itulah recurrence, dan replay bisa melompat ke sana."}, {"t0": 225.18, "t1": 231.89, "text": "Prominence mengukur seberapa dalam penurunan itu, relatif terhadap plateau."}], [{"t0": 232.55, "t1": 239.25, "text": "Metodenya meminta prominence sekitar 0,05 sampai 0,1."}, {"t0": 239.25, "t1": 243.95, "text": "Tangki Anda punya median 0,028."}, {"t0": 243.95, "t1": 250.23, "text": "Jadi penurunannya dangkal, dan replay memutar frame secara berurutan."}, {"t0": 250.23, "t1": 261.74, "text": "Katakan dengan terus terang: aliran saya tidak recurrent, dan itu tidak masalah, karena penghematannya datang dari tidak menghitung kecepatan dan tekanan."}]]}, {"title": "Tiga kegagalan berani", "paras": [[{"t0": 263.0, "t1": 270.69, "text": "Kuliahnya menyebut tiga bold failure dari recurrence CFD, masing-masing dengan koreksinya."}, {"t0": 270.69, "t1": 274.23, "text": "Hafalkan sebagai tiga pasangan."}], [{"t0": 274.83, "t1": 278.79, "text": "Pertama, ketidakseimbangan massa."}, {"t0": 278.79, "t1": 282.95, "text": "Cell shift tidak menjaga massa secara lokal."}, {"t0": 282.95, "t1": 289.98, "text": "Jadi sebuah monitor global mengoreksi totalnya, dengan face swap yang bekerja pada massa."}], [{"t0": 290.6, "t1": 294.62, "text": "Kedua, difusi yang tidak fisis."}, {"t0": 294.62, "t1": 299.77, "text": "Jumlah swap yang tetap memberi pencampuran yang sama di mana-mana."}, {"t0": 299.77, "t1": 304.6, "text": "Jadi jumlah swap seharusnya mengikuti pencampuran lokal."}], [{"t0": 305.21, "t1": 309.37, "text": "Ketiga, recurrence yang terlalu sedikit."}, {"t0": 309.37, "t1": 316.32, "text": "Pada domain yang besar, frame yang cocok secara global belum tentu cocok secara lokal."}, {"t0": 316.32, "t1": 323.64, "text": "Jadi domainnya dibagi menjadi recurrence island, masing-masing dengan matriksnya sendiri."}], [{"t0": 324.24, "t1": 327.51, "text": "Tesis Anda menyentuh ketiganya."}, {"t0": 327.51, "t1": 331.54, "text": "Conservation constraint adalah yang pertama."}, {"t0": 331.54, "t1": 335.61, "text": "Recorded diffusivity adalah yang kedua."}, {"t0": 335.61, "t1": 342.34, "text": "Dan aliran Anda, dengan prominence yang terlalu kecil, adalah yang ketiga."}]]}, {"title": "Kapan berhasil, kapan gagal?", "paras": [[{"t0": 343.61, "t1": 350.2, "text": "Metode ini berhasil ketika gerakannya berulang dan scalar-nya tidak mengubah aliran."}, {"t0": 350.2, "t1": 357.83, "text": "Metode ini gagal ketika scalar menggerakkan aliran, atau ketika keadaan operasinya berubah."}, {"t0": 357.83, "t1": 365.17, "text": "Pada keadaan baru, rekaman memang tidak berisi gerakan yang akan dihasilkan keadaan itu."}], [{"t0": 365.79, "t1": 368.46, "text": "Itulah hasil Anda."}, {"t0": 368.46, "t1": 378.43, "text": "Dengan tutup dingin, aliran terus memperbarui dirinya lewat plume dingin, gerakan yang tidak pernah terlihat dalam rekaman tutup terisolasi."}, {"t0": 378.43, "t1": 387.27, "text": "Jawaban dari kuliah adalah multi-state recurrence CFD: satu database untuk setiap keadaan proses."}]]}, {"title": "Digital twin", "paras": [[{"t0": 388.54, "t1": 392.91, "text": "Profesor Pirker menyukai cerita digital twin."}, {"t0": 392.91, "t1": 400.66, "text": "Model tangki dengan satu nilai rata-rata bekerja seketika, tetapi mengabaikan bagian dalam pabrik."}, {"t0": 400.66, "t1": 406.85, "text": "CFD penuh menunjukkan bagian dalam, tetapi butuh berhari-hari."}, {"t0": 406.85, "t1": 419.15, "text": "Contoh di kuliah: model tangki di bawah satu detik, eksperimen 750 detik, CFD dua hari, dan recurrence CFD 30 detik."}, {"t0": 419.15, "t1": 423.33, "text": "Jadi recurrence CFD berada di tengah."}], [{"t0": 423.94, "t1": 429.8, "text": "Tetapi kalau dijalankan maju tanpa pengawasan, galatnya menumpuk."}, {"t0": 429.8, "t1": 434.95, "text": "Jadi data langsung dari proses harus terus menyelaraskannya."}, {"t0": 434.95, "t1": 446.79, "text": "Dan tesis Anda menunjukkan apa yang harus diawasi oleh twin seperti itu: satu kondisi batas bisa memindahkan proses ke regime yang tidak dicakup database."}]]}, {"title": "Apakah recurrence CFD termasuk machine learning?", "paras": [[{"t0": 448.06, "t1": 451.21, "text": "Jawablah dengan hati-hati."}, {"t0": 451.21, "t1": 456.09, "text": "Recurrence CFD adalah simulasi berbasis data."}, {"t0": 456.09, "t1": 467.01, "text": "Ground truth yang mahal menghasilkan data, model murah memakainya ulang, dan pertanyaan sebenarnya adalah seberapa jauh ia bisa digeneralisasi."}, {"t0": 467.01, "t1": 470.46, "text": "Tidak ada training dengan gradient."}, {"t0": 470.46, "t1": 475.0, "text": "Memilih frame berikutnya adalah nearest-neighbour search."}, {"t0": 475.0, "t1": 482.6, "text": "Dan replay-nya adalah rangkaian operator linear yang sparse, mirip dengan learned propagator."}], [{"t0": 483.21, "t1": 496.17, "text": "Langkah AI yang mungkin: mempelajari peta untuk keadaan yang belum pernah terlihat, mempelajari flux yang hilang sebagai fungsi keadaan, atau melatih neural operator pada database."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 497.42, "t1": 499.36, "text": "Pertama."}, {"t0": 499.36, "t1": 507.57, "text": "Prediksi berani ditambah koreksi berbasis fisika, sama seperti SIMPLE yang menebak tekanan lalu mengoreksinya."}], [{"t0": 508.22, "t1": 509.9, "text": "Kedua."}, {"t0": 509.9, "t1": 525.02, "text": "Tiga bold failure: ketidakseimbangan massa, diatasi dengan neraca global; difusi tidak fisis, diatasi dengan swap lokal; recurrence terlalu sedikit, diatasi dengan island."}, {"t0": 525.02, "t1": 528.29, "text": "Tesis Anda menyentuh ketiganya."}], [{"t0": 528.91, "t1": 530.65, "text": "Ketiga."}, {"t0": 530.65, "t1": 535.22, "text": "Sebuah database berlaku untuk satu flow regime."}, {"t0": 535.22, "t1": 543.5, "text": "Jawaban kuliahnya adalah multi-state recurrence CFD, dan tutup dingin Anda adalah contohnya."}]]}]}, {"id": "A2-id", "group": "A-id", "title": "A2 · Membaca gambar-gambar di tesis saya", "file": "tracks/A2-id.mp3", "voice": "Gadis", "duration": 555.1, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 3.62, "text": "Membaca gambar-gambar di tesis saya."}], [{"t0": 4.22, "t1": 12.66, "text": "Profesor Pirker sering menunjuk sebuah gambar lalu bertanya: apa yang ditunjukkan gambar ini, dan kenapa?"}, {"t0": 12.66, "t1": 18.0, "text": "Jadi untuk setiap gambar penting, siapkan tiga kalimat."}, {"t0": 18.0, "t1": 20.64, "text": "Apa yang digambarkan."}, {"t0": 20.64, "t1": 22.88, "text": "Apa yang terlihat."}, {"t0": 22.88, "t1": 25.72, "text": "Dan kenapa itu penting."}, {"t0": 25.72, "t1": 29.86, "text": "Di episode ini kita latih persis hal itu."}, {"t0": 29.86, "t1": 38.73, "text": "Setiap gambar saya sebut berdasarkan isinya, bukan nomornya, karena penomoran gambar masih bisa berubah."}]]}, {"title": "Passive scalar dan non-passive scalar", "paras": [[{"t0": 39.98, "t1": 43.51, "text": "Gambar pembuka punya tiga panel."}, {"t0": 43.51, "t1": 52.79, "text": "Pertama, zat pewarna di dalam kecepatan tersimpan dari tangki terisolasi: zat itu hanya teregang oleh aliran."}, {"t0": 52.79, "t1": 60.26, "text": "Kedua, tangki yang didinginkan, di mana plume dingin dari tutup menciptakan gerakan."}, {"t0": 60.26, "t1": 68.47, "text": "Ketiga, replay, yang memindahkan suhu dengan peta rekaman dan tidak pernah menghitung kecepatan."}], [{"t0": 69.09, "t1": 75.19, "text": "Kenapa penting: seluruh pertanyaan tesis ada dalam satu gambar."}, {"t0": 75.19, "t1": 84.46, "text": "Zat pewarna hanya menumpang aliran, sedangkan suhu menciptakan aliran, dan replay memutus umpan balik itu."}]]}, {"title": "Recurrence dari database", "paras": [[{"t0": 85.73, "t1": 90.31, "text": "Gambar ini menunjukkan distance matrix dari rekaman."}, {"t0": 90.31, "t1": 97.11, "text": "Ada dua blok, terbelah di akhir semburan: tahap pengisian dan tahap pengendapan."}, {"t0": 97.11, "t1": 103.63, "text": "Baris-barisnya naik ke sebuah plateau, dan tidak ada yang kembali mendekati nol."}], [{"t0": 104.25, "t1": 113.21, "text": "Kenapa penting: prominence, dengan median 0,028, tetap di bawah kebutuhan metode."}, {"t0": 113.21, "t1": 119.98, "text": "Jadi tidak ada keadaan yang kembali, dan replay memutar frame secara berurutan."}]]}, {"title": "Transport panas vertikal di bawah tutup dingin", "paras": [[{"t0": 121.24, "t1": 131.7, "text": "Gambar ini membagi vertical heat flux rata-rata bidang menjadi dua bagian: bagian yang dibawa aliran, dan bagian yang dibawa konduksi."}, {"t0": 131.7, "t1": 141.47, "text": "Di bawah tutup dingin, aliran membawa panas jauh lebih banyak daripada konduksi, dan simpangan suhunya seukuran plume utuh."}], [{"t0": 142.07, "t1": 146.89, "text": "Kenapa penting: pendinginan adalah proses transport."}, {"t0": 146.89, "t1": 150.67, "text": "Langkah difusif tidak bisa menirunya."}]]}, {"title": "Dua regime", "paras": [[{"t0": 151.94, "t1": 157.63, "text": "Geometri sama, semburan sama, dua aliran berbeda."}, {"t0": 157.63, "t1": 165.9, "text": "Dengan tutup terisolasi, semburan naik, menyebar di bawah tutup, lalu lapisan hangatnya diam."}, {"t0": 165.9, "t1": 174.18, "text": "Dengan tutup dingin, lapisan di atas front berputar dalam deretan sel, digerakkan oleh plume dingin."}], [{"t0": 174.78, "t1": 182.23, "text": "Kenapa penting: satu kondisi batas memindahkan aliran dari satu regime ke regime lain."}]]}, {"title": "Replay standar pada sapuan pencampuran", "paras": [[{"t0": 183.5, "t1": 190.84, "text": "Dua panel: suhu rata-rata dan tinggi panas, untuk tujuh kekuatan pencampuran."}, {"t0": 190.84, "t1": 199.3, "text": "Pencampuran yang lebih kuat memanaskan tangki lebih cepat selama semburan, dan mengurasnya lebih cepat sesudahnya."}, {"t0": 199.3, "t1": 207.04, "text": "Tinggi panas paling baik pada kekuatan menengah, kandungan panas paling baik dengan pencampuran kecil."}], [{"t0": 207.66, "t1": 212.25, "text": "Kenapa penting: tidak ada satu setelan terbaik."}]]}, {"title": "Tangki terisolasi sepanjang run", "paras": [[{"t0": 213.49, "t1": 220.29, "text": "Suhu bidang tengah pada empat waktu, dengan lebar front tertulis di setiap panel."}, {"t0": 220.29, "t1": 226.12, "text": "Replay yang hanya memakai peta rekaman menjaga front setipis referensi."}, {"t0": 226.12, "t1": 229.54, "text": "Replay standar membuatnya melebar."}, {"t0": 229.54, "t1": 233.19, "text": "Replay terkoreksi menipiskannya lagi."}], [{"t0": 233.82, "t1": 240.85, "text": "Kenapa penting: pelebaran datang dari face exchange, bukan dari peta rekaman."}]]}, {"title": "Diagram ruang-waktu", "paras": [[{"t0": 242.12, "t1": 247.61, "text": "Suhu rata-rata horizontal digambar terhadap ketinggian dan waktu."}, {"t0": 247.61, "t1": 251.42, "text": "Terlihat lapisan hangat yang tumbuh ke bawah."}, {"t0": 251.42, "t1": 261.9, "text": "Panel selisih menunjukkan di mana replay standar terlalu hangat atau terlalu dingin, dan panel ketebalan menunjukkan front-nya tetap terlalu tebal."}, {"t0": 261.9, "t1": 265.7, "text": "Replay terkoreksi mengikuti referensi."}]]}, {"title": "Semua run koreksi dalam satu peta", "paras": [[{"t0": 266.96, "t1": 275.53, "text": "Setiap penanda adalah satu replay: galat trace dan galat profil akhir, digambar terhadap lebar front."}, {"t0": 275.53, "t1": 285.73, "text": "Hanya bentuk yang diberi bobot vertikal yang menurunkan kedua galat sekaligus sambil membawa front ke lebar referensi, 5,0 milimeter."}, {"t0": 285.73, "t1": 291.82, "text": "Rentang kerjanya s dari 0,40 sampai 0,50."}], [{"t0": 292.43, "t1": 297.78, "text": "Kenapa penting: arah lebih menentukan daripada kekuatan."}]]}, {"title": "Buoyancy frequency di sepanjang front", "paras": [[{"t0": 299.03, "t1": 305.39, "text": "Buoyancy frequency menunjukkan seberapa kuat pelapisan menahan gerakan vertikal."}, {"t0": 305.39, "t1": 311.27, "text": "N kuadrat sama dengan g dikali beta dikali gradien suhu vertikal."}, {"t0": 311.27, "t1": 317.26, "text": "Replay standar hanya punya penghalang kira-kira setengah sekuat referensi."}, {"t0": 317.26, "t1": 322.27, "text": "Replay terkoreksi mencapai nilai referensi setelah semburan."}], [{"t0": 322.88, "t1": 328.53, "text": "Kenapa penting: front yang lebih tajam adalah penghalang yang lebih kuat."}, {"t0": 328.53, "t1": 333.77, "text": "Koreksi memulihkan kestabilan front, tidak hanya lebarnya."}]]}, {"title": "Profil akhir melintasi front", "paras": [[{"t0": 335.02, "t1": 339.59, "text": "Tanpa koreksi, front lebar dan terlalu tinggi."}, {"t0": 339.59, "t1": 346.21, "text": "Koreksi tanpa bobot membuatnya tipis, tetapi meletakkannya di tempat yang salah."}, {"t0": 346.21, "t1": 349.87, "text": "Bobot vertikal mengikuti referensi."}], [{"t0": 350.48, "t1": 357.25, "text": "Kenapa penting: front yang bergerigi bisa punya lebar yang benar tetapi bentuk yang salah."}, {"t0": 357.25, "t1": 361.12, "text": "Baca lebar selalu bersama profilnya."}]]}, {"title": "Suhu outlet dari neraca energi", "paras": [[{"t0": 362.38, "t1": 374.73, "text": "Suhu outlet diperoleh dari neraca energi seluruh tangki: massa dikali laju perubahan suhu rata-rata sama dengan laju aliran massa dikali selisih suhu inlet dan outlet."}, {"t0": 374.73, "t1": 382.17, "text": "Selama semburan hangat, replay standar menahan panas berlebih sekitar 2,7 kelvin."}, {"t0": 382.17, "t1": 386.95, "text": "Setelah itu, 4,6 kelvin terbuang."}], [{"t0": 387.56, "t1": 396.93, "text": "Kenapa penting: outlet berada tepat di bawah front, jadi galat numerik di front berubah menjadi galat dalam neraca energi."}]]}, {"title": "State space", "paras": [[{"t0": 398.19, "t1": 406.22, "text": "Dua mode POD utama dari medan referensi, dan jarak setiap run dari ruang sepuluh mode pertama."}, {"t0": 406.22, "t1": 410.94, "text": "Replay standar keluar dari ruang ini dan tidak kembali."}, {"t0": 410.94, "t1": 414.97, "text": "Replay terkoreksi kembali setelah semburan."}], [{"t0": 415.59, "t1": 423.07, "text": "Kenapa penting: koreksi menjaga replay tetap dekat dengan keadaan-keadaan yang dicakup rekaman."}]]}, {"title": "Tutup dingin: profil, trace, dan plume", "paras": [[{"t0": 424.35, "t1": 435.81, "text": "Profil akhir: replay standar menyimpan jumlah panas yang hampir benar, tetapi di tempat yang salah, dengan galat profil 2,79 kelvin."}, {"t0": 435.81, "t1": 441.21, "text": "Bagian tengah terlalu hangat, lapisan atas terlalu dingin."}, {"t0": 441.21, "t1": 444.85, "text": "Koreksi memindahkan panasnya kembali."}], [{"t0": 445.46, "t1": 454.9, "text": "Trace: sebuah pita berarsir menunjukkan seberapa jauh koreksi lokal tertinggal dalam heterogenitas selama semburan hangat."}, {"t0": 454.9, "t1": 460.13, "text": "Hanya recorded flux yang ikut mengikuti heterogenitas."}, {"t0": 460.13, "t1": 466.79, "text": "Keterlambatan pelapisan berarti kekurangan transport, bukan kekurangan ketajaman."}], [{"t0": 467.4, "t1": 473.9, "text": "Dan dalam tiga dimensi: plume pada replay standar berhenti di tengah jalan."}, {"t0": 473.9, "t1": 478.6, "text": "Dengan koreksi, plume itu mencapai front lagi."}, {"t0": 478.6, "t1": 482.27, "text": "Replay tidak mengarang gerakan apa pun."}, {"t0": 482.27, "t1": 486.84, "text": "Plume itu sudah ada di peta rekaman sejak awal."}]]}, {"title": "Recurrence dari dua rekaman", "paras": [[{"t0": 488.13, "t1": 501.82, "text": "Setelah semburan berhenti, aliran dengan tutup dingin terus memperbarui dirinya, kira-kira sepuluh kali lebih cepat pada selang waktu pendek, sedangkan aliran tutup terisolasi hampir tidak berubah."}], [{"t0": 502.44, "t1": 512.87, "text": "Kenapa penting: kasus yang didinginkan adalah regime yang berbeda, jadi database yang direkam tanpa pendinginan tidak bisa berisi gerakannya."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 514.12, "t1": 516.08, "text": "Pertama."}, {"t0": 516.08, "t1": 523.13, "text": "Untuk setiap gambar: apa yang digambarkan, apa yang terlihat, kenapa penting."}], [{"t0": 523.75, "t1": 525.43, "text": "Kedua."}, {"t0": 525.43, "t1": 540.02, "text": "Rangkaian gambar kuncinya: tidak ada satu setelan pencampuran terbaik, peta rekaman menjaga front tipis, outlet membuang panas, dan koreksi vertikal memulihkan lebar serta kestabilan front."}], [{"t0": 540.64, "t1": 542.37, "text": "Ketiga."}, {"t0": 542.37, "t1": 555.11, "text": "Dengan tutup dingin: panasnya benar tetapi tempatnya salah tanpa koreksi, keterlambatan adalah kekurangan transport, dan regime yang berbeda butuh database yang berbeda."}]]}]}, {"id": "A3-id", "group": "A-id", "title": "A3 · Dasar-dasar CFD di balik recurrence CFD", "file": "tracks/A3-id.mp3", "voice": "Gadis", "duration": 590.3, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 4.84, "text": "Dasar-dasar CFD di balik recurrence CFD."}], [{"t0": 5.45, "t1": 11.39, "text": "Episode terakhir membahas dasar CFD dari kuliah Profesor Pirker."}, {"t0": 11.39, "t1": 19.75, "text": "Pertanyaan-pertanyaan ini menguji apakah Anda benar-benar paham landasan tempat recurrence CFD berdiri."}, {"t0": 19.75, "t1": 29.41, "text": "Triknya sama untuk setiap pertanyaan: sampaikan idenya, berikan satu rumus, lalu kaitkan dengan tesis Anda."}, {"t0": 29.41, "t1": 35.37, "text": "Kaitan itulah yang mengubah jawaban buku teks menjadi jawaban Anda sendiri."}]]}, {"title": "Bilangan tak berdimensi", "paras": [[{"t0": 36.62, "t1": 44.31, "text": "Bilangan Reynolds membandingkan inersia dengan gaya viskos: U dikali L dibagi nu."}, {"t0": 44.31, "t1": 52.67, "text": "Aliran dalam pipa laminar di bawah sekitar 2300, dan turbulen di atas sekitar 4000."}], [{"t0": 53.28, "t1": 55.73, "text": "Beberapa yang lain."}, {"t0": 55.73, "t1": 60.37, "text": "Bilangan Péclet membandingkan konveksi dengan difusi."}, {"t0": 60.37, "t1": 66.08, "text": "Bilangan Prandtl membandingkan difusi momentum dengan difusi panas."}, {"t0": 66.08, "t1": 71.21, "text": "Bilangan Froude membandingkan inersia dengan gravitasi."}, {"t0": 71.21, "t1": 76.38, "text": "Bilangan Richardson membandingkan gaya apung dengan inersia."}], [{"t0": 76.99, "t1": 90.96, "text": "Kasus Anda: bilangan Reynolds sekitar 99, jadi laminar, dan bilangan Richardson 1,84, jadi gaya apung sedikit lebih kuat daripada inersia."}]]}, {"title": "Persamaan pengatur dan material derivative", "paras": [[{"t0": 92.23, "t1": 97.51, "text": "Massa, momentum, dan energi bersifat kekal."}, {"t0": 97.51, "t1": 100.87, "text": "Ada dua cara melihat aliran."}, {"t0": 100.87, "t1": 105.68, "text": "Sudut pandang Lagrangian mengikuti satu parsel fluida."}, {"t0": 105.68, "t1": 110.12, "text": "Sudut pandang Eulerian mengamati satu titik tetap."}], [{"t0": 110.73, "t1": 114.87, "text": "Material derivative menghubungkan keduanya."}, {"t0": 114.87, "t1": 124.99, "text": "Turunan ini adalah laju perubahan yang dialami parsel yang bergerak: perubahan lokal terhadap waktu, ditambah kecepatan dikali gradien."}, {"t0": 124.99, "t1": 132.41, "text": "Rumusnya didapat dari chain rule sepanjang lintasan, karena parsel bergerak mengikuti kecepatan."}], [{"t0": 133.02, "t1": 144.98, "text": "Persamaan momentum dengan kata-kata: perubahan terhadap waktu ditambah konveksi sama dengan gaya tekanan, ditambah gaya viskos, ditambah gaya badan."}]]}, {"title": "Metode volume hingga", "paras": [[{"t0": 146.27, "t1": 150.36, "text": "Integralkan persamaannya pada setiap sel."}, {"t0": 150.36, "t1": 156.49, "text": "Teorema divergensi mengubah setiap divergensi menjadi flux yang melewati face."}, {"t0": 156.49, "t1": 163.69, "text": "Apa yang keluar dari satu sel masuk ke sel tetangganya, jadi metodenya konservatif."}], [{"t0": 164.32, "t1": 177.03, "text": "Setiap nilai sel lalu terhubung dengan tetangganya lewat satu persamaan linear: a P dikali c P sama dengan jumlah koefisien tetangga dikali nilai tetangga, ditambah sumber."}, {"t0": 177.03, "t1": 181.25, "text": "Bentuk ini disebut computational molecule."}], [{"t0": 181.86, "t1": 194.2, "text": "Kaitannya dengan tesis Anda: kalau semua koefisiennya positif, nilai baru merupakan rata-rata berbobot dari tetangganya, jadi tidak ada ekstrem baru yang muncul."}, {"t0": 194.2, "t1": 203.29, "text": "Aturan itulah yang melindungi face exchange di recurrence CFD, dan ide yang sama ada di balik limiter Anda."}]]}, {"title": "Skema diskretisasi dan difusi numerik", "paras": [[{"t0": 204.56, "t1": 208.99, "text": "First-order upwind mengambil nilai dari arah hulu."}, {"t0": 208.99, "t1": 214.38, "text": "Skema ini stabil, tetapi menambahkan difusi palsu."}, {"t0": 214.38, "t1": 222.51, "text": "Central differencing lebih akurat, tetapi bisa berosilasi ketika cell Péclet number lebih dari dua."}], [{"t0": 223.11, "t1": 226.4, "text": "Kenapa upwind menimbulkan difusi?"}, {"t0": 226.4, "t1": 230.38, "text": "Ekspansikan nilai hulu dengan deret Taylor."}, {"t0": 230.38, "t1": 237.78, "text": "Selisih upwind sama dengan turunan sebenarnya dikurangi setengah delta x dikali turunan kedua."}, {"t0": 237.78, "t1": 248.66, "text": "Jadi persamaan yang sebenarnya diselesaikan upwind punya suku difusi tambahan, dengan difusivitas numerik setengah dikali u dikali delta x."}], [{"t0": 249.27, "t1": 255.3, "text": "Dan tesis Anda dalam satu kalimat: sebuah cerita tentang difusi numerik."}, {"t0": 255.3, "t1": 260.86, "text": "Face exchange melebarkan front, dan koreksi mengembalikannya."}]]}, {"title": "Time stepping eksplisit dan implisit", "paras": [[{"t0": 262.14, "t1": 266.97, "text": "Langkah eksplisit murah tetapi dibatasi kestabilan."}, {"t0": 266.97, "t1": 273.49, "text": "Langkah implisit menyelesaikan sistem persamaan, tetapi stabil tanpa syarat."}], [{"t0": 274.11, "t1": 284.34, "text": "Untuk konveksi eksplisit, bilangan Courant harus di bawah satu: informasi tidak boleh berpindah lebih dari satu sel per langkah."}, {"t0": 284.34, "t1": 293.89, "text": "Untuk difusi eksplisit, diffusion number, Gamma delta t dibagi delta x kuadrat, harus di bawah setengah."}], [{"t0": 294.51, "t1": 298.88, "text": "Batas difusi ini bisa Anda tunjukkan di papan."}, {"t0": 298.88, "t1": 303.94, "text": "Masukkan satu Fourier mode ke langkah difusi eksplisit."}, {"t0": 303.94, "t1": 311.41, "text": "Faktor pertumbuhannya satu dikurangi empat d dikali sinus kuadrat k delta x per dua."}, {"t0": 311.41, "t1": 321.27, "text": "Nilainya tetap di antara minus satu dan satu untuk setiap mode hanya jika empat d paling besar dua, jadi d paling besar setengah."}], [{"t0": 321.89, "t1": 329.94, "text": "Kaitannya lagi: batas difusi eksplisit inilah yang menahan recorded diffusivity dalam replay Anda."}]]}, {"title": "Algoritma SIMPLE", "paras": [[{"t0": 331.2, "t1": 338.4, "text": "SIMPLE singkatan dari Semi-Implicit Method for Pressure-Linked Equations, dari Patankar."}, {"t0": 338.4, "t1": 340.52, "text": "Empat langkah."}, {"t0": 340.52, "t1": 348.19, "text": "Satu: tebak tekanan, lalu selesaikan persamaan momentum untuk mendapat kecepatan."}, {"t0": 348.19, "t1": 354.08, "text": "Dua: tuliskan koreksi kecepatan sebagai fungsi koreksi tekanan."}, {"t0": 354.08, "t1": 362.1, "text": "Tiga: masukkan ke persamaan kontinuitas, sehingga muncul persamaan untuk koreksi tekanan."}, {"t0": 362.1, "t1": 370.56, "text": "Empat: koreksi kedua medan, dengan under-relaxation, dan ulangi sampai residual-nya kecil."}], [{"t0": 371.18, "t1": 375.98, "text": "Tebak, hitung, koreksi, ulangi."}, {"t0": 375.98, "t1": 383.11, "text": "Ingat dari episode pertama: recurrence CFD bekerja dengan semangat yang sama."}]]}, {"title": "Turbulensi", "paras": [[{"t0": 384.38, "t1": 388.88, "text": "Turbulensi bersifat kacau dan mencampur dengan kuat."}, {"t0": 388.88, "t1": 397.5, "text": "Energi masuk di eddy besar lalu mengalir turun ke skala Kolmogorov, tempat viskositas menghabiskannya."}], [{"t0": 398.11, "t1": 403.63, "text": "Panjang Kolmogorov bisa diturunkan dari analisis dimensi."}, {"t0": 403.63, "t1": 410.91, "text": "Besaran itu hanya boleh bergantung pada viskositas nu dan laju disipasi epsilon."}, {"t0": 410.91, "t1": 420.54, "text": "Cocokkan satuan meter dan detik, dan hasilnya eta sama dengan nu pangkat tiga dibagi epsilon, dipangkatkan seperempat."}], [{"t0": 421.15, "t1": 436.63, "text": "RANS memisahkan kecepatan menjadi rata-rata dan fluktuasi, lalu memodelkan semua eddy, biasanya dengan eddy viscosity, misalnya C mu dikali k kuadrat dibagi epsilon pada model k-epsilon."}, {"t0": 436.63, "t1": 440.18, "text": "LES hanya memodelkan eddy kecil."}, {"t0": 440.18, "t1": 444.03, "text": "DNS tidak memodelkan sama sekali."}, {"t0": 444.03, "t1": 450.12, "text": "Kasus Anda tidak membutuhkan semua ini, karena alirannya laminar."}]]}, {"title": "Lapisan batas dinding", "paras": [[{"t0": 451.39, "t1": 455.89, "text": "Di dekat dinding, kecepatan turun menjadi nol."}, {"t0": 455.89, "t1": 467.35, "text": "y plus menunjukkan seberapa jauh sel pertama dari dinding, dalam satuan viskos: friction velocity dikali jarak ke dinding, dibagi nu."}, {"t0": 467.35, "t1": 474.9, "text": "Viscous sublayer berada di bawah y plus sekitar lima, log layer di atas sekitar tiga puluh."}, {"t0": 474.9, "t1": 481.82, "text": "Wall function menempatkan sel pertama di log layer dan memodelkan sisanya, jadi murah."}, {"t0": 481.82, "t1": 486.79, "text": "Simulasi yang meresolusi dinding butuh y plus sekitar satu."}]]}, {"title": "Transport panas dan Boussinesq", "paras": [[{"t0": 488.06, "t1": 498.36, "text": "Suhu dan spesies mengikuti persamaan transport yang sama: perubahan terhadap waktu ditambah konveksi sama dengan difusi ditambah sumber."}, {"t0": 498.36, "t1": 504.23, "text": "Kalau densitas bergantung pada suhu, aliran dan suhu saling terikat."}], [{"t0": 504.83, "t1": 515.21, "text": "Untuk perubahan densitas yang kecil, Boussinesq approximation menganggap densitas konstan di mana-mana, kecuali pada suku gravitasi."}, {"t0": 515.21, "t1": 520.95, "text": "Dan suku gaya apung itulah tepatnya hubungan yang diputus oleh replay."}]]}, {"title": "Aliran multifase", "paras": [[{"t0": 522.21, "t1": 528.98, "text": "Euler-Euler memperlakukan setiap fase sebagai kontinum, dengan volume fraction."}, {"t0": 528.98, "t1": 533.54, "text": "Cocok untuk sistem yang padat dengan biaya lebih rendah."}, {"t0": 533.54, "t1": 544.93, "text": "Euler-Lagrange melacak setiap partikel, dan jika tumbukan partikel ikut dihitung, menjadi CFD-DEM: akurat, tetapi mahal."}, {"t0": 544.93, "t1": 551.35, "text": "Recurrence CFD pertama kali dipakai untuk bubble column dan fluidized bed."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 552.62, "t1": 554.56, "text": "Pertama."}, {"t0": 554.56, "t1": 565.52, "text": "Volume hingga bersifat konservatif, dan koefisien positif berarti tidak ada ekstrem baru: aturan yang sama melindungi limiter Anda."}], [{"t0": 566.13, "t1": 567.79, "text": "Kedua."}, {"t0": 567.79, "t1": 576.13, "text": "Upwind menambahkan difusivitas numerik setengah u delta x. Tesis Anda adalah cerita tentang difusi numerik."}], [{"t0": 576.73, "t1": 578.48, "text": "Ketiga."}, {"t0": 578.48, "t1": 585.39, "text": "Batas eksplisit: Courant di bawah satu, diffusion number di bawah setengah."}, {"t0": 585.39, "t1": 590.33, "text": "Batas difusi itulah yang menahan recorded diffusivity."}]]}]}, {"id": "M1-id", "group": "M-id", "title": "M1 · Belajar dari data: risk, loss, dan cerita bias-variance", "file": "tracks/M1-id.mp3", "voice": "Gadis", "duration": 462.1, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 6.44, "text": "Belajar dari data: risk, loss, dan cerita bias-variance."}], [{"t0": 7.06, "t1": 13.46, "text": "Hampir setiap ujian Machine Learning and Perception dimulai dari titik yang sama."}, {"t0": 13.46, "t1": 19.9, "text": "Penguji berkata: tuliskan sebuah supervised data set dan kerangka training-nya."}, {"t0": 19.9, "t1": 27.0, "text": "Kalau cerita ini bisa Anda sampaikan dengan tenang, sisa ujian akan terasa lebih ringan."}, {"t0": 27.0, "t1": 32.42, "text": "Jadi mari kita susun, satu bagian demi satu bagian."}]]}, {"title": "Data, model, loss, rata-rata, minimalkan", "paras": [[{"t0": 33.7, "t1": 36.56, "text": "Kita punya N pasangan."}, {"t0": 36.56, "t1": 41.98, "text": "Setiap pasangan terdiri dari input x n dan label y n."}, {"t0": 41.98, "t1": 51.78, "text": "Kita menganggap pasangan-pasangan itu diambil secara independen dari satu distribusi yang tidak diketahui, p dari x dan y."}], [{"t0": 52.39, "t1": 59.36, "text": "Sebuah model g memetakan input menjadi prediksi, dan model itu punya bobot w."}, {"t0": 59.36, "t1": 63.97, "text": "Sebuah loss L mengukur seberapa salah satu prediksi."}, {"t0": 63.97, "t1": 71.16, "text": "Kalau loss dirata-ratakan untuk semua pasangan training, hasilnya disebut empirical risk."}, {"t0": 71.16, "t1": 78.2, "text": "Dan belajar artinya sederhana: cari bobot yang membuat empirical risk sekecil mungkin."}], [{"t0": 78.81, "t1": 87.6, "text": "Ingat dalam lima kata bahasa Inggris: data, model, loss, average, minimise."}]]}, {"title": "Kenapa tidak meminimalkan galat yang sebenarnya?", "paras": [[{"t0": 88.87, "t1": 97.4, "text": "Penguji akan mendesak: apa itu generalization error, dan kenapa tidak bisa diminimalkan secara langsung?"}], [{"t0": 98.06, "t1": 105.87, "text": "Generalization error adalah nilai harapan loss pada data baru yang diambil dari distribusi sebenarnya."}, {"t0": 105.87, "t1": 114.57, "text": "Untuk menghitungnya, loss harus diintegralkan terhadap p dari x dan y. Masalahnya, p tidak diketahui."}, {"t0": 114.57, "t1": 118.41, "text": "Seluruh persoalan belajar ada di situ."}], [{"t0": 119.03, "t1": 132.07, "text": "Jadi yang kita minimalkan adalah empirical risk, lalu generalization error diperkirakan pada data yang tidak dipakai untuk training: sebuah test set, atau cross-validation."}, {"t0": 132.07, "t1": 139.79, "text": "Menurut hukum bilangan besar, rata-rata loss pada test set yang besar akan mendekati nilai harapannya."}], [{"t0": 140.39, "t1": 146.84, "text": "Satu jebakan yang harus dihindari: training loss bukan perkiraan yang adil."}, {"t0": 146.84, "t1": 153.65, "text": "Bobotnya dipilih berdasarkan data itu, jadi angkanya terlihat terlalu bagus."}]]}, {"title": "Apa itu loss function?", "paras": [[{"t0": 154.91, "t1": 158.73, "text": "Loss membandingkan label dengan prediksi."}, {"t0": 158.73, "t1": 164.27, "text": "Nilainya tidak pernah negatif, dan nol kalau prediksinya benar."}, {"t0": 164.27, "t1": 167.62, "text": "Loss dipilih sesuai tugasnya."}], [{"t0": 168.23, "t1": 176.17, "text": "Untuk regresi, squared loss: setengah kali selisih label dan prediksi, dikuadratkan."}, {"t0": 176.17, "t1": 180.56, "text": "Untuk dua kelas, binary cross-entropy."}, {"t0": 180.56, "t1": 191.42, "text": "Untuk banyak kelas, categorical cross-entropy: minus jumlah, untuk semua kelas, dari label dikali log probabilitas prediksi."}, {"t0": 191.42, "t1": 196.04, "text": "Dan untuk support vector machine, hinge loss."}], [{"t0": 196.64, "t1": 203.99, "text": "Profesor Klambauer pernah menanyakan lanjutan yang menarik: apakah semua loss bisa diturunkan?"}, {"t0": 203.99, "t1": 205.5, "text": "Tidak."}, {"t0": 205.5, "t1": 214.49, "text": "Zero-one loss, yang hanya menghitung jumlah kesalahan, tidak punya gradient yang berguna karena datar hampir di mana-mana."}, {"t0": 214.49, "t1": 218.96, "text": "Jadi untuk training kita memakai cross-entropy."}]]}, {"title": "Regresi linear sebagai pemanasan", "paras": [[{"t0": 220.21, "t1": 225.57, "text": "Dengan model linear dan squared loss, risk-nya berbentuk mangkuk."}, {"t0": 225.57, "t1": 234.36, "text": "Fungsinya konveks, jadi hanya ada satu minimum, dan minimum itu bisa ditemukan dalam bentuk tertutup."}, {"t0": 234.36, "t1": 240.13, "text": "Ambil gradient dari setengah kali norma kuadrat y dikurangi X w."}, {"t0": 240.13, "t1": 244.59, "text": "Hasilnya minus X transpose dikali error."}, {"t0": 244.59, "t1": 249.81, "text": "Samakan dengan nol, dan muncul normal equations."}, {"t0": 249.81, "t1": 257.46, "text": "Solusinya: X transpose X, diinverskan, dikali X transpose y."}, {"t0": 257.46, "t1": 260.08, "text": "Itulah pseudo-inverse."}], [{"t0": 260.7, "t1": 267.66, "text": "Perhatikan satu pola di sini, karena pola ini muncul lagi di backpropagation."}, {"t0": 267.66, "t1": 273.57, "text": "Untuk satu sampel, gradient-nya sama dengan error dikali input."}]]}, {"title": "Overfitting, underfitting, bias dan variance", "paras": [[{"t0": 274.83, "t1": 277.71, "text": "Gambaran ini membantu."}, {"t0": 277.71, "t1": 285.22, "text": "Bayangkan Anda memanah sebuah sasaran berkali-kali, dan setiap kali dengan training set yang baru."}, {"t0": 285.22, "t1": 291.6, "text": "Bias adalah seberapa jauh pusat sebaran anak panah dari titik tengah sasaran."}, {"t0": 291.6, "t1": 296.59, "text": "Variance adalah seberapa lebar anak panah itu tersebar."}], [{"t0": 297.2, "t1": 301.48, "text": "Model yang terlalu sederhana punya bias tinggi."}, {"t0": 301.48, "t1": 306.98, "text": "Ia tidak mampu mengikuti data, jadi terjadi underfitting."}, {"t0": 306.98, "t1": 311.35, "text": "Model yang terlalu kompleks punya variance tinggi."}, {"t0": 311.35, "t1": 319.06, "text": "Ia mengikuti noise di setiap training set, sehingga training error rendah tetapi test error tinggi."}, {"t0": 319.06, "t1": 321.65, "text": "Itulah overfitting."}], [{"t0": 322.28, "t1": 332.02, "text": "Rumus di balik gambaran tadi: nilai harapan galat kuadrat sama dengan noise, ditambah bias kuadrat, ditambah variance."}, {"t0": 332.02, "t1": 338.04, "text": "Rumus ini diturunkan dengan menambah dan mengurangi rata-rata prediksi model."}, {"t0": 338.04, "t1": 342.89, "text": "Suku silangnya punya rata-rata nol, jadi hilang."}], [{"t0": 343.49, "t1": 349.15, "text": "Tambahan modern: network yang sangat besar menunjukkan double descent."}, {"t0": 349.15, "t1": 356.88, "text": "Setelah melewati titik di mana network persis mencocokkan data training, test error justru turun lagi."}, {"t0": 356.88, "t1": 360.46, "text": "Sebutkan dalam satu kalimat saja."}, {"t0": 360.46, "t1": 366.04, "text": "Ini menunjukkan Anda tahu kurva klasik belum menceritakan semuanya."}]]}, {"title": "Maximum likelihood", "paras": [[{"t0": 367.3, "t1": 371.41, "text": "Profesor Widmer beberapa kali menanyakan ini."}, {"t0": 371.41, "t1": 377.96, "text": "Maximum likelihood memilih parameter yang membuat data yang teramati paling mungkin terjadi."}, {"t0": 377.96, "t1": 385.58, "text": "Yang dimaksimalkan adalah log-likelihood, karena penjumlahan lebih mudah daripada perkalian."}], [{"t0": 386.18, "t1": 393.36, "text": "Hubungan yang rapi: squared loss sama dengan maximum likelihood di bawah noise Gaussian."}, {"t0": 393.36, "t1": 403.35, "text": "Tuliskan likelihood Gaussian, ambil minus log-nya, dan satu-satunya bagian yang bergantung pada bobot adalah jumlah galat kuadrat."}], [{"t0": 403.97, "t1": 410.72, "text": "Kelemahannya: dengan data sedikit, maximum likelihood mudah overfitting."}, {"t0": 410.72, "t1": 415.63, "text": "Kejadian yang belum pernah terlihat mendapat probabilitas nol."}, {"t0": 415.63, "t1": 423.99, "text": "Sebuah prior, yang menghasilkan MAP estimation, atau regularisasi, bisa mengatasinya."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 425.25, "t1": 427.19, "text": "Pertama."}, {"t0": 427.19, "t1": 436.46, "text": "Data, model, loss, rata-rata, minimalkan: itulah empirical risk minimization."}], [{"t0": 437.08, "t1": 438.75, "text": "Kedua."}, {"t0": 438.75, "t1": 450.37, "text": "Generalization error membutuhkan distribusi yang tidak diketahui, jadi diperkirakan dengan test set atau cross-validation, tidak pernah dengan data training."}], [{"t0": 450.98, "t1": 452.72, "text": "Ketiga."}, {"t0": 452.72, "t1": 462.05, "text": "Model sederhana punya bias, model kompleks punya variance, dan network yang sangat besar menunjukkan double descent."}]]}]}, {"id": "M2-id", "group": "M-id", "title": "M2 · Dari satu neuron sampai backpropagation", "file": "tracks/M2-id.mp3", "voice": "Gadis", "duration": 486.8, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 4.16, "text": "Dari satu neuron sampai backpropagation."}], [{"t0": 4.78, "t1": 9.26, "text": "Topik ini paling sering ditanyakan di seluruh ujian."}, {"t0": 9.26, "t1": 20.83, "text": "Profesor Hochreiter, Profesor Klambauer, dan penguji lain menanyakannya berulang kali: jelaskan backpropagation dan definisikan delta error."}, {"t0": 20.83, "t1": 23.46, "text": "Targetnya sederhana."}, {"t0": 23.46, "t1": 31.52, "text": "Anda harus bisa menuliskannya di papan dalam dua menit, sambil menjelaskan setiap baris yang ditulis."}, {"t0": 31.52, "t1": 33.96, "text": "Mari kita ke sana."}]]}, {"title": "Satu neuron", "paras": [[{"t0": 35.21, "t1": 44.71, "text": "Sebuah neuron mengambil jumlah berbobot dari input-nya, menambahkan bias, lalu memasukkan hasilnya ke fungsi non-linear."}, {"t0": 44.71, "t1": 49.79, "text": "Jumlah berbobot itu disebut pre-activation, s."}, {"t0": 49.79, "t1": 56.38, "text": "Hasilnya, a sama dengan f dari s, disebut activation."}, {"t0": 56.38, "t1": 61.59, "text": "Satu layer melakukan hal ini untuk banyak neuron sekaligus."}, {"t0": 61.59, "t1": 75.19, "text": "Dalam bentuk matriks, activation layer l sama dengan f dari W dikali activation layer di bawahnya, ditambah b. Forward pass berjalan layer demi layer, dari input ke output."}]]}, {"title": "Kenapa butuh non-linearitas?", "paras": [[{"t0": 76.46, "t1": 82.82, "text": "Profesor Schlüter pernah bertanya: apa yang terjadi tanpa activation function?"}, {"t0": 82.82, "t1": 87.6, "text": "Seluruh network runtuh menjadi satu model linear."}, {"t0": 87.6, "t1": 93.37, "text": "Kalikan dua pemetaan linear, hasilnya tetap pemetaan linear."}, {"t0": 93.37, "t1": 101.29, "text": "Jadi kedalaman tidak menambah apa-apa, dan network bahkan tidak bisa menyelesaikan XOR."}, {"t0": 101.29, "t1": 105.6, "text": "Non-linearitaslah yang membuat kedalaman berguna."}]]}, {"title": "Universal approximation theorem", "paras": [[{"t0": 106.87, "t1": 119.48, "text": "Satu hidden layer, dengan cukup banyak unit dan activation yang bukan polinomial, misalnya sigmoid, bisa mendekati fungsi kontinu apa pun pada himpunan kompak."}, {"t0": 119.48, "t1": 124.16, "text": "Sekarang bagian pentingnya, yaitu batasnya."}, {"t0": 124.16, "t1": 129.62, "text": "Teorema ini mengatakan network mampu merepresentasikan fungsinya."}, {"t0": 129.62, "t1": 134.42, "text": "Teorema ini tidak mengatakan berapa unit yang dibutuhkan."}, {"t0": 134.42, "t1": 139.88, "text": "Dan tidak mengatakan bahwa gradient descent akan menemukan bobotnya."}, {"t0": 139.88, "t1": 144.29, "text": "Keberadaan, bukan kemampuan dipelajari."}]]}, {"title": "Backpropagation: idenya", "paras": [[{"t0": 145.56, "t1": 148.13, "text": "Masalahnya begini."}, {"t0": 148.13, "t1": 155.27, "text": "Sebuah network bisa punya jutaan bobot, dan kita butuh gradient loss untuk setiap bobot."}, {"t0": 155.27, "t1": 159.47, "text": "Menghitungnya satu per satu jelas tidak mungkin."}], [{"t0": 160.08, "t1": 166.74, "text": "Backpropagation mendapatkan semuanya dengan satu forward pass dan satu backward pass."}, {"t0": 166.74, "t1": 172.55, "text": "Bayangkan seperti menelusuri siapa yang bertanggung jawab dalam sebuah tim."}, {"t0": 172.55, "t1": 175.92, "text": "Output-nya salah sebesar sekian."}, {"t0": 175.92, "t1": 182.43, "text": "Setiap unit menanggung bagian kesalahan, sesuai seberapa besar kontribusinya."}, {"t0": 182.43, "t1": 187.93, "text": "Dan bagian kesalahan itu mengalir mundur, layer demi layer."}, {"t0": 187.93, "t1": 191.94, "text": "Bagian kesalahan itulah yang disebut delta."}]]}, {"title": "Definisi delta", "paras": [[{"t0": 193.2, "t1": 201.13, "text": "Tulis ini lebih dulu: delta i didefinisikan sebagai turunan loss terhadap pre-activation s i."}], [{"t0": 201.74, "t1": 209.08, "text": "Sekarang gradient dari bobot w i j. Bobot ini mempengaruhi loss hanya lewat s i."}, {"t0": 209.08, "t1": 218.55, "text": "Jadi dengan chain rule, turunan loss terhadap w i j sama dengan delta i, dikali turunan s i terhadap w i j."}, {"t0": 218.55, "t1": 225.09, "text": "Karena s i adalah jumlah berbobot, turunan itu tidak lain adalah a j."}], [{"t0": 225.74, "t1": 230.5, "text": "Jadi gradient-nya adalah delta i dikali a j."}, {"t0": 230.5, "t1": 238.13, "text": "Dengan kata-kata: delta dari unit di atas, dikali activation dari unit di bawah."}, {"t0": 238.13, "t1": 242.04, "text": "Kalimat inilah yang ingin didengar penguji."}], [{"t0": 242.7, "t1": 251.65, "text": "Dan update-nya: w i j menjadi w i j dikurangi eta, dikali delta i, dikali a j."}]]}, {"title": "Rekursinya", "paras": [[{"t0": 252.9, "t1": 258.83, "text": "Pertanyaan berikutnya: bagaimana mendapatkan delta untuk hidden unit?"}, {"t0": 258.83, "t1": 265.14, "text": "Hidden unit j mempengaruhi loss hanya lewat unit-unit i di layer berikutnya."}, {"t0": 265.14, "t1": 269.04, "text": "Jadi kita jumlahkan semua jalur itu."}], [{"t0": 269.65, "t1": 279.43, "text": "Delta j sama dengan jumlah, untuk semua i, dari delta i dikali w i j, dikali f aksen dari s j."}], [{"t0": 280.04, "t1": 292.47, "text": "Dalam bentuk matriks: ambil delta layer di atas, kalikan dengan transpose matriks bobot, lalu kalikan elemen demi elemen dengan kemiringan activation-nya."}, {"t0": 292.47, "t1": 299.52, "text": "Delta mengalir ke bawah: kalikan W transpose, lalu kalikan f aksen."}], [{"t0": 300.13, "t1": 310.98, "text": "Gradient untuk satu matriks bobot utuh adalah outer product: vektor delta layer l dikali transpose vektor activation layer di bawahnya."}, {"t0": 310.98, "t1": 314.71, "text": "Biayanya linear terhadap jumlah bobot."}, {"t0": 314.71, "t1": 318.19, "text": "Itulah sebabnya backprop efisien."}]]}, {"title": "Delta di output", "paras": [[{"t0": 319.45, "t1": 327.42, "text": "Profesor Hochreiter menyukai pertanyaan ini: berapa delta di output dengan softmax dan cross-entropy?"}, {"t0": 327.42, "t1": 330.7, "text": "Jawabannya sederhana sekali."}, {"t0": 330.7, "t1": 333.68, "text": "Prediksi dikurangi label."}], [{"t0": 334.33, "t1": 337.24, "text": "Anda bisa menurunkannya."}, {"t0": 337.24, "t1": 357.02, "text": "Turunan output softmax a k terhadap s i sama dengan a k dikali, satu jika k sama dengan i, dikurangi a i. Masukkan ke turunan cross-entropy, gunakan fakta bahwa label one-hot berjumlah satu, dan semuanya menyusut menjadi a i dikurangi y i."}], [{"t0": 357.63, "t1": 366.98, "text": "Hasil yang sama rapinya berlaku untuk output linear dengan squared loss, dan untuk sigmoid dengan binary cross-entropy."}, {"t0": 366.98, "t1": 372.36, "text": "Karena itulah pasangan-pasangan ini selalu dipakai bersama."}]]}, {"title": "Vanishing dan exploding gradient", "paras": [[{"t0": 373.66, "t1": 376.55, "text": "Lihat lagi rekursinya."}, {"t0": 376.55, "t1": 383.27, "text": "Untuk mendapatkan delta layer pertama, kita mengalikan satu Jacobian per layer."}, {"t0": 383.27, "t1": 390.13, "text": "Jadi melewati banyak layer, delta mengecil atau membesar secara eksponensial."}, {"t0": 390.13, "t1": 394.99, "text": "Dengan sigmoid, kemiringannya paling besar seperempat."}, {"t0": 394.99, "t1": 402.97, "text": "Kalau seperempat dikali norma bobot lebih kecil dari satu, delta menghilang ketika network makin dalam."}], [{"t0": 403.59, "t1": 414.71, "text": "Dan ada kaitannya dengan Linz: Sepp Hochreiter menganalisis masalah ini dalam tesis diplomanya tahun 1991, di Linz."}, {"t0": 414.71, "t1": 423.11, "text": "Kalau penguji bertanya siapa yang menemukannya, itulah jawabannya, dan saat yang tepat untuk tersenyum."}], [{"t0": 423.72, "t1": 437.15, "text": "Solusinya: activation ReLU atau SELU, inisialisasi yang baik, normalisasi, residual connection, dan untuk data berurutan, LSTM."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 438.41, "t1": 440.35, "text": "Pertama."}, {"t0": 440.35, "t1": 444.95, "text": "Delta adalah turunan loss terhadap pre-activation."}, {"t0": 444.95, "t1": 450.26, "text": "Gradient sama dengan delta di atas dikali activation di bawah."}], [{"t0": 450.86, "t1": 452.56, "text": "Kedua."}, {"t0": 452.56, "t1": 459.2, "text": "Delta mengalir ke bawah: kalikan W transpose, lalu f aksen."}, {"t0": 459.2, "t1": 465.5, "text": "Di output, softmax dengan cross-entropy memberi prediksi dikurangi label."}], [{"t0": 466.1, "t1": 467.85, "text": "Ketiga."}, {"t0": 467.85, "t1": 472.05, "text": "Perkalian Jacobian bisa menghilang atau meledak."}, {"t0": 472.05, "t1": 478.04, "text": "Hochreiter, 1991, Linz."}, {"t0": 478.04, "t1": 486.79, "text": "Solusinya: ReLU atau SELU, inisialisasi, ResNet, LSTM."}]]}]}, {"id": "M3-id", "group": "M-id", "title": "M3 · Training yang baik: optimizer, activation, regularisasi", "file": "tracks/M3-id.mp3", "voice": "Gadis", "duration": 442.4, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 6.44, "text": "Training yang baik: optimizer, activation, regularisasi."}], [{"t0": 7.06, "t1": 12.75, "text": "Setelah gradient didapat, gradient itu harus dipakai dengan baik."}, {"t0": 12.75, "t1": 27.55, "text": "Episode ini membahas pertanyaan-pertanyaan pendek yang biasanya menyusul setelah backpropagation: gradient descent, optimizer, activation function, regularisasi, dan inisialisasi."}, {"t0": 27.55, "t1": 32.68, "text": "Pertanyaannya cepat, jadi jawabannya juga harus cepat."}, {"t0": 32.68, "t1": 37.33, "text": "Satu kalimat yang jelas, lalu satu detail."}]]}, {"title": "Gradient descent dan mini-batch", "paras": [[{"t0": 38.59, "t1": 46.12, "text": "Gradient descent menggeser bobot sedikit demi sedikit berlawanan arah dengan gradient empirical risk."}, {"t0": 46.12, "t1": 52.2, "text": "Bobot baru sama dengan bobot lama dikurangi eta, dikali gradient."}, {"t0": 52.2, "t1": 54.92, "text": "Eta adalah learning rate."}], [{"t0": 55.53, "t1": 57.84, "text": "Kenapa mini-batch?"}, {"t0": 57.84, "t1": 63.01, "text": "Bayangkan seorang pendaki di tengah kabut yang mencoba turun gunung."}, {"t0": 63.01, "t1": 70.29, "text": "Full batch ibarat mensurvei seluruh gunung sebelum setiap langkah: tepat, tetapi lambat."}, {"t0": 70.29, "t1": 77.8, "text": "Satu sampel ibarat menebak dari satu batu di bawah kaki: murah, tetapi kacau."}, {"t0": 77.8, "t1": 81.26, "text": "Mini-batch adalah jalan tengahnya."}, {"t0": 81.26, "t1": 93.11, "text": "Mini-batch memberi perkiraan gradient yang tidak bias, berjalan cepat dan paralel di GPU, dan noise kecilnya bahkan membantu bobot keluar dari minimum yang tajam."}]]}, {"title": "Optimizer apa saja yang Anda tahu?", "paras": [[{"t0": 94.37, "t1": 103.35, "text": "Gradient descent, stochastic gradient descent, momentum, AdaGrad, RMSprop, dan Adam."}], [{"t0": 103.96, "t1": 113.56, "text": "Momentum menyimpan jumlah berjalan dari gradient sebelumnya, seperti bola yang menggelinding turun dan tetap melaju melewati gundukan kecil."}, {"t0": 113.56, "t1": 122.0, "text": "AdaGrad dan RMSprop memberi setiap bobot ukuran langkahnya sendiri, berdasarkan kuadrat gradient sebelumnya."}, {"t0": 122.0, "t1": 130.76, "text": "Adam menggabungkan keduanya, momentum dan RMSprop, ditambah bias correction untuk langkah-langkah awal."}, {"t0": 130.76, "t1": 134.84, "text": "Adam adalah pilihan bawaan yang paling umum."}]]}, {"title": "Metode training lain", "paras": [[{"t0": 136.1, "t1": 142.7, "text": "Profesor Klambauer pernah bertanya: apakah ada metode selain gradient descent?"}, {"t0": 142.7, "t1": 144.33, "text": "Ada."}, {"t0": 144.33, "t1": 147.82, "text": "Model linear punya bentuk tertutup."}, {"t0": 147.82, "t1": 153.64, "text": "Logistic regression bisa memakai iteratively reweighted least squares."}, {"t0": 153.64, "t1": 159.17, "text": "RProp dan Quickprop hanya memakai tanda atau kelengkungan gradient."}, {"t0": 159.17, "t1": 168.11, "text": "Newton, Gauss-Newton, Levenberg-Marquardt, dan conjugate gradient memakai informasi orde dua."}, {"t0": 168.11, "t1": 174.55, "text": "Algoritma evolusioner atau random search sama sekali tidak butuh gradient."}]]}, {"title": "Activation function, dan yang berasal dari Linz", "paras": [[{"t0": 175.82, "t1": 185.65, "text": "Pertanyaan favorit Profesor Hochreiter: activation function apa saja yang Anda tahu, dan mana yang berasal dari Linz?"}], [{"t0": 186.31, "t1": 194.56, "text": "Sigmoid dan tanh halus, tetapi mengalami saturasi, sehingga gradient-nya menjadi kecil sekali."}, {"t0": 194.56, "t1": 207.7, "text": "ReLU murah dan tidak mengalami saturasi untuk input positif, tetapi unit bisa mati: kalau input sebuah unit terus negatif, unit itu tidak pernah belajar lagi."}], [{"t0": 208.31, "t1": 214.04, "text": "Dan dari Linz: ELU dan SELU, dikembangkan di JKU."}, {"t0": 214.04, "t1": 222.01, "text": "SELU, dari Klambauer dan rekan tahun 2017, membuat network self-normalizing."}, {"t0": 222.01, "t1": 231.58, "text": "Rata-rata dan variansi activation ditarik ke nol dan satu, layer demi layer, tanpa layer normalisasi tambahan."}, {"t0": 231.58, "t1": 241.42, "text": "Konstantanya: lambda sekitar 1,0507, dan alpha sekitar 1,6733."}, {"t0": 241.42, "t1": 246.31, "text": "Titik tetapnya adalah rata-rata nol dan variansi satu."}], [{"t0": 246.93, "t1": 256.2, "text": "Untuk layer output: linear untuk regresi, sigmoid untuk dua kelas, softmax untuk banyak kelas."}]]}, {"title": "Regularisasi", "paras": [[{"t0": 257.46, "t1": 264.91, "text": "Weight decay, dropout, early stopping, data augmentation, dan noise."}], [{"t0": 265.52, "t1": 271.92, "text": "Weight decay menambahkan penalti, lambda per dua dikali norma kuadrat bobot."}, {"t0": 271.92, "t1": 282.69, "text": "Gradient-nya menambahkan lambda dikali w, sehingga di setiap langkah bobot menyusut dengan faktor satu dikurangi eta lambda sebelum update biasa."}, {"t0": 282.69, "t1": 285.94, "text": "Dari situlah namanya berasal."}], [{"t0": 286.55, "t1": 295.26, "text": "Dropout mematikan unit secara acak selama training, sehingga network tidak bisa bergantung pada satu unit tertentu."}, {"t0": 295.26, "t1": 304.37, "text": "Bayangkan sebuah tim di mana anggota mana pun bisa absen di hari apa saja: semua orang harus menguasai pekerjaannya."}, {"t0": 304.37, "t1": 309.78, "text": "Early stopping menghentikan training ketika validation error mulai naik."}]]}, {"title": "Inisialisasi dan batch normalization", "paras": [[{"t0": 311.05, "t1": 314.27, "text": "Kenapa inisialisasi penting?"}, {"t0": 314.27, "t1": 316.77, "text": "Ada dua alasan."}, {"t0": 316.77, "t1": 321.18, "text": "Pertama, bobot acak memecah simetri."}, {"t0": 321.18, "t1": 327.23, "text": "Kalau semua bobot dimulai sama, semua unit mempelajari hal yang sama."}, {"t0": 327.23, "t1": 330.23, "text": "Kedua, skalanya."}, {"t0": 330.23, "t1": 337.35, "text": "Kalau skalanya salah, sinyal dan delta akan menghilang atau meledak saat melewati layer."}], [{"t0": 337.98, "t1": 341.12, "text": "Penurunan singkatnya begini."}, {"t0": 341.12, "t1": 349.24, "text": "Sebuah pre-activation adalah jumlah, untuk n in input, dari bobot dikali activation."}, {"t0": 349.24, "t1": 360.53, "text": "Dengan bobot independen yang rata-ratanya nol, variansinya sama dengan n in, dikali variansi bobot, dikali rata-rata kuadrat activation."}, {"t0": 360.53, "t1": 366.54, "text": "Supaya variansinya tetap, pilih variansi bobot satu per n in."}, {"t0": 366.54, "t1": 373.76, "text": "Untuk ReLU, yang memotong rata-rata kuadrat menjadi setengah, pilih dua per n in."}, {"t0": 373.76, "t1": 377.04, "text": "Itulah He initialization."}], [{"t0": 377.65, "t1": 388.65, "text": "Batch normalization menstandarkan setiap pre-activation pada mini-batch, lalu mengatur ulang skala dan pergeserannya dengan parameter yang dipelajari."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 389.91, "t1": 391.85, "text": "Pertama."}, {"t0": 391.85, "t1": 400.3, "text": "Mini-batch: perkiraan gradient yang murah, tidak bias, paralel, dengan noise yang berguna."}, {"t0": 400.3, "t1": 405.95, "text": "Adam adalah momentum ditambah RMSprop dengan bias correction."}], [{"t0": 406.56, "t1": 408.24, "text": "Kedua."}, {"t0": 408.24, "t1": 412.58, "text": "Activation dari Linz adalah ELU dan SELU."}, {"t0": 412.58, "t1": 423.35, "text": "SELU bersifat self-normalizing, dengan lambda sekitar 1,0507 dan alpha sekitar 1,6733."}], [{"t0": 423.96, "t1": 425.71, "text": "Ketiga."}, {"t0": 425.71, "t1": 433.88, "text": "Inisialisasi menjaga variansi tetap: satu per n in, atau dua per n in untuk ReLU."}, {"t0": 433.88, "t1": 442.35, "text": "Regularisasi: weight decay, dropout, early stopping, augmentation, noise."}]]}]}, {"id": "M4-id", "group": "M-id", "title": "M4 · Arsitektur: CNN, ResNet, RNN, LSTM, dan Transformer", "file": "tracks/M4-id.mp3", "voice": "Gadis", "duration": 520.8, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 9.01, "text": "Arsitektur: CNN, ResNet, RNN, LSTM, dan Transformer."}], [{"t0": 9.62, "t1": 18.63, "text": "Di kebanyakan ujian, setelah bagian inti, penguji memilih satu arsitektur dan meminta Anda menjelaskannya."}, {"t0": 18.63, "t1": 30.98, "text": "Jadi untuk setiap arsitektur, siapkan tiga hal: idenya dalam satu kalimat, kenapa arsitektur itu bekerja, dan satu rumus yang menunjukkannya."}]]}, {"title": "Convolutional network", "paras": [[{"t0": 32.23, "t1": 42.86, "text": "Idenya: filter kecil dengan bobot yang dipakai bersama digeser di atas gambar, sehingga sebuah pola bisa ditemukan di mana pun letaknya."}], [{"t0": 43.46, "t1": 46.33, "text": "Kenapa cocok untuk gambar?"}, {"t0": 46.33, "t1": 52.03, "text": "Gambar punya struktur lokal, piksel yang berdekatan saling berkaitan."}, {"t0": 52.03, "t1": 59.03, "text": "Dan pola yang sama, misalnya tepi atau mata, bisa muncul di mana saja."}, {"t0": 59.03, "t1": 70.23, "text": "Bobot yang dipakai bersama membuat jumlah parameter sedikit dan menghasilkan translation equivariance: geser gambarnya, feature map ikut bergeser."}, {"t0": 70.23, "t1": 75.47, "text": "Pooling memperkecil ukuran map dan menambah sedikit invariansi."}, {"t0": 75.47, "t1": 80.38, "text": "Layer yang lebih dalam melihat bagian gambar yang lebih luas."}], [{"t0": 81.0, "t1": 92.43, "text": "Angka yang perlu diingat: ukuran output sama dengan pembulatan ke bawah dari n ditambah dua p dikurangi k, dibagi s, lalu ditambah satu."}, {"t0": 92.43, "t1": 99.97, "text": "Di sini n adalah ukuran input, k ukuran kernel, p padding, dan s stride."}]]}, {"title": "ResNet dan U-Net", "paras": [[{"t0": 101.23, "t1": 105.58, "text": "ResNet menambahkan input sebuah blok ke output-nya."}, {"t0": 105.58, "t1": 112.88, "text": "Activation berikutnya sama dengan activation sekarang ditambah F dari activation sekarang."}, {"t0": 112.88, "t1": 115.12, "text": "Kenapa membantu?"}, {"t0": 115.12, "t1": 121.07, "text": "Jacobian sebuah residual block adalah identitas ditambah bagian kecil."}, {"t0": 121.07, "t1": 127.88, "text": "Jadi delta tidak menyusut, dan gradient bisa melewati network yang sangat dalam."}, {"t0": 127.88, "t1": 131.58, "text": "Mirip lift ekspres di samping tangga."}], [{"t0": 132.19, "t1": 135.66, "text": "U-Net dipakai untuk segmentasi."}, {"t0": 135.66, "t1": 141.47, "text": "Isinya encoder dan decoder dengan skip connection di antara keduanya."}, {"t0": 141.47, "t1": 149.67, "text": "U-Net memprediksi satu kelas per piksel, dan skip connection menyalin detail halus dari encoder ke decoder."}, {"t0": 149.67, "t1": 153.56, "text": "Profesor Klambauer pernah menanyakan U-Net."}]]}, {"title": "Recurrent network", "paras": [[{"t0": 154.87, "t1": 164.1, "text": "Idenya: RNN membaca sebuah urutan langkah demi langkah dan menyimpan hidden state yang membawa informasi masa lalu."}], [{"t0": 164.7, "t1": 174.25, "text": "Forward pass-nya: s dari t sama dengan W dikali x dari t, ditambah R dikali a dari t dikurangi satu."}, {"t0": 174.25, "t1": 185.76, "text": "Lalu a dari t sama dengan f dari s dari t. Bobot yang sama dipakai di setiap langkah, jadi jumlah parameter tidak bertambah seiring panjang urutan."}], [{"t0": 186.37, "t1": 189.29, "text": "Bagaimana cara melatihnya?"}, {"t0": 189.29, "t1": 192.69, "text": "Dengan backpropagation through time."}, {"t0": 192.69, "t1": 202.26, "text": "Bentangkan network sepanjang urutan, lalu lakukan backpropagation seperti pada network dalam dengan bobot yang dipakai bersama."}, {"t0": 202.26, "t1": 211.62, "text": "Delta di setiap langkah mendapat dua sumbangan: satu dari output di langkah itu, dan satu dari langkah berikutnya."}, {"t0": 211.62, "t1": 218.09, "text": "Karena bobotnya dipakai bersama, gradient-nya dijumlahkan sepanjang waktu."}]]}, {"title": "Kenapa RNN biasa gagal, dan bagaimana LSTM memperbaikinya", "paras": [[{"t0": 219.35, "t1": 226.03, "text": "Di setiap langkah mundur dalam waktu, delta dikalikan dengan recurrent Jacobian."}, {"t0": 226.03, "t1": 231.03, "text": "Untuk urutan yang panjang, hasil perkaliannya menghilang."}, {"t0": 231.03, "t1": 236.21, "text": "Jadi RNN biasa melupakan ketergantungan jarak jauh."}, {"t0": 236.21, "t1": 241.89, "text": "Masalah vanishing gradient yang sama, kini terjadi dalam waktu."}], [{"t0": 242.51, "t1": 254.38, "text": "LSTM, dari Hochreiter dan Schmidhuber tahun 1997, memperbaikinya dengan memory cell yang diperbarui lewat penjumlahan."}, {"t0": 254.38, "t1": 262.23, "text": "Cell c dari t sama dengan forget gate dikali cell lama, ditambah input gate dikali input baru."}, {"t0": 262.23, "t1": 266.62, "text": "Output gate menentukan apa yang dibaca dari cell."}], [{"t0": 267.23, "t1": 275.1, "text": "Baris kuncinya: turunan c dari t terhadap c dari t dikurangi satu hanyalah forget gate."}, {"t0": 275.1, "t1": 281.38, "text": "Ketika forget gate mendekati satu, turunan itu mendekati identitas."}, {"t0": 281.38, "t1": 286.28, "text": "Jadi error mengalir mundur sepanjang waktu tanpa menyusut."}, {"t0": 286.28, "t1": 289.57, "text": "Inilah constant error carousel."}, {"t0": 289.57, "t1": 300.99, "text": "Bayangkan ban berjalan yang membawa ingatan ke depan, dan gate-gate adalah pekerja yang memutuskan apa yang diletakkan di ban, apa yang tetap, dan apa yang diangkat."}]]}, {"title": "Bidirectional RNN dan label untuk satu urutan", "paras": [[{"t0": 302.24, "t1": 307.91, "text": "Profesor Schlüter pernah bertanya tentang \"RNN dari masa depan\"."}, {"t0": 307.91, "t1": 317.37, "text": "Bidirectional RNN menjalankan satu RNN maju dan satu RNN mundur, lalu menggabungkan state keduanya."}, {"t0": 317.37, "t1": 322.31, "text": "Jadi setiap langkah melihat masa lalu dan masa depan."}, {"t0": 322.31, "t1": 329.35, "text": "Batasnya: butuh seluruh urutan, jadi tidak cocok untuk penggunaan real-time."}], [{"t0": 329.96, "t1": 341.0, "text": "Untuk satu label per urutan, pakai hidden state terakhir, atau gabungkan semua hidden state dengan pooling, lalu pasang classifier di atasnya."}]]}, {"title": "Attention dan Transformer", "paras": [[{"t0": 342.27, "t1": 351.35, "text": "Idenya: setiap token mengambil rata-rata berbobot dari semua token, dan bobotnya berasal dari query dikali key."}], [{"t0": 351.97, "t1": 359.6, "text": "Setiap token membentuk tiga vektor lewat pemetaan linear: query, key, dan value."}, {"t0": 359.6, "t1": 369.87, "text": "Bobot attention adalah softmax dari query dikali key, dibagi akar kuadrat d k. Output-nya mencampur value dengan bobot tersebut."}], [{"t0": 370.49, "t1": 373.49, "text": "Kenapa dibagi akar d k?"}, {"t0": 373.49, "t1": 388.73, "text": "Kalau entri query dan key independen dengan variansi satu, perkalian titiknya bervariansi d k. Membaginya dengan akarnya mengembalikan variansi ke satu, sehingga softmax tidak mengalami saturasi."}], [{"t0": 389.35, "t1": 399.61, "text": "Satu blok Transformer berisi multi-head self-attention ditambah MLP, masing-masing dengan residual connection dan layer normalization."}]]}, {"title": "Dua pertanyaan lanjutan", "paras": [[{"t0": 400.87, "t1": 409.42, "text": "Profesor Lehner pernah bertanya: Transformer bersifat permutation-equivariant, kenapa itu masalah?"}, {"t0": 409.42, "t1": 414.53, "text": "Karena self-attention melihat token sebagai sebuah himpunan."}, {"t0": 414.53, "t1": 419.95, "text": "Kalau token diacak, output-nya teracak dengan cara yang sama."}, {"t0": 419.95, "t1": 422.61, "text": "Urutan kata hilang."}, {"t0": 422.61, "t1": 432.75, "text": "Jadi informasi posisi ditambahkan: sinusoid tetap, vektor yang dipelajari, atau relative encoding seperti RoPE."}], [{"t0": 433.37, "t1": 438.26, "text": "Dan: bandingkan biaya RNN dan Transformer."}, {"t0": 438.26, "t1": 444.87, "text": "RNN linear terhadap panjang urutan, orde N, tetapi berurutan."}, {"t0": 444.87, "t1": 458.17, "text": "Transformer kuadratik, orde N kuadrat, karena setiap token memperhatikan setiap token, tetapi semua token diproses paralel, dan jalur jarak jauh hanya satu langkah."}, {"t0": 458.17, "t1": 467.43, "text": "Karena itu juga model bergaya LSTM seperti xLSTM kembali menarik: inferensinya linear dalam N."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 468.74, "t1": 470.68, "text": "Pertama."}, {"t0": 470.68, "t1": 476.75, "text": "CNN: filter lokal, bobot bersama, pooling."}, {"t0": 476.75, "t1": 484.2, "text": "ResNet: identitas ditambah residual, jadi Jacobian tetap dekat identitas."}], [{"t0": 484.82, "t1": 486.48, "text": "Kedua."}, {"t0": 486.48, "t1": 494.18, "text": "RNN: bobot sama di setiap langkah, dilatih dengan backpropagation through time."}, {"t0": 494.18, "t1": 504.29, "text": "LSTM: pembaruan cell lewat penjumlahan, jadi dengan forget gate mendekati satu, error terbawa tanpa berubah."}], [{"t0": 504.91, "t1": 506.65, "text": "Ketiga."}, {"t0": 506.65, "t1": 513.74, "text": "Attention: softmax dari query kali key dibagi akar d k, dikali value."}, {"t0": 513.74, "t1": 520.81, "text": "Transformer butuh informasi posisi, berbiaya N kuadrat tetapi berjalan paralel."}]]}]}, {"id": "M5-id", "group": "M-id", "title": "M5 · Machine learning klasik, REINFORCE, dan evaluasi model", "file": "tracks/M5-id.mp3", "voice": "Gadis", "duration": 449.1, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 5.95, "text": "Machine learning klasik, REINFORCE, dan evaluasi model."}], [{"t0": 6.55, "t1": 23.23, "text": "Episode ML&P terakhir membahas pertanyaan yang berada di samping deep learning: support vector machine, kernel, VC dimension, loss REINFORCE, serta cara mengevaluasi dan menguji ketahanan sebuah classifier."}, {"t0": 23.23, "t1": 30.97, "text": "Sebagian pernah ditanyakan Profesor Kofler dan Profesor Hochreiter, jadi layak diperhatikan."}]]}, {"title": "Support vector machine", "paras": [[{"t0": 32.23, "t1": 39.63, "text": "Idenya dalam satu kalimat: SVM mencari hyperplane pemisah dengan margin terbesar."}], [{"t0": 40.25, "t1": 44.74, "text": "Bayangkan sebuah jalan di antara dua kelompok rumah."}, {"t0": 44.74, "t1": 52.71, "text": "SVM membangun jalan yang selebar mungkin, dan rumah-rumah yang menyentuh tepi jalan disebut support vector."}, {"t0": 52.71, "t1": 56.73, "text": "Hanya merekalah yang menentukan letak jalan."}], [{"t0": 57.33, "t1": 61.51, "text": "Margin-nya sama dengan dua dibagi norma w."}, {"t0": 61.51, "t1": 66.84, "text": "Jadi memaksimalkan margin berarti meminimalkan norma w kuadrat."}, {"t0": 66.84, "t1": 72.82, "text": "Pada versi soft-margin, sebagian titik boleh berada di dalam margin."}, {"t0": 72.82, "t1": 79.1, "text": "Hal itu diizinkan lewat slack variable, dan dibayar dengan penalti C."}, {"t0": 79.1, "t1": 90.57, "text": "Jadi yang diminimalkan adalah setengah norma w kuadrat, ditambah C dikali jumlah slack, dengan syarat setiap titik berada di sisi yang benar, sejauh slack-nya."}], [{"t0": 91.19, "t1": 97.12, "text": "Pada dual problem, yang muncul hanyalah perkalian titik antar data."}, {"t0": 97.12, "t1": 102.89, "text": "Titik-titik dengan alpha n lebih besar dari nol adalah support vector."}]]}, {"title": "Kernel dan kernel trick", "paras": [[{"t0": 104.15, "t1": 111.42, "text": "Kernel adalah perkalian titik di sebuah feature space, yang dihitung tanpa membangun feature-nya."}], [{"t0": 112.02, "t1": 115.01, "text": "Contoh klasiknya begini."}, {"t0": 115.01, "t1": 122.17, "text": "Ambil polynomial kernel di dua dimensi: x transpose x aksen, dikuadratkan."}, {"t0": 122.17, "t1": 135.21, "text": "Kalikan semuanya, dan hasilnya persis perkalian titik dua vektor feature, dengan feature x satu kuadrat, akar dua kali x satu x dua, dan x dua kuadrat."}, {"t0": 135.21, "t1": 142.97, "text": "Jadi kernel menghitung perkalian titik di feature space tiga dimensi itu, tanpa pernah membangunnya."}], [{"t0": 143.58, "t1": 151.49, "text": "Karena dual SVM hanya membutuhkan perkalian titik, perkalian itu bisa diganti dengan kernel."}, {"t0": 151.49, "t1": 157.02, "text": "Hasilnya classifier non-linear dengan biaya classifier linear."}, {"t0": 157.02, "t1": 161.43, "text": "Contohnya polynomial kernel dan Gaussian kernel."}]]}, {"title": "VC dimension", "paras": [[{"t0": 162.69, "t1": 171.42, "text": "VC dimension adalah jumlah titik terbanyak yang bisa diberi label oleh sebuah kelas model dengan semua kemungkinan cara."}, {"t0": 171.42, "t1": 176.07, "text": "Kelas model itu dikatakan mampu shatter himpunan tersebut."}, {"t0": 176.07, "t1": 179.99, "text": "VC dimension mengukur kapasitas."}, {"t0": 179.99, "t1": 186.9, "text": "Untuk classifier linear di d dimensi, VC dimension-nya d ditambah satu."}, {"t0": 186.9, "t1": 197.32, "text": "Dalam generalization bound, jarak antara training error dan test error membesar seiring VC dimension dan mengecil seiring jumlah sampel."}]]}, {"title": "REINFORCE, ditanyakan Profesor Hochreiter", "paras": [[{"t0": 198.59, "t1": 202.95, "text": "Kita ingin policy dengan expected return terbesar."}, {"t0": 202.95, "t1": 213.11, "text": "Expected return J dari theta adalah integral, untuk semua trajectory, dari probabilitas trajectory dikali return-nya."}], [{"t0": 213.71, "t1": 228.9, "text": "Triknya adalah log-derivative trick: gradient dari p sama dengan p dikali gradient log p. Trik ini memindahkan gradient ke dalam nilai harapan, sehingga gradient bisa diperkirakan dari episode yang diambil sampelnya."}], [{"t0": 229.52, "t1": 234.12, "text": "Sekarang tulis log-probabilitas sebuah trajectory."}, {"t0": 234.12, "t1": 243.02, "text": "Isinya log keadaan awal, ditambah jumlah sepanjang waktu dari log-policy, ditambah log dinamika lingkungan."}, {"t0": 243.02, "t1": 247.33, "text": "Lingkungan tidak bergantung pada parameter policy."}, {"t0": 247.33, "t1": 252.82, "text": "Jadi saat gradient diambil, hanya suku policy yang tersisa."}], [{"t0": 253.42, "t1": 265.08, "text": "Hasilnya: gradient J sama dengan nilai harapan dari jumlah sepanjang waktu, gradient log pi dari a t diberi s t, dikali return G t."}, {"t0": 265.08, "t1": 274.47, "text": "Sebagai loss yang diminimalkan, kita tulis minus jumlah log pi dari aksi, dikali return dikurangi sebuah baseline."}, {"t0": 274.47, "t1": 281.22, "text": "Baseline tidak mengubah nilai harapan gradient, tetapi mengurangi variansinya."}]]}, {"title": "Bagaimana mengevaluasi sebuah classifier?", "paras": [[{"t0": 282.49, "t1": 290.59, "text": "Dengan confusion matrix, precision, recall, dan area di bawah kurva ROC."}], [{"t0": 291.2, "t1": 297.44, "text": "Precision: dari semua yang saya sebut positif, berapa yang benar?"}, {"t0": 297.44, "t1": 302.76, "text": "True positive dibagi true positive ditambah false positive."}, {"t0": 302.76, "t1": 309.09, "text": "Recall: dari semua yang benar-benar positif, berapa yang saya temukan?"}, {"t0": 309.09, "t1": 314.43, "text": "True positive dibagi true positive ditambah false negative."}, {"t0": 314.43, "t1": 321.2, "text": "Cara mudah mengingat: precision itu seberapa bersih, recall itu seberapa lengkap."}], [{"t0": 321.82, "t1": 328.72, "text": "Kurva ROC menggambarkan true-positive rate terhadap false-positive rate, untuk semua threshold."}, {"t0": 328.72, "t1": 337.74, "text": "AUC adalah probabilitas bahwa sebuah sampel positif acak mendapat skor lebih tinggi daripada sampel negatif acak."}, {"t0": 337.74, "t1": 342.09, "text": "AUC 0,5 berarti seperti menebak."}, {"t0": 342.09, "t1": 345.69, "text": "AUC satu berarti sempurna."}]]}, {"title": "Bagaimana lagi mengukur robustness?", "paras": [[{"t0": 346.95, "t1": 355.2, "text": "Profesor Klambauer pernah bertanya: selain adversarial attack, bagaimana lagi mengukur robustness?"}, {"t0": 355.2, "t1": 363.8, "text": "Uji di bawah distribution shift: input yang rusak, domain baru, data dari waktu yang berbeda."}, {"t0": 363.8, "t1": 370.73, "text": "Periksa kalibrasi dan ketidakpastian, dengan ensemble atau Monte Carlo dropout."}, {"t0": 370.73, "t1": 376.51, "text": "Dan periksa seberapa sensitif output terhadap perubahan kecil pada input."}], [{"t0": 377.11, "t1": 381.01, "text": "Di sini Anda bisa membawa tesis sendiri."}, {"t0": 381.01, "t1": 388.85, "text": "Rekaman yang dibuat di bawah satu kondisi batas gagal di kondisi batas lain, karena regime-nya berubah."}, {"t0": 388.85, "t1": 394.22, "text": "Itu distribution shift, dalam sebuah simulasi fisika."}, {"t0": 394.22, "t1": 397.41, "text": "Jawaban yang kuat dan personal."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 398.67, "t1": 400.61, "text": "Pertama."}, {"t0": 400.61, "t1": 411.47, "text": "SVM: margin maksimum; dual-nya hanya berisi perkalian titik, jadi kernel memberi classifier non-linear dengan biaya linear."}, {"t0": 411.47, "t1": 417.61, "text": "Classifier linear di d dimensi punya VC dimension d ditambah satu."}], [{"t0": 418.27, "t1": 419.94, "text": "Kedua."}, {"t0": 419.94, "t1": 429.76, "text": "REINFORCE: log-derivative trick, dinamika lingkungan hilang, dan loss-nya minus log pi dikali return dikurangi baseline."}], [{"t0": 430.37, "t1": 432.11, "text": "Ketiga."}, {"t0": 432.11, "t1": 439.31, "text": "Precision itu seberapa bersih, recall seberapa lengkap, AUC kualitas pemeringkatan."}, {"t0": 439.31, "t1": 449.04, "text": "Robustness: distribution shift, kalibrasi, sensitivitas, dan contoh regime dari tesis Anda."}]]}]}, {"id": "T1-id", "group": "T-id", "title": "T1 · Tesis saya dalam bahasa sederhana", "file": "tracks/T1-id.mp3", "voice": "Gadis", "duration": 431.1, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 3.54, "text": "Tesis saya dalam bahasa sederhana."}], [{"t0": 4.15, "t1": 11.57, "text": "Ada satu pertanyaan yang hampir pasti muncul saat sidang: masalah apa yang Anda selesaikan?"}, {"t0": 11.57, "t1": 18.9, "text": "Jadi mari kita latih jawabannya pelan-pelan, sampai terasa seperti cerita Anda sendiri."}], [{"t0": 19.51, "t1": 22.26, "text": "Mulai dari metodenya."}, {"t0": 22.26, "t1": 28.0, "text": "Recurrence CFD adalah cara untuk membuat simulasi jadi murah."}, {"t0": 28.0, "t1": 32.57, "text": "Anda menjalankan satu simulasi penuh yang normal."}, {"t0": 32.57, "t1": 42.3, "text": "Selama simulasi berjalan, Anda merekam, frame demi frame, berapa bagian dari setiap sel yang berpindah ke sel lain."}, {"t0": 42.3, "t1": 47.88, "text": "Setelah itu, kecepatan dan tekanan tidak pernah dihitung lagi."}, {"t0": 47.88, "t1": 55.76, "text": "Gerakan yang sudah direkam cukup diputar ulang, lalu dipakai untuk membawa sesuatu di dalam tangki."}, {"t0": 55.76, "t1": 58.67, "text": "Karena itu metodenya cepat."}, {"t0": 58.67, "t1": 66.01, "text": "Dalam kasus saya, simulasi penuh butuh 569 menit waktu solver."}, {"t0": 66.01, "t1": 69.6, "text": "Satu replay hanya sekitar dua menit."}, {"t0": 69.6, "t1": 73.81, "text": "Kira-kira 260 kali lebih cepat."}], [{"t0": 74.42, "t1": 77.05, "text": "Sekarang masalahnya."}, {"t0": 77.05, "t1": 87.79, "text": "Metode ini dibuat untuk passive scalar, yaitu sesuatu yang ikut terbawa aliran tetapi tidak mengubah aliran itu, seperti zat pewarna."}, {"t0": 87.79, "t1": 90.36, "text": "Suhu tidak begitu."}, {"t0": 90.36, "t1": 94.86, "text": "Air hangat lebih ringan, jadi naik ke atas."}, {"t0": 94.86, "t1": 99.32, "text": "Suhu ikut menggerakkan aliran lewat gaya apung."}, {"t0": 99.32, "t1": 106.18, "text": "Jadi ketika replay memakai gerakan rekaman yang tetap, umpan balik tersebut terputus."}], [{"t0": 106.79, "t1": 113.83, "text": "Maka jawaban untuk pertanyaan \"masalah apa yang Anda selesaikan\" kira-kira begini."}, {"t0": 113.83, "t1": 121.49, "text": "Saya menguji recurrence CFD pada suhu, sebuah scalar yang menggerakkan alirannya sendiri."}, {"t0": 121.49, "t1": 130.08, "text": "Saya mengukur apa yang hilang dalam replay, dan seberapa banyak yang bisa diperbaiki tanpa menghitung aliran lagi."}]]}, {"title": "Mengapa orang harus peduli?", "paras": [[{"t0": 131.35, "t1": 136.73, "text": "Pertanyaan kedua sering berbunyi: kenapa saya harus peduli?"}, {"t0": 136.73, "t1": 140.47, "text": "Jawaban singkat dan jujurnya begini."}, {"t0": 140.47, "t1": 149.75, "text": "Proses termal berjalan berjam-jam, dan CFD penuh untuk waktu sepanjang itu terlalu lambat untuk dipakai sehari-hari."}, {"t0": 149.75, "t1": 155.27, "text": "Replay yang 260 kali lebih cepat terdengar bagus sekali."}, {"t0": 155.27, "t1": 160.64, "text": "Tetapi model yang cepat hanya berguna kalau galatnya diketahui."}, {"t0": 160.64, "t1": 170.08, "text": "Tesis saya mengukur galat tersebut, pada kasus di mana suhu berperan, dan menunjukkan bagian mana yang bisa diperbaiki."}], [{"t0": 170.7, "t1": 175.38, "text": "Cepat itu berguna hanya kalau galatnya diketahui."}, {"t0": 175.38, "t1": 183.3, "text": "Ucapkan kalimat ini pelan-pelan dalam bahasa Inggris: fast is useful only with a known error."}, {"t0": 183.3, "t1": 186.72, "text": "Kalimat ini bagus untuk diingat."}]]}, {"title": "Recurrence CFD dengan kata-kata sederhana", "paras": [[{"t0": 187.98, "t1": 196.2, "text": "Kalau diminta menjelaskan recurrence CFD secara sederhana, pakai gambaran kamera lalu lintas."}, {"t0": 196.2, "t1": 201.93, "text": "Bayangkan sebuah kamera yang merekam rute setiap mobil di sebuah kota."}, {"t0": 201.93, "t1": 207.35, "text": "Lain kali, Anda tidak perlu mensimulasikan para pengemudi."}, {"t0": 207.35, "t1": 212.16, "text": "Rute yang sudah terekam dipakai ulang untuk memindahkan paket."}, {"t0": 212.16, "t1": 215.15, "text": "Begitulah replay bekerja."}], [{"t0": 215.75, "t1": 222.74, "text": "Tetapi setiap analogi punya batas, dan penguji senang menanyakan batas itu."}, {"t0": 222.74, "t1": 227.77, "text": "Batasnya begini: rekaman tidak menyimpan gambar."}, {"t0": 227.77, "t1": 233.56, "text": "Yang disimpan adalah peta berapa banyak fluida berpindah dari sel ke sel."}, {"t0": 233.56, "t1": 240.37, "text": "Dan kalau paketnya cukup berat sampai mengubah lalu lintas, rute lama menjadi salah."}, {"t0": 240.37, "t1": 242.68, "text": "Begitulah suhu."}], [{"t0": 243.3, "t1": 246.91, "text": "Satu langkah replay punya empat tahap."}, {"t0": 246.91, "t1": 254.0, "text": "Ingat urutannya dalam bahasa Inggris: map, swap, correct, balance."}, {"t0": 254.0, "t1": 258.2, "text": "Map: peta rekaman memindahkan panas."}, {"t0": 258.2, "t1": 264.16, "text": "Swap: face exchange menambah sedikit pencampuran antar sel tetangga."}, {"t0": 264.16, "t1": 269.89, "text": "Correct: tahap koreksi, dan di sinilah kontribusi saya."}, {"t0": 269.89, "t1": 275.32, "text": "Balance: conservation constraint membetulkan total panas."}, {"t0": 275.32, "t1": 281.98, "text": "Pada recurrence CFD standar, tahap koreksi tidak melakukan apa-apa."}, {"t0": 281.98, "t1": 287.0, "text": "Dalam tesis saya, justru tahap inilah yang bekerja."}]]}, {"title": "Mengapa ini termasuk AI, bukan hanya CFD?", "paras": [[{"t0": 288.28, "t1": 294.84, "text": "Pertanyaan ini pernah muncul di sidang sebelumnya, jadi siapkan jawabannya."}, {"t0": 294.84, "t1": 299.79, "text": "Recurrence CFD termasuk simulasi berbasis data."}, {"t0": 299.79, "t1": 306.22, "text": "Solver yang mahal menghasilkan data, lalu model yang murah memakainya ulang."}, {"t0": 306.22, "t1": 312.03, "text": "Database berisi keadaan aliran yang terekam berperan sebagai data latih."}, {"t0": 312.03, "t1": 321.56, "text": "Memilih frame berikutnya sama dengan nearest-neighbour search di dalam database itu, yang dikenal sebagai method of analogues."}], [{"t0": 322.16, "t1": 326.77, "text": "Temuan utama saya sebenarnya soal generalisasi."}, {"t0": 326.77, "t1": 331.35, "text": "Sebuah database berlaku untuk satu flow regime."}, {"t0": 331.35, "t1": 339.27, "text": "Kalau satu kondisi batas mengubah regime-nya, database tersebut menjadi out of distribution."}, {"t0": 339.27, "t1": 345.98, "text": "Dalam bahasa machine learning: data uji tidak lagi mirip dengan data latih."}, {"t0": 345.98, "t1": 351.4, "text": "Persis itulah yang terjadi ketika tutup tangki saya didinginkan."}]]}, {"title": "Kasus uji", "paras": [[{"t0": 352.69, "t1": 357.38, "text": "Anda harus bisa menggambarkan tangkinya tanpa catatan."}, {"t0": 357.38, "t1": 366.95, "text": "Tangki tertutup, tujuh puluh lima kali tujuh puluh lima kali lima belas milimeter, dengan sel berukuran satu milimeter."}, {"t0": 366.95, "t1": 379.28, "text": "Semburan hangat masuk di tengah ketinggian, bersuhu 333 kelvin dengan kecepatan 0,02 meter per detik, selama 315 detik."}, {"t0": 379.28, "t1": 385.33, "text": "Bilangan Reynolds sekitar 99, jadi alirannya laminar."}, {"t0": 385.33, "t1": 392.0, "text": "Tutupnya ada dua versi: satu terisolasi, satu didinginkan."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 393.27, "t1": 395.21, "text": "Pertama."}, {"t0": 395.21, "t1": 405.6, "text": "Masalahnya: recurrence CFD dibuat untuk zat pewarna, dan saya mengujinya pada suhu, yang balik mempengaruhi aliran."}], [{"t0": 406.21, "t1": 407.89, "text": "Kedua."}, {"t0": 407.89, "t1": 419.14, "text": "Nilainya: 260 kali lebih cepat, tetapi cepat itu berguna hanya kalau galatnya diketahui, dan galat itulah yang saya ukur."}], [{"t0": 419.74, "t1": 421.49, "text": "Ketiga."}, {"t0": 421.49, "t1": 431.14, "text": "Sudut pandang AI: database adalah data latih, dan flow regime yang baru berarti datanya out of distribution."}]]}]}, {"id": "T2-id", "group": "T-id", "title": "T2 · Di dalam replay: knob, saluran keluar, dan limiter", "file": "tracks/T2-id.mp3", "voice": "Gadis", "duration": 571.5, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 5.96, "text": "Di dalam replay: knob, saluran keluar, dan limiter."}], [{"t0": 6.58, "t1": 15.81, "text": "Episode ini membahas jantung tesis: kenapa replay standar meleset, dan bagaimana koreksi saya memperbaikinya."}, {"t0": 15.81, "t1": 24.71, "text": "Kalau cerita ini bisa Anda sampaikan dengan jelas, sebagian besar pertanyaan tentang bab empat dan lima bisa Anda jawab."}]]}, {"title": "Apakah alirannya berulang?", "paras": [[{"t0": 25.97, "t1": 33.77, "text": "Mulai dari pertanyaan yang mungkin diajukan Profesor Pirker: apakah aliran Anda benar-benar recurrent?"}, {"t0": 33.77, "t1": 37.1, "text": "Jawaban jujurnya: tidak."}], [{"t0": 37.7, "t1": 43.24, "text": "Recurrence matrix membandingkan setiap pasangan keadaan yang terekam."}, {"t0": 43.24, "t1": 50.84, "text": "Jarak yang kecil berarti dua keadaan mirip, sehingga replay bisa melompat dari satu ke yang lain."}, {"t0": 50.84, "t1": 57.86, "text": "Di tangki saya, matriksnya terbagi dua blok: tahap pengisian dan tahap pengendapan."}, {"t0": 57.86, "t1": 61.05, "text": "Tidak ada keadaan yang kembali."}, {"t0": 61.05, "t1": 67.69, "text": "Metodenya meminta prominence sekitar 0,05 sampai 0,1."}, {"t0": 67.69, "t1": 72.48, "text": "Tangki saya punya median 0,028."}, {"t0": 72.48, "t1": 77.23, "text": "Jadi replay cukup memutar frame secara berurutan."}], [{"t0": 77.85, "t1": 82.21, "text": "Apakah masih bisa disebut recurrence CFD?"}, {"t0": 82.21, "t1": 83.67, "text": "Ya."}, {"t0": 83.67, "t1": 92.17, "text": "Penghematannya tidak datang dari lompatan antar frame, melainkan dari tidak menghitung kecepatan dan tekanan lagi."}]]}, {"title": "Face exchange dan knob-nya", "paras": [[{"t0": 93.43, "t1": 97.54, "text": "Perpindahan murni tidak mencampur apa pun."}, {"t0": 97.54, "t1": 107.44, "text": "Karena itu, setelah setiap langkah, library replay menukar sebagian panas lewat setiap face, dari sel hangat ke sel dingin."}, {"t0": 107.44, "t1": 120.38, "text": "Kekuatan pertukaran per langkah ini disebut f s d. Besaran ini tidak bersatuan, jadi bukan koefisien difusi, tetapi bisa diterjemahkan menjadi koefisien difusi."}], [{"t0": 121.0, "t1": 123.94, "text": "Sifat pentingnya begini."}, {"t0": 123.94, "t1": 128.57, "text": "Pertukaran ini hanya bisa mengurangi perbedaan."}, {"t0": 128.57, "t1": 133.7, "text": "Ia tidak pernah bisa membangun kembali front yang sudah melebar."}]]}, {"title": "Tidak ada satu setelan terbaik", "paras": [[{"t0": 134.97, "t1": 139.11, "text": "Saya menjalankan tujuh nilai kekuatan."}, {"t0": 139.11, "t1": 148.13, "text": "Kandungan panas tangki paling baik tanpa pencampuran tambahan, dengan galat suhu rata-rata 1,07 kelvin."}, {"t0": 148.13, "t1": 156.52, "text": "Tinggi lapisan hangat paling baik di sekitar setengah, dengan galat hanya 0,068 milimeter."}, {"t0": 156.52, "t1": 161.29, "text": "Jadi tidak ada satu nilai yang terbaik untuk keduanya."}, {"t0": 161.29, "t1": 168.43, "text": "Dengan pencampuran terkuat, tangki berakhir 5,08 kelvin terlalu dingin."}], [{"t0": 169.05, "t1": 173.53, "text": "Kenapa pencampuran lebih banyak membuat panas hilang?"}, {"t0": 173.53, "t1": 180.35, "text": "Bayangkan bak mandi yang lubang pembuangannya dipasang tepat di bawah lapisan permukaan yang hangat."}, {"t0": 180.35, "t1": 185.58, "text": "Kalau lapisan itu tetap tipis, yang terbuang air dingin."}, {"t0": 185.58, "t1": 192.89, "text": "Kalau lapisan itu melebar ke bawah, air hangat mencapai lubang pembuangan dan ikut keluar."}, {"t0": 192.89, "t1": 197.62, "text": "Di tangki saya, outlet berada tepat di bawah front."}, {"t0": 197.62, "t1": 202.46, "text": "Jadi front yang melebar berubah menjadi kebocoran panas."}], [{"t0": 203.08, "t1": 207.95, "text": "Saya menunjukkannya dengan neraca energi seluruh tangki."}, {"t0": 207.95, "t1": 213.0, "text": "Energi masuk dikurangi energi keluar memberi suhu outlet."}, {"t0": 213.0, "t1": 220.47, "text": "Selama semburan hangat, replay standar menahan panas berlebih sekitar 2,7 kelvin."}, {"t0": 220.47, "t1": 227.37, "text": "Setelah semburan berhenti, panas sebesar 4,6 kelvin terbuang lewat outlet."}], [{"t0": 227.99, "t1": 231.24, "text": "Lalu siapa yang membuat front melebar?"}, {"t0": 231.24, "t1": 233.38, "text": "Saya periksa."}, {"t0": 233.38, "t1": 241.31, "text": "Dengan peta rekaman saja, front pada detik ke-240 setebal 2,5 milimeter."}, {"t0": 241.31, "t1": 246.0, "text": "Dengan exchange standar, 19,3."}, {"t0": 246.0, "t1": 249.3, "text": "Referensinya 4,5."}, {"t0": 249.3, "t1": 252.65, "text": "Jadi petanya baik-baik saja."}, {"t0": 252.65, "t1": 255.41, "text": "Exchange-lah penyebabnya."}]]}, {"title": "Kenapa tidak pakai difusi negatif saja?", "paras": [[{"t0": 256.67, "t1": 260.15, "text": "Pertanyaan klasik dari penguji."}, {"t0": 260.15, "t1": 262.94, "text": "Difusi menghaluskan."}, {"t0": 262.94, "t1": 267.89, "text": "Jadi kenapa tidak dijalankan mundur untuk mempertajam front?"}], [{"t0": 268.5, "t1": 271.89, "text": "Karena difusi negatif ill-posed."}, {"t0": 271.89, "t1": 278.6, "text": "Setiap gangguan kecil akan membesar, dan riak yang paling pendek tumbuh paling cepat."}, {"t0": 278.6, "t1": 283.2, "text": "Anda bisa menunjukkannya dengan satu Fourier mode."}, {"t0": 283.2, "t1": 292.89, "text": "Untuk langkah difusi eksplisit, faktor pertumbuhannya satu dikurangi empat nu kali sinus kuadrat k delta x per dua."}, {"t0": 292.89, "t1": 301.22, "text": "Untuk nu negatif dan mode terpendek, faktornya menjadi satu ditambah empat kali nilai mutlak nu."}, {"t0": 301.22, "t1": 307.26, "text": "Nilainya lebih dari satu, jadi riak itu tumbuh di setiap langkah."}, {"t0": 307.26, "t1": 315.66, "text": "Dalam uji satu dimensi saya, setelah 21 langkah, medannya sudah keluar dari rentang data."}], [{"t0": 316.28, "t1": 322.52, "text": "Jadi bagian yang berguna, yaitu penajaman, saya pertahankan."}, {"t0": 322.52, "t1": 327.0, "text": "Bagian yang berbahaya saya hentikan dengan limiter."}]]}, {"title": "Limiter", "paras": [[{"t0": 328.26, "t1": 335.34, "text": "Untuk setiap sel, ambil nilai terkecil dan terbesar di antara sel itu dan tetangganya."}, {"t0": 335.34, "t1": 338.3, "text": "Itulah batas lokalnya."}, {"t0": 338.3, "t1": 343.57, "text": "Headroom sel hangat adalah seberapa jauh ia masih boleh naik."}, {"t0": 343.57, "t1": 349.0, "text": "Headroom sel dingin adalah seberapa jauh ia masih boleh turun."}, {"t0": 349.0, "t1": 357.42, "text": "Lewat sebuah face, panas dipindahkan ke arah atas gradien, dari sel yang lebih dingin ke sel yang lebih hangat."}, {"t0": 357.42, "t1": 363.37, "text": "Jumlahnya adalah headroom yang lebih kecil, dikali kekuatan s."}], [{"t0": 363.99, "t1": 369.11, "text": "Dengan begitu, tidak ada sel yang keluar dari batasnya."}, {"t0": 369.11, "t1": 375.14, "text": "Nilai maksimum tidak bisa bertambah, nilai minimum tidak bisa turun."}, {"t0": 375.14, "t1": 383.07, "text": "Panas yang keluar dari satu sel masuk ke sel lainnya, jadi energi tetap terjaga di setiap face."}, {"t0": 383.07, "t1": 390.84, "text": "Ide ini berasal dari limiter flux-corrected transport, karya Boris dan Book, serta Zalesak."}], [{"t0": 391.44, "t1": 394.95, "text": "Ada juga satu batas yang rapi."}, {"t0": 394.95, "t1": 398.57, "text": "Sel heksahedral punya enam face."}, {"t0": 398.57, "t1": 406.81, "text": "Kalau s paling besar satu per enam, tidak ada sel yang bisa keluar dari batasnya bahkan sebelum clamp bekerja."}, {"t0": 406.81, "t1": 418.67, "text": "Rentang kerja saya, 0,40 sampai 0,50, berada di atas itu, jadi bergantung pada clamp dan conservation constraint global."}, {"t0": 418.67, "t1": 423.01, "text": "Sampaikan hal ini dengan jujur kalau ditanya."}]]}, {"title": "Kenapa ada bobot vertikal?", "paras": [[{"t0": 424.28, "t1": 427.01, "text": "Front-nya horizontal."}, {"t0": 427.01, "t1": 433.25, "text": "Jadi koreksi seharusnya bekerja melintasi front, bukan sepanjang front."}, {"t0": 433.25, "t1": 440.63, "text": "Setiap face mendapat bobot kosinus kuadrat dari sudut antara arah penghubungnya dan arah vertikal."}, {"t0": 440.63, "t1": 447.18, "text": "Face yang melintasi front mendapat bobot satu, face yang sejajar front mendapat nol."}, {"t0": 447.18, "t1": 452.61, "text": "Tanpa bobot ini, koreksi membuat front bergerigi ke samping."}, {"t0": 452.61, "t1": 460.66, "text": "Secara matematis, bobot ini persis koefisien face dari difusi yang hanya bekerja ke satu arah."}]]}, {"title": "Recorded diffusivity tidak membantu", "paras": [[{"t0": 461.93, "t1": 466.41, "text": "Satu hasil lagi yang harus bisa Anda jelaskan."}, {"t0": 466.41, "t1": 473.59, "text": "Saya juga mencoba recorded diffusivity yang bersifat lokal sebagai pengganti knob konstan."}, {"t0": 473.59, "t1": 479.04, "text": "Hasilnya tidak berubah, dan replay-nya identik sampai ke bit."}, {"t0": 479.04, "t1": 480.73, "text": "Kenapa?"}, {"t0": 480.73, "t1": 487.57, "text": "Nilai yang terekam meminta pertukaran lebih besar daripada yang bisa diberikan langkah eksplisit."}, {"t0": 487.57, "t1": 495.17, "text": "Setiap face mentok di batas atas, sehingga medannya berperilaku persis seperti setelan konstan."}, {"t0": 495.17, "t1": 501.67, "text": "Langkah waktu yang lebih pendek atau exchange implisit akan membuatnya bisa bekerja."}]]}, {"title": "Hasilnya", "paras": [[{"t0": 502.95, "t1": 512.92, "text": "Dengan koreksi, front di akhir run berubah dari 15,7 milimeter menjadi antara 5,3 dan 4,5."}, {"t0": 512.92, "t1": 516.26, "text": "Referensinya 5,0."}, {"t0": 516.26, "t1": 524.28, "text": "Galat suhu rata-rata sepanjang run turun dari 1,46 menjadi sekitar 0,7 kelvin."}, {"t0": 524.28, "t1": 532.13, "text": "Dan ingat kalimat jujurnya: kekuatan koreksi dipilih dengan membandingkan terhadap referensi yang sama."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 533.38, "t1": 535.33, "text": "Pertama."}, {"t0": 535.33, "t1": 543.76, "text": "Tidak ada setelan knob yang cocok untuk semua, karena outlet di bawah front membuang panas dari front yang melebar."}], [{"t0": 544.37, "t1": 546.05, "text": "Kedua."}, {"t0": 546.05, "t1": 549.71, "text": "Difusi negatif membuat riak tumbuh."}, {"t0": 549.71, "t1": 559.02, "text": "Limiter mempertahankan penajaman dan tetap di dalam batas tetangga, jadi tidak ada ekstrem baru dan tidak ada panas yang hilang."}], [{"t0": 559.63, "t1": 561.38, "text": "Ketiga."}, {"t0": 561.38, "t1": 571.45, "text": "15,7 milimeter menjadi sekitar 5, referensinya 5,0, dan kekuatannya dipilih dengan referensi."}]]}]}, {"id": "T3-id", "group": "T-id", "title": "T3 · Tutup dingin, batas metode, dan bagaimana saya tahu hasilnya benar", "file": "tracks/T3-id.mp3", "voice": "Gadis", "duration": 538.0, "sections": [{"title": "", "paras": [[{"t0": 0.05, "t1": 6.63, "text": "Tutup dingin, batas metode, dan bagaimana saya tahu hasilnya benar."}], [{"t0": 7.22, "t1": 13.99, "text": "Di episode ini kita masuk ke separuh tesis yang lebih sulit: tutup yang didinginkan."}, {"t0": 13.99, "t1": 20.32, "text": "Setelah itu kita latih pertanyaan yang hampir selalu ditanyakan di akhir sidang."}, {"t0": 20.32, "t1": 23.84, "text": "Bagaimana Anda tahu hasilnya benar?"}, {"t0": 23.84, "t1": 27.78, "text": "Apa yang akan Anda lakukan secara berbeda?"}, {"t0": 27.78, "t1": 31.53, "text": "Dan paper mana yang paling mempengaruhi Anda?"}]]}, {"title": "Ketika tutupnya menjadi dingin", "paras": [[{"t0": 32.78, "t1": 36.36, "text": "Sejauh ini tutupnya terisolasi."}, {"t0": 36.36, "t1": 41.94, "text": "Panas masuk bersama semburan dan keluar lewat outlet, hanya itu."}, {"t0": 41.94, "t1": 47.65, "text": "Sekarang tutupnya melepas panas ke luar, dan fisikanya berubah."}, {"t0": 47.65, "t1": 54.5, "text": "Air dingin terbentuk di bawah tutup, lebih berat, lalu turun dalam bentuk plume."}, {"t0": 54.5, "t1": 58.21, "text": "Lapisan di atas front mulai berputar."}, {"t0": 58.21, "t1": 63.42, "text": "Artinya, suhu sekarang menciptakan gerakannya sendiri."}, {"t0": 63.42, "t1": 71.59, "text": "Umpan balik seperti inilah yang tidak bisa ditiru replay, karena gerakannya sudah terkunci dalam rekaman."}], [{"t0": 72.19, "t1": 78.28, "text": "Setiap replay di bab ini memakai sifat fluida yang sama dengan referensi."}, {"t0": 78.28, "t1": 85.55, "text": "Siapkan kalimat ini, karena kalimat ini menutup satu kelompok pertanyaan sekaligus."}]]}, {"title": "Apa yang sudah benar dalam replay", "paras": [[{"t0": 86.81, "t1": 93.03, "text": "Sepanjang run, tangki mendingin sebesar 9,62 kelvin."}, {"t0": 93.03, "t1": 98.54, "text": "Replay standar berakhir 0,66 kelvin terlalu dingin."}, {"t0": 98.54, "t1": 104.37, "text": "Kedengarannya kecil, dan memang kecil, untuk kandungan panasnya."}, {"t0": 104.37, "t1": 107.6, "text": "Tetapi lihat letak panasnya."}, {"t0": 107.6, "t1": 117.56, "text": "Profil akhir replay standar menyimpang 2,79 kelvin: bagian tengah terlalu hangat, lapisan atas terlalu dingin."}, {"t0": 117.56, "t1": 121.47, "text": "Panasnya sama, tempatnya salah."}], [{"t0": 122.11, "t1": 143.41, "text": "Dengan koreksi, pada kekuatan antara 0,475 dan 0,55, galat akhir kandungan panas berada antara minus 0,04 dan plus 0,06 kelvin, dan profil akhirnya membaik menjadi antara 0,59 dan 0,41 kelvin."}, {"t0": 143.41, "t1": 147.94, "text": "Jadi koreksi mengembalikan panas ke lapisan yang benar."}, {"t0": 147.94, "t1": 155.19, "text": "Sekali lagi, sampaikan dengan jujur: kekuatan ini dipilih dengan referensi."}], [{"t0": 155.8, "t1": 160.79, "text": "Karena itulah saya selalu melaporkan dua jenis ukuran."}, {"t0": 160.79, "t1": 165.35, "text": "Suhu rata-rata menunjukkan berapa banyak panasnya."}, {"t0": 165.35, "t1": 170.39, "text": "Profil dan lebar front menunjukkan di mana panas itu berada."}, {"t0": 170.39, "t1": 176.19, "text": "Sebuah replay bisa benar di satu ukuran dan salah di ukuran lainnya."}]]}, {"title": "Apa yang tidak bisa diperbaiki", "paras": [[{"t0": 177.45, "t1": 180.54, "text": "Sekarang cacat yang tersisa."}, {"t0": 180.54, "t1": 186.27, "text": "Selama tangki terisi, lapisan-lapisannya terpisah terlalu lambat."}, {"t0": 186.27, "t1": 193.41, "text": "Saya mencoba enam varian koreksi lokal, dan tidak satu pun mengubah keterlambatan ini."}, {"t0": 193.41, "t1": 195.11, "text": "Kenapa?"}], [{"t0": 195.71, "t1": 199.49, "text": "Cara paling bersih menjelaskannya begini."}, {"t0": 199.49, "t1": 204.45, "text": "Koreksi lokal hanya memindahkan panas antar tetangga."}, {"t0": 204.45, "t1": 212.77, "text": "Ia bisa mengubah bentuk front, tetapi tidak bisa membawa panas dari satu lapisan ke lapisan lain yang jauh."}, {"t0": 212.77, "t1": 215.43, "text": "Itu namanya transport."}, {"t0": 215.43, "t1": 222.08, "text": "Jadi keterlambatan ini adalah kekurangan transport, bukan kekurangan ketajaman."}], [{"t0": 222.69, "t1": 226.81, "text": "Lalu saya mencoba menyediakan transport itu."}, {"t0": 226.81, "t1": 239.42, "text": "Selama perekaman, saya menyimpan vertical heat flux, yaitu bagian panas yang dibawa oleh kecepatan vertikal, relatif terhadap rata-rata satu pita horizontal."}, {"t0": 239.42, "t1": 243.64, "text": "Dalam replay, flux itu saya terapkan."}, {"t0": 243.64, "t1": 252.48, "text": "Hasilnya bekerja: keterlambatan pelapisan turun dari 2,25 menjadi 0,45 kelvin."}, {"t0": 252.48, "t1": 255.26, "text": "Tetapi ada harganya."}, {"t0": 255.26, "t1": 260.97, "text": "Tangki kemudian berakhir 0,86 kelvin terlalu dingin."}]]}, {"title": "Kenapa rekaman tidak bisa melakukannya sendiri", "paras": [[{"t0": 262.24, "t1": 266.93, "text": "Bagian terakhir dari cerita ini adalah flow regime."}, {"t0": 266.93, "t1": 272.73, "text": "Bandingkan seberapa cepat masing-masing rekaman berubah dalam selang waktu pendek."}, {"t0": 272.73, "t1": 284.07, "text": "Setelah semburan berhenti, aliran dengan tutup dingin terus memperbarui dirinya, kira-kira sepuluh kali lebih cepat daripada aliran dengan tutup terisolasi."}, {"t0": 284.07, "t1": 291.17, "text": "Jadi rekaman yang dibuat tanpa tutup dingin memang tidak berisi gerakan kasus yang didinginkan."}, {"t0": 291.17, "t1": 297.98, "text": "Sebuah database berlaku untuk satu flow regime, bukan untuk satu kasus."}, {"t0": 297.98, "t1": 304.7, "text": "Dalam bahasa machine learning: regime baru berarti out of distribution."}]]}, {"title": "Bagaimana Anda tahu hasilnya benar?", "paras": [[{"t0": 305.97, "t1": 310.46, "text": "Pertanyaan ini pernah muncul di sidang sebelumnya."}, {"t0": 310.46, "t1": 313.69, "text": "Jawab dengan tiga poin singkat."}], [{"t0": 314.29, "t1": 318.99, "text": "Pertama, setiap replay bersifat deterministik."}, {"t0": 318.99, "t1": 323.94, "text": "Kalau dijalankan ulang, hasilnya sama sampai ke bit."}, {"t0": 323.94, "t1": 330.28, "text": "Jadi perbedaan antara dua run pasti berasal dari satu setelan yang saya ubah."}], [{"t0": 330.9, "t1": 345.43, "text": "Kedua, replay dan referensi saya bandingkan pada waktu yang sama, dan pada jendela akhir yang sama, dari detik 580 sampai 599, di kedua sisi."}], [{"t0": 346.04, "t1": 352.65, "text": "Ketiga, neraca energi setiap kasus saya tutup, suku demi suku."}, {"t0": 352.65, "t1": 358.88, "text": "Kalau panasnya tidak cocok, saya sudah tahu sebelum menafsirkan apa pun."}]]}, {"title": "Kenapa bias dan RMSE?", "paras": [[{"t0": 360.15, "t1": 367.47, "text": "Pada sebuah trace, bias memberi tahu arah galat, terlalu hangat atau terlalu dingin."}, {"t0": 367.47, "t1": 371.28, "text": "Root mean square error memberi tahu besarnya."}, {"t0": 371.28, "t1": 376.55, "text": "Ada identitas rapi yang bisa Anda turunkan di papan tulis."}, {"t0": 376.55, "t1": 382.35, "text": "RMSE kuadrat sama dengan bias kuadrat ditambah variansi galat."}, {"t0": 382.35, "t1": 387.8, "text": "Jadi identitas ini memisahkan pergeseran dari bentuk yang salah."}]]}, {"title": "Dua pemeriksaan fisika", "paras": [[{"t0": 389.07, "t1": 391.99, "text": "Kenapa alirannya laminar?"}, {"t0": 391.99, "t1": 404.51, "text": "Semburan masuk dengan kecepatan 0,02 meter per detik lewat lubang lima milimeter, sehingga bilangan Reynolds sekitar 99, jauh di bawah transisi."}, {"t0": 404.51, "t1": 416.86, "text": "Bilangan Richardson-nya 1,84: gaya apung sedikit lebih kuat daripada inersia, jadi semburan membelok ke atas dalam jarak beberapa kali lebar inlet."}], [{"t0": 417.46, "t1": 421.37, "text": "Kenapa memakai Boussinesq approximation?"}, {"t0": 421.37, "t1": 426.0, "text": "Densitas hanya berubah sedikit pada rentang suhu ini."}, {"t0": 426.0, "t1": 432.84, "text": "Jadi densitas dianggap konstan di mana-mana, kecuali pada suku gravitasi."}, {"t0": 432.84, "t1": 441.37, "text": "Dan ada kaitan yang bagus dengan tesis: suku gaya apung itulah tepatnya hubungan yang diputus oleh replay."}]]}, {"title": "Apa yang akan Anda lakukan berbeda? Future work", "paras": [[{"t0": 442.64, "t1": 444.53, "text": "Tiga hal."}, {"t0": 444.53, "t1": 452.39, "text": "Biarkan recorded diffusivity bekerja, dengan exchange implisit atau langkah waktu yang lebih pendek."}, {"t0": 452.39, "t1": 460.68, "text": "Bagi conservation constraint menjadi beberapa kompartemen, supaya tidak mendorong panas kembali ke front."}, {"t0": 460.68, "t1": 470.54, "text": "Dan gunakan beberapa rekaman, dipilih berdasarkan keadaan suhu yang sedang di-replay, supaya lebih dari satu regime tercakup."}]]}, {"title": "Paper mana yang paling mempengaruhi Anda?", "paras": [[{"t0": 471.8, "t1": 480.76, "text": "Lichtenegger dan Pirker, 2016, yang memperkenalkan recurrence CFD dan recurrence matrix."}, {"t0": 480.76, "t1": 488.48, "text": "Pirker dan rekan, 2018, untuk face exchange dan conservation constraint."}, {"t0": 488.48, "t1": 497.88, "text": "Dan Zalesak, 1979, untuk batas lokal flux-corrected transport yang dipakai limiter saya."}]]}, {"title": "Tiga hal untuk diingat", "paras": [[{"t0": 499.13, "t1": 501.07, "text": "Pertama."}, {"t0": 501.07, "t1": 510.23, "text": "Dengan tutup dingin, kandungan panasnya benar, tetapi lapisan terpisah terlalu lambat: itu kekurangan transport."}], [{"t0": 510.84, "t1": 512.52, "text": "Kedua."}, {"t0": 512.52, "t1": 525.08, "text": "Recorded flux menurunkan keterlambatan dari 2,25 menjadi 0,45 kelvin, tetapi tangki lalu berakhir 0,86 kelvin terlalu dingin."}], [{"t0": 525.67, "t1": 527.43, "text": "Ketiga."}, {"t0": 527.43, "t1": 537.94, "text": "Saya tahu hasilnya benar karena replay deterministik, satu perubahan per run, waktu pembanding yang sama, dan neraca energi yang tertutup."}]]}]}]};
